class TestHotkey:
    def test_manifest_has_save_tab_command(self):
        m = json.load(open(f"{EXT_PATH}/manifest.json"))
        cmd = m["commands"]["save-tab"]
        assert cmd["suggested_key"]["default"] == "Ctrl+Shift+S"
        assert cmd["description"] == "__MSG_cmdSaveTab__"

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        page.goto("about:blank")
        page.evaluate(MOCK_CHROME)
        page.evaluate(load_file("background.js") + "; 'loaded'")
        self.page = page

    def _fire_command(self, command):
        self.page.evaluate(f"""(() => {{
          chrome.commands.onCommand._listeners.forEach(fn => fn({json.dumps(command)}));
        }})()""")

    def test_on_command_save_tab_saves_active_tab(self):
        self._fire_command("save-tab")
        self.page.wait_for_timeout(100)
        tabs = read_storage_raw(self.page, "blattam-tabs")
        sps = read_storage_raw(self.page, "blattam-spaces")
        assert len(tabs) == 1
        assert tabs[0]["url"] == "https://example.com"
        assert tabs[0]["name"] == "Example Domain"
        assert tabs[0]["spaceId"] == sps[0]["id"]
        assert "folderId" not in tabs[0]

    def test_on_command_skips_chrome_urls(self):
        self.page.evaluate("chrome.tabs._currentTab.url = 'chrome://settings'")
        self._fire_command("save-tab")
        self.page.wait_for_timeout(100)
        assert read_storage_raw(self.page, "blattam-tabs") == []

    def test_on_command_ignores_other_commands(self):
        self._fire_command("some-other-command")
        self.page.wait_for_timeout(100)
        assert read_storage_raw(self.page, "blattam-tabs") == []


# ==========================================
#  OPERA STARTPAGE → view.html (runtime newtab-перехват)
# ==========================================

class TestOperaStartpage:
    """Opera не поддерживает chrome_url_overrides.newtab из манифеста — её
    new tab это фирменный startpage (chrome://startpage). background.js
    перехватывает его: вкладка со startpage (onCreated / onUpdated complete)
    → chrome.tabs.update → view.html. В Chrome это no-op (такой URL там не
    встречается)."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        page.goto("about:blank")
        page.evaluate(MOCK_CHROME)
        page.evaluate(load_file("background.js") + "; 'loaded'")

    def _fire_created(self, tab):
        self.page.evaluate("chrome.tabs.onCreated._fire(%s)" % json.dumps(tab))

    def _fire_updated(self, tab_id, change_info, tab):
        self.page.evaluate(
            "chrome.tabs.onUpdated._fire(%s, %s, %s)"
            % (json.dumps(tab_id), json.dumps(change_info), json.dumps(tab)))

    def _last_update(self):
        return self.page.evaluate("chrome.tabs._lastUpdate")

    def test_on_created_startpage_redirects_to_view(self):
        self._fire_created({"id": 42, "url": "chrome://startpage/"})
        lu = self._last_update()
        assert lu is not None
        assert lu["tabId"] == 42
        assert lu["opts"]["url"] == "chrome-extension://mock-extension-id/view.html"

    def test_on_updated_complete_startpage_redirects(self):
        self._fire_updated(7, {"status": "complete"}, {"id": 7, "url": "chrome://startpage"})
        lu = self._last_update()
        assert lu is not None
        assert lu["tabId"] == 7
        assert lu["opts"]["url"] == "chrome-extension://mock-extension-id/view.html"

    def test_opera_scheme_startpage_redirects(self):
        self._fire_created({"id": 3, "url": "opera://startpage"})
        assert self._last_update()["opts"]["url"] == "chrome-extension://mock-extension-id/view.html"

    def test_pending_startpage_redirects(self):
        self._fire_created({"id": 5, "url": "", "pendingUrl": "chrome://startpage/"})
        assert self._last_update()["opts"]["url"] == "chrome-extension://mock-extension-id/view.html"

    def test_normal_tab_not_redirected(self):
        self._fire_created({"id": 9, "url": "https://example.com"})
        assert self._last_update() is None

    def test_on_updated_loading_not_redirected(self):
        self._fire_updated(11, {"status": "loading", "url": "chrome://startpage/"}, {"id": 11, "url": "chrome://startpage/", "status": "loading"})
        assert self._last_update() is None

    def test_chrome_newtab_not_redirected(self):
        self._fire_updated(12, {"status": "complete"}, {"id": 12, "url": "chrome://newtab/"})
        assert self._last_update() is None

    def test_startup_sweep_redirects_loaded_startpage(self):
        # SW может стартовать ПОСЛЕ создания startpage-вкладки (первая вкладка
        # Opera при запуске) — sweep при старте SW (chrome.tabs.query) ловит её.
        self.page.goto("about:blank")
        self.page.evaluate(MOCK_CHROME)
        self.page.evaluate("Object.defineProperty(navigator, 'userAgent', {configurable: true, value: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36 OPR/94.0.0.0'})")
        self.page.evaluate(
            "chrome.tabs._tabs = ["
            "{id: 21, url: 'chrome://startpage/', windowId: 1, index: 0}, "
            "{id: 22, url: 'https://example.com', windowId: 1, index: 1}];")
        self.page.evaluate(load_file("background.js") + "; 'loaded'")
        self.page.wait_for_timeout(100)
        lu = self._last_update()
        assert lu is not None
        assert lu["tabId"] == 21
        assert lu["opts"]["url"] == "chrome-extension://mock-extension-id/view.html"

    def test_startup_sweep_noop_when_no_startpage(self):
        self.page.goto("about:blank")
        self.page.evaluate(MOCK_CHROME)
        self.page.evaluate("Object.defineProperty(navigator, 'userAgent', {configurable: true, value: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36 OPR/94.0.0.0'})")
        self.page.evaluate(
            "chrome.tabs._tabs = [{id: 31, url: 'https://example.com', windowId: 1, index: 0}];")
        self.page.evaluate(load_file("background.js") + "; 'loaded'")
        self.page.wait_for_timeout(100)
        assert self._last_update() is None

class TestSweepOperaOnly:
    """Стартовый sweep (скан startpage-вкладок при старте SW, 20 x chrome.tabs.query)
    по 500 мс) работает только в Opera (userAgent содержит OPR/): в Chrome на
    старте SW холостых запросов нет (С3.14). Перехват startpage-вкладок по событиям
    onCreated/onUpdated остаётся безусловным — в Chrome это no-op (startpage-URL
    не встречается)."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        page.goto("about:blank")
        page.evaluate(MOCK_CHROME)

    def _fire_created(self, tab):
        self.page.evaluate("chrome.tabs.onCreated._fire(%s)" % json.dumps(tab))

    def _last_update(self):
        return self.page.evaluate("chrome.tabs._lastUpdate")

    def test_sweep_inactive_without_opera_ua(self):
        self.page.evaluate(
            "chrome.tabs._tabs = [{id: 41, url: 'chrome://startpage/', windowId: 1, index: 0}];")
        self.page.evaluate(load_file("background.js") + "; 'loaded'")
        self.page.wait_for_timeout(700)
        assert self._last_update() is None

    def test_event_hijack_still_works_without_opera_ua(self):
        self.page.evaluate(load_file("background.js") + "; 'loaded'")
        self._fire_created({"id": 51, "url": "chrome://startpage/"})
        lu = self._last_update()
        assert lu is not None
        assert lu["opts"]["url"] == "chrome-extension://mock-extension-id/view.html"

class TestRailMirrorIncognito:
    """Зеркало вкладок браузера (правая рейка newtab-страницы,
    storage.local 'blattam-browser-tabs') не включает инкогнито-вкладки —
    refreshBrowserTabsMirror фильтрует их по !t.incognito (С3.12).
    Исключение вкладок самой newtab-страницы (view.html) сохранено."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        page.goto("about:blank")
        page.evaluate(MOCK_CHROME)

    def _seed(self, tabs):
        self.page.evaluate("chrome.tabs._tabs = %s;" % json.dumps(tabs))
        self.page.evaluate(load_file("background.js") + "; 'loaded'")
        self.page.wait_for_timeout(300)

    def _mirror(self):
        raw = self.page.evaluate(
            "JSON.stringify(chrome.storage.local._data['blattam-browser-tabs'])")
        return json.loads(raw) if raw else []
    def test_incognito_tab_excluded_from_mirror(self):
        self._seed([
            {"id": 101, "title": "Normal", "url": "https://n.com",
             "favIconUrl": "", "windowId": 1, "index": 0},
            {"id": 102, "title": "Secret", "url": "https://s.com",
             "favIconUrl": "", "windowId": 1, "index": 1, "incognito": True},
        ])
        mirror = self._mirror()
        assert any(t["id"] == 101 for t in mirror)
        assert not any(t["id"] == 102 for t in mirror)

    def test_regular_tab_still_mirrored(self):
        self._seed([
            {"id": 101, "title": "Normal", "url": "https://n.com",
             "favIconUrl": "", "windowId": 1, "index": 0},
        ])
        rec = next(t for t in self._mirror() if t["id"] == 101)
        assert rec["title"] == "Normal"
        assert rec["url"] == "https://n.com"
        assert rec["windowId"] == 1
        assert rec["index"] == 0

    def test_newtab_page_still_excluded(self):
        self._seed([
            {"id": 104, "url": "chrome-extension://mock-extension-id/view.html",
             "windowId": 1, "index": 0},
        ])
        assert self._mirror() == []

    def test_incognito_excluded_after_tab_event(self):
        self._seed([
            {"id": 101, "title": "Normal", "url": "https://n.com",
             "favIconUrl": "", "windowId": 1, "index": 0},
        ])
        tab = {"id": 103, "url": "https://inc.com", "title": "I",
               "favIconUrl": "", "windowId": 1, "index": 1, "incognito": True}
        self.page.evaluate(
            "chrome.tabs._tabs.push(%s); chrome.tabs.onCreated._fire(%s);"
            % (json.dumps(tab), json.dumps(tab)))
        self.page.wait_for_timeout(300)
        mirror = self._mirror()
        assert any(t["id"] == 101 for t in mirror)
        assert not any(t["id"] == 103 for t in mirror)

# ==========================================
#  СРЕДНИЙ КЛИК ПО КАРТОЧКЕ — фоновая вкладка
# ==========================================

class TestMiddleClickBackgroundOpen:
    """Средний клик (колесо) по сохранённой вкладке — сайт открывается новой
    фоновой вкладкой (chrome.tabs.create, active:false), страница плагина
    остаётся активной. Левый клик (open-one, active:true) не тронут."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page

    def test_middle_click_opens_background_tab(self):
        load_view(self.page, tabs=[{"name": "A", "url": "https://a.com"}])
        self.page.locator(".tab-card").click(button="middle")
        last = json.loads(self.page.evaluate("JSON.stringify(window.lastTabCreated)"))
        assert last == {"url": "https://a.com", "active": False}

    def test_middle_click_single_open_no_left_path(self):
        load_view(self.page, tabs=[{"name": "A", "url": "https://a.com"},
                                   {"name": "B", "url": "https://b.com"}])
        self.page.locator(".tab-card").nth(1).click(button="middle")
        assert self.page.evaluate("chrome.tabs.createdTabs.length") == 1
        last = json.loads(self.page.evaluate("JSON.stringify(window.lastTabCreated)"))
        assert last["url"] == "https://b.com"
        assert last["active"] is False
        msg = self.page.evaluate("window.lastMessage && window.lastMessage.action")
        assert msg != "open-one"

    def test_middle_click_mousedown_autoscroll_prevented(self):
        load_view(self.page, tabs=[{"name": "A", "url": "https://a.com"}])
        self.page.evaluate("""
          window.__mdPrevented = null;
          document.addEventListener('mousedown', (e) => {
            if (e.button === 1 && e.target.closest('.tab-card')) {
              window.__mdPrevented = e.defaultPrevented;
            }
          }, false);
        """)
        self.page.locator(".tab-card").click(button="middle")
        assert self.page.evaluate("window.__mdPrevented") is True

    def test_middle_click_on_name_opens_background(self):
        load_view(self.page, tabs=[{"name": "Wiki", "url": "https://wiki.example"}])
        self.page.locator(".tab-card .tab-name").click(button="middle")
        last = json.loads(self.page.evaluate("JSON.stringify(window.lastTabCreated)"))
        assert last == {"url": "https://wiki.example", "active": False}
        assert self.page.locator(".tab-card .tab-name").inner_text() == "Wiki"

    def test_middle_click_on_hover_buttons_no_open(self):
        load_view(self.page, tabs=[{"name": "A", "url": "https://a.com"}])
        self.page.locator(".tab-card").hover()
        for sel in (".tab-select", ".tab-remove", ".tab-edit"):
            self.page.locator(sel).first.click(button="middle")
        assert self.page.evaluate("chrome.tabs.createdTabs.length") == 0

    def test_middle_click_left_click_unchanged(self):
        load_view(self.page, tabs=[{"name": "A", "url": "https://a.com"}])
        self.page.locator(".tab-card").click()
        msg = json.loads(self.page.evaluate("JSON.stringify(window.lastMessage)"))
        assert msg["action"] == "open-one"
        last = json.loads(self.page.evaluate("JSON.stringify(window.lastTabCreated)"))
        assert last["active"] is True

# ==========================================
#  РЕЛИЗ: zip-сборка, иконки, описание магазина
# ==========================================

class TestRelease:
    EXPECTED_MEMBERS = {
        "manifest.json",
        "background.js",
        "popup.html",
        "popup.js",
        "i18n.js",
        "view.html",
        "view.js",
        "theme.css",
        "oauth-callback.html",
        "oauth-callback.js",
        "_locales/ru/messages.json",
        "_locales/en/messages.json",
        "icons/icon16.png",
        "icons/icon48.png",
        "icons/icon128.png",
    }
    EXCLUDED = ("test_plugin.py", "build_zip.py", "QWEN.md", "ROADMAP.md",
                "dist", ".git", ".pytest_cache", "__pycache__", "sketches")

    def _run_build(self):
        spec = importlib.util.spec_from_file_location("build_zip", f"{EXT_PATH}/build_zip.py")
        bz = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(bz)
        bz.main()
        return os.path.join(EXT_PATH, "dist", "BlatTabs-v%s.zip" % bz.read_version())

    @staticmethod
    def _png_size(path):
        with open(path, "rb") as f:
            head = f.read(24)
        assert head[:8] == b"\x89PNG\r\n\x1a\n", "not a PNG"
        w, h = struct.unpack(">II", head[16:24])
        return w, h

    def test_build_zip_members_exact(self):
        zip_path = self._run_build()
        assert os.path.isfile(zip_path), f"zip not created: {zip_path}"
        with zipfile.ZipFile(zip_path) as zf:
            names = set(zf.namelist())
            assert names == self.EXPECTED_MEMBERS, f"unexpected members: {names ^ self.EXPECTED_MEMBERS}"
            for bad in self.EXCLUDED:
                for n in names:
                    assert bad not in n.replace(os.sep, "/"), f"excluded file leaked: {n}"
            manifest = json.loads(zf.read("manifest.json").decode("utf-8"))
            assert "icons" in manifest
            for px in ("16", "48", "128"):
                icon = manifest["icons"][px]
                assert icon in names, f"icon {icon} (size {px}) missing from zip"

    def test_icon_pixel_sizes(self):
        for px in (16, 48, 128):
            path = os.path.join(EXT_PATH, "icons", f"icon{px}.png")
            assert os.path.isfile(path), f"missing {path}"
            w, h = self._png_size(path)
            assert (w, h) == (px, px), f"icon{px}.png is {w}x{h}, expected {px}x{px}"

    def test_description_has_short(self):
        path = os.path.join(EXT_PATH, "store", "DESCRIPTION.md")
        assert os.path.isfile(path), "missing store/DESCRIPTION.md"
        text = open(path, "r", encoding="utf-8").read()
        assert "Короткое описание" in text, "no short-description section"
        rest = text[text.index("Короткое описание"):]
        short = ""
        for ln in rest.split("\n"):
            ln = ln.strip()
            if ln and not ln.startswith("##") and "Короткое описание" not in ln:
                short = ln
                break
        assert short, "empty short description"
        assert len(short) <= 132, f"short description too long ({len(short)} > 132)"
        assert "Ctrl+T" in short, "short description should mention Ctrl+T"


