#  VIEW.JS: ☑ «Без группы» — ВЫБОР ВСЕХ НЕГРУППОВЫХ ВКЛАДОК ПРОСТРАНСТВА
# ==========================================

class TestLooseSelectAll:
    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page

    SP = [{"id": "sp1", "name": "Main"}]
    GROUPS = [{"id": "g1", "name": "Dev", "spaceId": "sp1", "collapsed": False}]
    TABS = [
        {"name": "D1", "url": "https://d1.com", "spaceId": "sp1", "groupId": "g1"},
        {"name": "D2", "url": "https://d2.com", "spaceId": "sp1", "groupId": "g1"},
        {"name": "L Alpha", "url": "https://la.com", "spaceId": "sp1"},
        {"name": "L Beta", "url": "https://lb.com", "spaceId": "sp1"},
    ]

    def _load(self):
        load_view(self.page, spaces=self.SP, groups=self.GROUPS, tabs=self.TABS)

    def _click(self):
        self.page.evaluate("document.querySelector('.loose-label .loose-select').click()")

    def test_loose_label_rendered_with_select_button(self):
        # Подпись «Без группы» рендерится (группы И негрупповые есть) с кнопкой ☑,
        # в неактивном состоянии
        self._load()
        d = self.page.evaluate("""(() => {
          const lbl = document.querySelector('.loose-label');
          if (!lbl) return null;
          const btn = lbl.querySelector('.loose-select');
          if (!btn) return null;
          return {text: lbl.textContent, glyph: btn.textContent,
                  on: btn.classList.contains('on')};
        })()""")
        assert d is not None
        assert d["glyph"] == "\u2611"
        assert "Без группы" in d["text"]
        assert d["on"] is False

    def test_click_selects_all_loose_tabs_only(self):
        self._load()
        self._click()
        d = json.loads(self.page.evaluate("""(() => {
          const sel = [...document.querySelectorAll('.tab-card.selected')].map(c => c.__tab.url);
          return JSON.stringify({sel,
            barHidden: document.getElementById('selection-bar').classList.contains('hidden'),
            count: document.getElementById('selection-count').textContent});
        })()"""))
        # Выделены ТОЛЬКО негрупповые вкладки; батч-бар виден со счётчиком
        assert sorted(d["sel"]) == ["https://la.com", "https://lb.com"], d
        assert d["barHidden"] is False
        assert d["count"] == "2 выбрано"

    def test_second_click_deselects_all(self):
        self._load()
        self._click()
        self._click()
        assert self.page.evaluate("document.querySelectorAll('.tab-card.selected').length") == 0
        assert self.page.evaluate("document.getElementById('selection-bar').classList.contains('hidden')") is True
        assert not self.page.evaluate("document.querySelector('.loose-label .loose-select').classList.contains('on')")

    def test_button_on_when_all_loose_selected(self):
        # Все негрупповые выделены — кнопка в активном (заполненном) состоянии
        self._load()
        self._click()
        assert self.page.evaluate("document.querySelector('.loose-label .loose-select').classList.contains('on')")

    def test_selection_covers_full_loose_set_under_filter(self):
        # Поиск сужает видимые негрупповые карточки до одной — клик по ☑ всё равно
        # выделяет ПОЛНЫЙ набор негрупповых вкладок пространства, а не видимые
        self._load()
        self.page.evaluate("""(() => {
          const inp = document.getElementById('search');
          inp.value = 'Alpha';
          inp.dispatchEvent(new Event('input', {bubbles: true}));
        })()""")
        assert self.page.evaluate("document.querySelectorAll('.tab-card').length") == 1
        self._click()
        assert self.page.evaluate("document.getElementById('selection-count').textContent") == "2 выбрано"
        # Снимаем фильтр — обе негрупповые вкладки стоят выделенными
        self.page.evaluate("""(() => {
          const inp = document.getElementById('search');
          inp.value = '';
          inp.dispatchEvent(new Event('input', {bubbles: true}));
        })()""")
        d = json.loads(self.page.evaluate("""(() => {
          const sel = [...document.querySelectorAll('.tab-card.selected')].map(c => c.__tab.url);
          return JSON.stringify({sel});
        })()"""))
        assert sorted(d["sel"]) == ["https://la.com", "https://lb.com"], d



class TestDragRowKeeper:
    """Строки секции при драге: схваченная карточка выдергивается из сетки
    (display:none), а тёплая ghost-slot занимает её клетку. Условный
    row-keeper подключается только когда заглушка уезжает ИЗ исходной
    секции И число строк секции при этом уменьшается (TestDragSourceRowHold);
    в лейаутах ниже строки не схлопываются — .tab-row-keeper в DOM нет.
    На dragend — без следов."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page

    SP = [{"id": "sp1", "name": "Main"}]
    TABS3 = [
        {"name": "A", "url": "https://a.com", "spaceId": "sp1"},
        {"name": "B", "url": "https://b.com", "spaceId": "sp1"},
        {"name": "C", "url": "https://c.com", "spaceId": "sp1"},
    ]

    def _start_drag(self, idx):
        self.page.evaluate("""(idx) => {
          const card = document.querySelectorAll('#tabs-list .tab-card')[idx];
          window.__srcCard = card;
          const dt = new DataTransfer();
          window.__dt = dt;
          card.dispatchEvent(new DragEvent('dragstart',
            {dataTransfer: dt, bubbles: true, cancelable: true}));
        }""", idx)
        self.page.wait_for_timeout(50)  # отложенное создание ghost-slot

    def _dragover_card(self, idx):
        self.page.evaluate("""(idx) => {
          const card = document.querySelectorAll('#tabs-list .tab-card')[idx];
          const r = card.getBoundingClientRect();
          card.dispatchEvent(new DragEvent('dragover', {
            dataTransfer: window.__dt, bubbles: true, cancelable: true,
            clientX: r.left + r.width / 2, clientY: r.top + r.height / 2
          }));
        }""", idx)

    def _end_drag(self):
        self.page.evaluate("""(() => {
          const card = window.__srcCard;
          if (card) card.dispatchEvent(new DragEvent('dragend',
            {bubbles: true, cancelable: true}));
        })()""")

    def _anchor_top(self):
        return self.page.evaluate(
            "document.getElementById('tabs-list').getBoundingClientRect().bottom")

    def _inject_css(self):
        css = load_file("theme.css")
        html = load_file("view.html")
        style_block = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate("""(css) => {
          const s = document.createElement('style');
          s.textContent = css;
          document.head.appendChild(s);
        }""", css + style_block)

    def test_no_keeper_rows_fixed_when_ghost_stays_in_section(self):
        # Ghost ушёл от дома (в начало списка), но остаётся В СЕКЦИИ:
        # .tab-row-keeper в DOM нет, схваченная карточка (C) выдернута из
        # сетки (display:none) — число строк секции постоянно, якорь под
        # списком не сдвинулся
        load_view(self.page, spaces=self.SP, tabs=self.TABS3)
        self._inject_css()  # реальная сетка: 3 карточки = одна строка
        self.page.set_viewport_size({"width": 1280, "height": 800})
        self.page.wait_for_timeout(50)
        # указатель в нейтральный угол: :hover карточки (translateY(-1px)) не
        # должен смещать строки под измерением (физическая позиция мыши
        # живёт между тестами на общей странице)
        self.page.mouse.move(0, 0)
        self.page.wait_for_timeout(200)
        pre = self._anchor_top()
        c_before = json.loads(self.page.evaluate("""(() => {
          const b = document.querySelectorAll('#tabs-list .tab-card')[2].getBoundingClientRect();
          return JSON.stringify({left: b.left, top: b.top});
        })()"""))
        self._start_drag(2)
        self._dragover_card(0)
        d = json.loads(self.page.evaluate("""(() => {
          const src = window.__srcCard;
          const slot = document.querySelector('.tab-ghost-slot');
          const b = document.querySelectorAll('#tabs-list .tab-card')[1];
          const bb = b.getBoundingClientRect();
          return JSON.stringify({
            keepers: document.querySelectorAll('.tab-row-keeper').length,
            srcDisplay: src.style.display,
            srcOpacity: getComputedStyle(src).opacity,
            slotAtStart: document.getElementById('tabs-list').firstElementChild === slot,
            bLeft: bb.left, bTop: bb.top,
            top: document.getElementById('tabs-list').getBoundingClientRect().bottom
          });
        })()"""))
        assert d["keepers"] == 0, d
        assert d["srcDisplay"] == "none" and d["srcOpacity"] == "1", d  # C выдернута, непрозрачна
        assert d["slotAtStart"], d  # заглушка в начале списка (до A)
        # заглушка в начале строки сдвинула A и B вправо: B заняла клетку C —
        # число строк секции не изменилось, C выдернута (display:none)
        assert abs(d["bLeft"] - c_before["left"]) < 2 and abs(d["bTop"] - c_before["top"]) < 2, (c_before, d)
        assert abs(d["top"] - pre) < 2, (pre, d["top"])
        self._end_drag()

    def test_dragend_no_leftovers_card_in_slot(self):
        # Drag без drop: ghost-заглушка снята (keeper больше нет в DOM),
        # карточка снова в слоте — видимая, без инлайнового display
        load_view(self.page, spaces=self.SP, tabs=self.TABS3)
        self._start_drag(2)
        self._dragover_card(0)
        self._end_drag()
        d = json.loads(self.page.evaluate("""(() => JSON.stringify({
          keepers: document.querySelectorAll('.tab-row-keeper').length,
          slots: document.querySelectorAll('.tab-ghost-slot').length,
          srcDisplay: window.__srcCard.style.display,
          srcConnected: window.__srcCard.isConnected,
          cards: document.querySelectorAll('#tabs-list .tab-card').length
        }))()"""))
        assert d["keepers"] == 0 and d["slots"] == 0, d
        assert d["srcDisplay"] == "" and d["srcConnected"] and d["cards"] == 3, d

    def test_no_keeper_while_ghost_at_home(self):
        # Ghost-заглушка стоит СРАЗУ ПОСЛЕ карточки (дом) — row-keeper
        # в DOM не подключается (его больше нет)
        load_view(self.page, spaces=self.SP, tabs=self.TABS3)
        self._start_drag(0)
        self._dragover_card(0)  # over своей карточке — слот остался дома
        d = json.loads(self.page.evaluate("""(() => JSON.stringify({
          keepers: document.querySelectorAll('.tab-row-keeper').length,
          slotAtHome: window.__srcCard.nextElementSibling ===
            document.querySelector('.tab-ghost-slot')
        }))()"""))
        assert d["keepers"] == 0, d
        assert d["slotAtHome"], d
        self._end_drag()

    def test_cross_section_no_keeper_rows_fixed_real_grid(self):
        # Реальная сетка (theme.css + стили view.html), 1280 → 5 колонок:
        # группа (2 вкладки) сверху + 13 негрупповых (5+5+3). Последнюю вкладку
        # перетаскиваем в группу: row-keeper в DOM нет (схваченная карточка
        # выдернута из сетки — display:none), число строк исходной (loose)
        # секции не меняется (5+5+2 строк карточек = как раньше 5+5+3) —
        # якорь под списком стоит на месте
        tabs = [
            {"name": "M1", "url": "https://m1.com", "spaceId": "sp1", "groupId": "g1"},
            {"name": "M2", "url": "https://m2.com", "spaceId": "sp1", "groupId": "g1"},
        ] + [
            {"name": f"T{i}", "url": f"https://t{i}.com", "spaceId": "sp1"}
            for i in range(1, 14)
        ]
        load_view(self.page, spaces=self.SP,
                  groups=[{"id": "g1", "name": "G", "spaceId": "sp1", "collapsed": False}],
                  tabs=tabs, last_space="sp1")
        self._inject_css()
        self.page.set_viewport_size({"width": 1280, "height": 800})
        self.page.wait_for_timeout(50)
        # указатель в нейтральный угол: :hover карточки (translateY(-1px)) не
        # должен смещать строки под измерением (физическая позиция мыши
        # живёт между тестами на общей странице)
        self.page.mouse.move(0, 0)
        self.page.wait_for_timeout(200)
        pre = self._anchor_top()
        self._start_drag(14)  # последняя негрупповая (одинокая в последней строке)
        self._dragover_card(0)  # карточка группы — за пределами секции
        d = json.loads(self.page.evaluate("""(() => {
          const src = window.__srcCard;
          const slot = document.querySelector('.tab-ghost-slot');
          const bar = document.querySelector('#tabs-list .gbar');
          return JSON.stringify({
            keepers: document.querySelectorAll('.tab-row-keeper').length,
            srcDisplay: src.style.display,
            srcOpacity: getComputedStyle(src).opacity,
            slotAtG1Head: !!slot && !!bar && bar.nextElementSibling === slot,
            top: document.getElementById('tabs-list').getBoundingClientRect().bottom
          });
        })()"""))
        assert d["keepers"] == 0, d
        assert d["srcDisplay"] == "none" and d["srcOpacity"] == "1", d  # T13 выдернута, непрозрачна
        assert d["slotAtG1Head"], d  # заглушка — в начале секции g1 (до M1)
        assert abs(d["top"] - pre) < 2, (pre, d["top"])
        self._end_drag()


class TestDragSourceRowHold:
    """Условный row-keeper исходной секции (реальная сетка 1280x800 → 5
    колонок): пока ghost-заглушка УЕХАЛА из исходной секции (в другую
    секцию или спрятана над шапкой/слотом/пустой зоной карт.области),
    последнюю строку секции держит НЕВИДИМАЯ карточка-холдер .tab-row-keeper
    (opacity:0, pointer-events:none, НЕ .tab-card — groupVisibleCardCount и
    вооружение шапок групп её не видят) — и только когда без него число
    строк секции уменьшается (nFull — все вкладки секции, включая
    схваченную; rOrig = ceil(nFull/cols)). Холдер — в хвоте секции (после
    последней видимой карточки / после .gbar, если карточек нет / в конце
    #tabs-list в негрупповой секции). Снимается при возврате заглушки в
    секцию, dragend/Escape и на перерисовке. Лейауты без схлопывания —
    холдера нет."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self._errors = []
        page.on("pageerror", self._on_err)
        yield
        assert not self._errors, self._errors
        page.remove_listener("pageerror", self._on_err)

    def _on_err(self, err):
        self._errors.append(str(err))

    SP = [{"id": "sp1", "name": "Main"}]
    G2 = [{"id": "g1", "name": "G1", "spaceId": "sp1", "collapsed": False},
          {"id": "g2", "name": "G2", "spaceId": "sp1", "collapsed": False}]

    def _g1_tabs(self, n):
        return [{"name": f"T{i}", "url": f"https://t{i}.com",
                 "spaceId": "sp1", "groupId": "g1"} for i in range(1, n + 1)]

    def _g2_tabs(self, n):
        return [{"name": f"U{i}", "url": f"https://u{i}.com",
                 "spaceId": "sp1", "groupId": "g2"} for i in range(1, n + 1)]

    def _load(self, groups, tabs):
        load_view(self.page, spaces=self.SP, groups=groups, tabs=tabs, last_space="sp1")
        css = load_file("theme.css")
        html = load_file("view.html")
        style_block = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate("""(css) => {
          const s = document.createElement('style');
          s.textContent = css;
          document.head.appendChild(s);
        }""", css + style_block)
        self.page.set_viewport_size({"width": 1280, "height": 800})
        # указатель в нейтральный угол: :hover карточки (translateY(-1px)) не
        # должен смещать строки под измерением
        self.page.mouse.move(0, 0)
        self.page.wait_for_timeout(200)

    def _start_drag(self, name):
        self.page.evaluate("""(name) => {
          const card = [...document.querySelectorAll('#tabs-list .tab-card')]
            .find(c => c.querySelector('.tab-name').textContent.trim() === name);
          window.__srcCard = card;
          const dt = new DataTransfer();
          window.__dt = dt;
          card.dispatchEvent(new DragEvent('dragstart', {dataTransfer: dt, bubbles: true}));
        }""", name)
        self.page.wait_for_timeout(50)

    def _hover(self, x, y):
        self.page.evaluate("""([x, y]) => {
          document.getElementById('tabs-list').dispatchEvent(
            new DragEvent('dragover', {dataTransfer: window.__dt, bubbles: true, cancelable: true, clientX: x, clientY: y}));
        }""", [x, y])

    def _over_gbar(self, gid):
        self.page.evaluate("""(gid) => {
          const bar = document.querySelector('#tabs-list .gbar[data-group-id="' + gid + '"]');
          const r = bar.getBoundingClientRect();
          bar.dispatchEvent(new DragEvent('dragover', {
            dataTransfer: window.__dt, bubbles: true, cancelable: true,
            clientX: r.left + r.width / 2, clientY: r.top + r.height / 2}));
        }""", gid)

    def _end_drag(self):
        self.page.evaluate("""(() => {
          const card = window.__srcCard;
          if (card) card.dispatchEvent(new DragEvent('dragend', {bubbles: true}));
        })()""")

    def _rect(self, name):
        return self.page.evaluate("""(name) => {
          const card = [...document.querySelectorAll('#tabs-list .tab-card')]
            .find(c => c.querySelector('.tab-name').textContent.trim() === name);
          const b = card.getBoundingClientRect();
          return {left: b.left, top: b.top, width: b.width, height: b.height};
        }""", name)

    def _state(self):
        return json.loads(self.page.evaluate("""(() => {
          const k = document.querySelector('.tab-row-keeper');
          const nm = el => el && el.querySelector && el.querySelector('.tab-name')
            ? el.querySelector('.tab-name').textContent.trim() : null;
          const bar2 = document.querySelector('.gbar[data-group-id="g2"]');
          return JSON.stringify({
            keepers: document.querySelectorAll('.tab-row-keeper').length,
            kOpacity: k ? getComputedStyle(k).opacity : null,
            kTop: k ? k.getBoundingClientRect().top : null,
            kIsLast: k ? k === document.getElementById('tabs-list').lastElementChild : false,
            kPrevName: k ? nm(k.previousElementSibling) : null,
            kPrevGbar: k && k.previousElementSibling && k.previousElementSibling.classList
              && k.previousElementSibling.classList.contains('gbar')
              ? k.previousElementSibling.dataset.groupId : null,
            ghostHidden: (() => { const s = document.querySelector('.tab-ghost-slot');
              return !s || getComputedStyle(s).display === 'none'; })(),
            gbar2Top: bar2 ? bar2.getBoundingClientRect().top : null,
            btnTop: document.getElementById('tabs-list').getBoundingClientRect().bottom
          });
        })()"""))

    def test_lone_last_row_tab_ghost_moved_out_row_held(self):
        # Главное: группа 5+1 — единственную вкладку последней строки тащим
        # в другую группу: последняя строка ДЕРЖИТСЯ (холдер на её месте),
        # шапка следующей группы и низ списка не сдвинулись
        self._load(self.G2, self._g1_tabs(6) + self._g2_tabs(2))
        pre = self._state()
        t6 = self._rect("T6")
        assert t6["top"] > self._rect("T1")["top"], t6  # T6 одинокая во 2-й строке
        u1 = self._rect("U1")
        self._start_drag("T6")
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        d = self._state()
        assert d["keepers"] == 1, d
        assert d["kOpacity"] == "0", d  # холдер невидим
        assert d["kPrevName"] == "T5", d  # холдер — в хвоте g1, после последней видимой
        assert abs(d["kTop"] - t6["top"]) < 2, (t6["top"], d["kTop"])  # строка на месте
        assert abs(d["gbar2Top"] - pre["gbar2Top"]) < 2, (pre["gbar2Top"], d["gbar2Top"])
        assert abs(d["btnTop"] - pre["btnTop"]) < 2, (pre["btnTop"], d["btnTop"])
        self._end_drag()
        assert self._state()["keepers"] == 0

    def test_row1_tab_ghost_moved_out_row_held(self):
        # Тащим вкладку ПЕРВОЙ строки: одинокая T6 поднимается в первую
        # строку, освобождённая вторая строка держится холдером (после T6)
        self._load(self.G2, self._g1_tabs(6) + self._g2_tabs(2))
        pre = self._state()
        t1 = self._rect("T1")
        t6 = self._rect("T6")
        u1 = self._rect("U1")
        self._start_drag("T1")
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        d = self._state()
        assert d["keepers"] == 1, d
        assert d["kPrevName"] == "T6", d  # T6 теперь последняя видимая
        assert abs(d["kTop"] - t6["top"]) < 2, (t6["top"], d["kTop"])  # строка на месте
        t6n = self._rect("T6")
        assert abs(t6n["top"] - t1["top"]) < 2, (t1["top"], t6n["top"])  # T6 поднялась в 1-ю строку
        assert abs(d["gbar2Top"] - pre["gbar2Top"]) < 2, (pre["gbar2Top"], d["gbar2Top"])
        self._end_drag()
        assert self._state()["keepers"] == 0

    def test_no_collapse_seven_tabs_no_keeper(self):
        # 7 вкладок (5+2): одна схвачена — 6 видимых = всё ещё 2 строки:
        # строка не схлопывается, холдер НЕ подключается (условие не выполнено)
        self._load(self.G2, self._g1_tabs(7) + self._g2_tabs(2))
        pre = self._state()
        u1 = self._rect("U1")
        self._start_drag("T1")
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        d = self._state()
        assert d["keepers"] == 0, d
        assert abs(d["gbar2Top"] - pre["gbar2Top"]) < 2, (pre["gbar2Top"], d["gbar2Top"])
        self._end_drag()

    def test_ghost_back_in_section_no_keeper(self):
        # Заглушка вернулась В исходную секцию (в первую строку, до T1) —
        # холдера нет: заглушка сама занимает клетку, 5 карточек + заглушка
        # = 2 строки держатся естественно (T6 вырвана)
        self._load(self.G2, self._g1_tabs(6) + self._g2_tabs(2))
        t6 = self._rect("T6")
        t1 = self._rect("T1")
        self._start_drag("T6")
        self._hover(t1["left"] + t1["width"] * 0.25, t1["top"] + t1["height"] * 0.5)
        d = self._state()
        assert d["keepers"] == 0, d
        assert d["ghostHidden"] is False, d
        t5 = self._rect("T5")
        assert abs(t5["top"] - t6["top"]) < 2, (t6["top"], t5["top"])  # T5 во 2-й строке
        self._end_drag()
        assert self._state()["keepers"] == 0


    def test_ghost_hidden_over_other_gbar_row_held(self):
        # Заглушка спрятана над шапкой ДРУГОЙ группы: строка исходной
        # секции всё так же держится холдером; возврат курсора в список
        # (заглушка снова в другой секции) — холдер остаётся
        self._load(self.G2, self._g1_tabs(6) + self._g2_tabs(2))
        pre = self._state()
        u1 = self._rect("U1")
        self._start_drag("T1")
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        assert self._state()["keepers"] == 1
        self._over_gbar("g2")  # курсор над шапкой g2 — заглушка прячется
        d = self._state()
        assert d["ghostHidden"] is True, d
        assert d["keepers"] == 1, d
        assert abs(d["gbar2Top"] - pre["gbar2Top"]) < 2, (pre["gbar2Top"], d["gbar2Top"])
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        d = self._state()
        assert d["ghostHidden"] is False and d["keepers"] == 1, d
        self._end_drag()
        assert self._state()["keepers"] == 0

    def test_single_tab_group_gbar_still_arms(self):
        # Группа с ЕДИНСТВЕННОЙ вкладкой: вкладка схвачена (вырвана из
        # сетки), заглушка спрятана над шапкой СОБСТВЕННОЙ группы — холдер
        # держит пустую строку (после шапки, карточек нет), а
        # groupVisibleCardCount(g1) === 0 — шапка вооружена целью дропа
        # (.drop-over), как и раньше: холдер карточкой не считается
        self._load(self.G2, self._g1_tabs(1) + self._g2_tabs(2))
        u1 = self._rect("U1")
        self._start_drag("T1")
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        d = self._state()
        assert d["keepers"] == 1 and d["kPrevGbar"] == "g1", d
        self._over_gbar("g1")  # курсор над шапкой g1 — заглушка прячется
        d = json.loads(self.page.evaluate("""(() => {
          const k = document.querySelector('.tab-row-keeper');
          const bar = document.querySelector('.gbar[data-group-id="g1"]');
          const s = document.querySelector('.tab-ghost-slot');
          return JSON.stringify({
            keepers: document.querySelectorAll('.tab-row-keeper').length,
            kOpacity: k ? getComputedStyle(k).opacity : null,
            visibleG1: groupVisibleCardCount('g1'),
            dropOver: bar.classList.contains('drop-over'),
            ghostHidden: !s || getComputedStyle(s).display === 'none'
          });
        })()"""))
        assert d["ghostHidden"] is True, d
        assert d["keepers"] == 1 and d["kOpacity"] == "0", d
        assert d["visibleG1"] == 0, d  # холдер не меняет счётчик видимых карточек
        assert d["dropOver"] is True, d  # шапка пустой группы вооружена
        self._end_drag()
        assert self._state()["keepers"] == 0

    def test_ghost_visible_over_tail_territory_row_held(self):
        # TERRITORIES: зона НИЖЕ последней строки g1 (над шапкой g2) —
        # ХВОСТ территории g1 (верхняя половина межсекционного зазора):
        # заглушка ВИДИМА (не прячется), встает перед T6 (подход снизу →
        # side 'before') и сама держит строку (холдер не нужен); g2 не сдвинулся.
        self._load(self.G2, self._g1_tabs(6) + self._g2_tabs(2))
        pre = self._state()
        u1 = self._rect("U1")
        self._start_drag("T1")
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        pt = self.page.evaluate("""(() => {
          const bar = document.querySelector('.gbar[data-group-id="g2"]');
          const list = document.getElementById('tabs-list').getBoundingClientRect();
          const cards = [...document.querySelectorAll('#tabs-list .tab-card')]
            .filter(c => c.style.display !== 'none' && c.__tab && c.__tab.groupId === 'g1');
          let bottom = -Infinity;
          cards.forEach(c => { const r = c.getBoundingClientRect();
            if (r.height > 0) bottom = Math.max(bottom, r.bottom); });
          return [list.left + list.width / 2,
                  (bottom + bar.getBoundingClientRect().top) / 2];
        })()""")
        self._hover(*pt)
        d = self._state()
        d2 = json.loads(self.page.evaluate("""(() => {
          const s = document.querySelector('.tab-ghost-slot');
          const nm = el => el && el.querySelector && el.querySelector('.tab-name')
            ? el.querySelector('.tab-name').textContent.trim() : null;
          return JSON.stringify({
            ghostPrev: nm(s.previousElementSibling),
            ghostNext: nm(s.nextElementSibling)
          });
        })()"""))
        assert d["ghostHidden"] is False, d
        assert d["keepers"] == 0, d
        assert d2["ghostPrev"] == "T5" and d2["ghostNext"] == "T6", d2
        assert abs(d["gbar2Top"] - pre["gbar2Top"]) < 2, (pre["gbar2Top"], d["gbar2Top"])
        self._end_drag()
        assert self._state()["keepers"] == 0

    def test_dragend_no_leftovers(self):
        # Dragend (без дропа) из состояния с холдером — без следов: ни
        # холдера, ни заглушки, карточка возвращена в слот
        self._load(self.G2, self._g1_tabs(6) + self._g2_tabs(2))
        u1 = self._rect("U1")
        self._start_drag("T1")
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        assert self._state()["keepers"] == 1
        self._end_drag()
        d = self._state()
        assert d["keepers"] == 0, d
        assert d["ghostHidden"] is True, d  # заглушки в DOM нет
        assert self.page.evaluate("""(() => {
          const card = [...document.querySelectorAll('#tabs-list .tab-card')]
            .find(c => c.querySelector('.tab-name').textContent.trim() === 'T1');
          return card.style.display;
        })()""") == ""

    def test_escape_cancel_no_leftovers(self):
        # Escape (pointer-путь) из состояния с холдером — без следов:
        # документный keydown ре-рендерит список, pointer-cancel снимает драг
        self._load(self.G2, self._g1_tabs(6) + self._g2_tabs(2))
        box = self._rect("T1")
        u1 = self._rect("U1")
        pg = self.page
        pg.mouse.move(box["left"] + box["width"] / 2, box["top"] + box["height"] / 2)
        pg.mouse.down()
        pg.mouse.move(u1["left"] + u1["width"] / 2, u1["top"] + u1["height"] / 2, steps=10)
        assert self._state()["keepers"] == 1
        pg.keyboard.press("Escape")
        pg.mouse.up()
        d = self._state()
        assert d["keepers"] == 0, d
        assert d["ghostHidden"] is True, d

    def test_re_render_resets_tracker(self):
        # Перерисовка посреди драга уносит холдер и сбрасывает трекер;
        # следующий драг прицепляет холдер заново (старое состояние не
        # «залипает»)
        self._load(self.G2, self._g1_tabs(6) + self._g2_tabs(2))
        u1 = self._rect("U1")
        self._start_drag("T1")
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        assert self._state()["keepers"] == 1
        self.page.evaluate("renderTabs()")  # перерисовка (как при storage-событии)
        assert self._state()["keepers"] == 0
        self._end_drag()
        self._start_drag("T1")  # свежий драг — холдер прицепляется снова
        u1 = self._rect("U1")
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        d = self._state()
        assert d["keepers"] == 1, d
        self._end_drag()
        assert self._state()["keepers"] == 0

    def test_loose_section_row_held(self):
        # Негрупповая секция 5+1: вкладка уезжает в группу — холдер в хвоте
        # #tabs-list держит последнюю строку
        tabs = self._g2_tabs(2) + [
            {"name": f"T{i}", "url": f"https://t{i}.com", "spaceId": "sp1"}
            for i in range(1, 7)]
        self._load([{"id": "g2", "name": "G2", "spaceId": "sp1", "collapsed": False}], tabs)
        pre = self._state()
        u1 = self._rect("U1")
        self._start_drag("T1")
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        d = self._state()
        assert d["keepers"] == 1, d
        assert d["kIsLast"] is True, d  # холдер — последний элемент #tabs-list
        assert abs(d["btnTop"] - pre["btnTop"]) < 2, (pre["btnTop"], d["btnTop"])
        assert abs(d["gbar2Top"] - pre["gbar2Top"]) < 2, (pre["gbar2Top"], d["gbar2Top"])
        self._end_drag()
        assert self._state()["keepers"] == 0

    def test_keeper_invisible_both_themes(self):
        # Холдер невидим (opacity 0) и держит строку в обеих темах
        # (смена темы не перерисовывает список)
        self._load(self.G2, self._g1_tabs(6) + self._g2_tabs(2))
        pre = self._state()
        u1 = self._rect("U1")
        self._start_drag("T1")
        self._hover(u1["left"] + u1["width"] * 0.5, u1["top"] + u1["height"] * 0.5)
        d = self._state()
        assert d["keepers"] == 1 and d["kOpacity"] == "0", d
        assert abs(d["gbar2Top"] - pre["gbar2Top"]) < 2, (pre["gbar2Top"], d["gbar2Top"])
        assert self.page.evaluate(
            "document.documentElement.dataset.theme") == "light"
        self.page.evaluate("setTheme('dark')")
        assert self.page.evaluate(
            "document.documentElement.dataset.theme") == "dark"
        d = self._state()
        assert d["keepers"] == 1 and d["kOpacity"] == "0", d
        assert abs(d["gbar2Top"] - pre["gbar2Top"]) < 2, (pre["gbar2Top"], d["gbar2Top"])
        self._end_drag()
        assert self._state()["keepers"] == 0


class TestEmptyGroupAutoCollapse:
    """Автосворачивание: группа, потерявшая ПОСЛЕДНЮЮ вкладку (перенос в
    «Без группы» или удаление ✕), сворачивается сама — вместо шапки с
    «Перетащите вкладку сюда» — свёрнутая шапка «0 вкладок». Пустая группа
    (свежесозданная или с collapsed:false в данных) рендерится в свёрнутом
    виде — раскрытие пустых групп убрано."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page

    SP = [{"id": "sp1", "name": "Main"}]
    G1 = {"id": "g1", "name": "Dev", "spaceId": "sp1", "collapsed": False}

    def _collapsed(self):
        return read_storage_raw(self.page, "blattam-groups")[0]["collapsed"]

    def test_last_tab_moved_out_collapses_group(self):
        # Единственная вкладка группы уезжает в «Без группы» (place-tab,
        # groupId null) — группа сворачивается: ▸ + «0 вкладок», слота нет
        load_view(self.page, spaces=self.SP, groups=[dict(self.G1)],
                  tabs=[{"name": "D1", "url": "https://d1.com",
                         "spaceId": "sp1", "groupId": "g1"}])
        self.page.evaluate("""chrome.runtime.sendMessage({action: 'place-tab',
            index: 0, anchorIndex: 1, side: 'after', groupId: null})""")
        self.page.wait_for_timeout(100)
        assert self.page.evaluate("document.querySelector('.gbar .chev').textContent") == "▸"
        assert self.page.evaluate("document.querySelectorAll('.group-empty-slot').length") == 0
        assert self.page.evaluate("document.querySelector('.gbar .gcount').textContent") == "0 вкладок"
        assert self._collapsed() is True

    def test_group_with_two_tabs_stays_expanded(self):
        # Две вкладки: одна уезжает в «Без группы» — группа остаётся
        # развёрнутой (член ещё есть): ▾, пустого слота нет
        load_view(self.page, spaces=self.SP, groups=[dict(self.G1)], tabs=[
            {"name": "D1", "url": "https://d1.com", "spaceId": "sp1", "groupId": "g1"},
            {"name": "D2", "url": "https://d2.com", "spaceId": "sp1", "groupId": "g1"},
        ])
        self.page.evaluate("""chrome.runtime.sendMessage({action: 'place-tab',
            index: 0, anchorIndex: 1, side: 'before', groupId: null})""")
        self.page.wait_for_timeout(100)
        assert self.page.evaluate("document.querySelector('.gbar .chev').textContent") == "▾"
        assert self.page.evaluate("document.querySelectorAll('.group-empty-slot').length") == 0
        assert self.page.evaluate("document.querySelector('.gbar .gcount').textContent") == "1 вкладка"
        assert self._collapsed() is False

    def test_last_tab_deleted_collapses_group(self):
        # ✕ на карточке: единственная вкладка группы уходит в корзину —
        # группа сворачивается: ▸ + «0 вкладок», слота нет, вкладки пустые
        load_view(self.page, spaces=self.SP, groups=[dict(self.G1)],
                  tabs=[{"name": "D1", "url": "https://d1.com",
                         "spaceId": "sp1", "groupId": "g1"}])
        self.page.evaluate("document.querySelector('.tab-card .tab-remove').click()")
        self.page.wait_for_timeout(100)
        assert self.page.evaluate("document.querySelector('.gbar .chev').textContent") == "▸"
        assert self.page.evaluate("document.querySelectorAll('.group-empty-slot').length") == 0
        assert self.page.evaluate("document.querySelector('.gbar .gcount').textContent") == "0 вкладок"
        assert self._collapsed() is True
        assert read_storage_raw(self.page, "blattam-tabs") == []
        trash = read_storage_raw(self.page, "blattam-trash")
        assert len(trash) == 1 and trash[0]["url"] == "https://d1.com", trash

    def test_fresh_empty_group_renders_collapsed(self):
        # Пустая группа без членов (свежесозданная) — свёрнутый вид:
        # ▸ + «0 вкладок», слота нет
        load_view(self.page, spaces=self.SP, groups=[dict(self.G1)], tabs=[])
        assert self.page.evaluate("document.querySelector('.gbar .chev').textContent") == "▸"
        assert self.page.evaluate("document.querySelector('.gbar').classList.contains('gbar-collapsed')") is True
        assert self.page.evaluate("document.querySelectorAll('.group-empty-slot').length") == 0
        assert self.page.evaluate("document.querySelector('.gbar .gcount').textContent") == "0 вкладок"
        assert self._collapsed() is False  # данные не трогаем — вид производный



