        load_view(self.page)
        self._open()
        qa = json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('#settings-modal .faq-item')]"
            ".map(i => ({q: i.querySelector('.faq-q').textContent.trim(), a: i.querySelector('.faq-a').textContent.trim()})))"))
