class TestTabCardHeightTaller:
    """Карточка сохранённой вкладки — 80px (было 74px): min-height 74px → 80px
    (<style> view.html); тёплая ghost-slot при драге снимает высоту с карточки
    на рантайме."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page

    SP = [{"id": "sp1", "name": "Main"}]

    def _inject_real_styles(self):
        theme = load_file("theme.css")
        html = load_file("view.html")
        style = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate(
            "(styles) => { var st = document.createElement('style'); st.textContent = styles; document.head.appendChild(st); }",
            [theme + "\n" + style])

    def test_card_height_80px_both_themes(self):
        for theme in ("light", "dark"):
            load_view(self.page, theme=theme, spaces=self.SP,
                      groups=[{"id": "g1", "name": "Empty", "spaceId": "sp1", "collapsed": False}],
                      tabs=[{"name": "A", "url": "https://a.com", "spaceId": "sp1"}])
            self._inject_real_styles()
            self.page.wait_for_timeout(150)
            d = json.loads(self.page.evaluate("""(() => {
              const card = document.querySelector('.tab-card');
              return JSON.stringify({
                cardH: card ? card.getBoundingClientRect().height : null
              });
            })()"""))
            assert d["cardH"] is not None, (theme, d)
            assert abs(d["cardH"] - 80) < 0.6, (theme, d)

    def test_drag_ghost_slot_height_matches_taller_card(self):
        load_view(self.page, spaces=self.SP,
                  groups=[{"id": "g1", "name": "G", "spaceId": "sp1", "collapsed": False}],
                  tabs=[{"name": "T1", "url": "https://t1.com", "spaceId": "sp1", "groupId": "g1"},
                        {"name": "T2", "url": "https://t2.com", "spaceId": "sp1", "groupId": "g1"}],
                  last_space="sp1")
        self._inject_real_styles()
        self.page.mouse.move(0, 0)
        self.page.wait_for_timeout(150)
        # HTML5-синтетика: dragstart карточки + один dragover в список.
        # Высота карточки снята ДО хайда (во время драга исходник display:none).
        cardH0 = self.page.evaluate(
            "document.querySelector('#tabs-list .tab-card').getBoundingClientRect().height")
        self.page.evaluate("""(() => {
          const card = document.querySelector('#tabs-list .tab-card');
          window.__srcCard = card;
          const dt = new DataTransfer();
          window.__dt = dt;
          card.dispatchEvent(new DragEvent('dragstart', {dataTransfer: dt, bubbles: true}));
        })()""")
        self.page.wait_for_timeout(50)  # отложенное создание заглушки (setTimeout(0))
        self.page.evaluate("""() => {
          // строка карточки T2 (шапка группы — полоса: над ней заглушка
          // прячется и высоту мерить нечего)
          const r = document.querySelectorAll('#tabs-list .tab-card')[1].getBoundingClientRect();
          document.getElementById('tabs-list').dispatchEvent(
            new DragEvent('dragover', {dataTransfer: window.__dt, bubbles: true,
                                       cancelable: true, clientX: r.left + 10, clientY: r.top + 10}));
        }""")
        self.page.wait_for_timeout(50)
        d = json.loads(self.page.evaluate("""(() => {
          const slot = document.querySelector('.tab-ghost-slot');
          return JSON.stringify({ghostH: slot ? slot.getBoundingClientRect().height : null});
        })()"""))
        assert d["ghostH"] is not None, d
        assert abs(d["ghostH"] - cardH0) < 0.6, (d, cardH0)
        assert abs(cardH0 - 80) < 0.6, (d, cardH0)
        self.page.evaluate("""() => {
          if (window.__srcCard) window.__srcCard.dispatchEvent(new DragEvent('dragend', {bubbles: true}));
        }""")


class TestGhostHiddenOverRail:
    """Призрак-заглушка (.tab-ghost-slot) спрятан ЦЕЛИКОМ, пока карточка
    висит над правой рейкой (#rail-right) — как над .gbar / .group-empty-slot
    (display:none, а не visibility: ячейка освобождается, строка исходной
    секции держится условным row-keeper'ом). Рейка при этом остаётся тёплой
    (.rail-drag-over). Возврат курсора в #tabs-list — призрак снова виден на
    месте вставки; дроп/отмена над рейкой — без остатков. Оба пути драга:
    HTML5-синтетика и pointer (реальная мышь). Дроп-поведение рейки (сайт
    открывается фоновой вкладкой, карточка не тронута) — без изменений."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self._errors = []
        page.on("pageerror", self._on_err)
        yield
        assert not self._errors, self._errors
        page.remove_listener("pageerror", self._on_err)

    def _on_err(self, err):
        self._errors.append(str(err))

    SP = [{"id": "sp1", "name": "Main"}]
    GROUPS = [{"id": "g1", "name": "G", "spaceId": "sp1", "collapsed": False}]
    TABS = [
        {"name": "T1", "url": "https://t1.com", "spaceId": "sp1", "groupId": "g1"},
        {"name": "T2", "url": "https://t2.com", "spaceId": "sp1", "groupId": "g1"},
    ]
    BT = [
        {"id": "bt1", "title": "Wiki", "url": "https://wiki.example", "windowId": 1, "index": 0},
        {"id": "bt2", "title": "Mail", "url": "https://mail.example", "windowId": 1, "index": 1},
    ]

    def _load(self, tabs=None, groups=None):
        load_view(self.page, spaces=self.SP, groups=groups or self.GROUPS,
                  tabs=tabs or self.TABS, last_space="sp1", browser_tabs=self.BT)
        # CSS view.html + theme.css — как в TestRailWarmOnCardDrag: без него
        # рейка лежит ПОД центральным списком, а не в правой колонке
        css = load_file("theme.css")
        html = load_file("view.html")
        style_block = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate("""(css) => {
          const s = document.createElement('style');
          s.textContent = css;
          document.head.appendChild(s);
        }""", css + style_block)
        self.page.set_viewport_size({"width": 1280, "height": 800})
        self.page.mouse.move(0, 0)
        self.page.wait_for_timeout(200)

    def _state(self):
        return json.loads(self.page.evaluate("""() => {
          const s = document.querySelector('#tabs-list .tab-ghost-slot');
          const c = document.querySelector('.pd-clone');
          return JSON.stringify({
            ghostExists: !!s,
            ghostDisplay: s ? getComputedStyle(s).display : null,
            inList: !!s && s.isConnected,
            railCls: document.getElementById('rail-right').classList.contains('rail-drag-over'),
            keepers: document.querySelectorAll('.tab-row-keeper').length,
            clones: c ? 1 : 0
          });
        }"""))

    def _card_box(self, name):
        return self.page.evaluate("""(name) => {
          const c = [...document.querySelectorAll('#tabs-list .tab-card')]
            .find(c => c.querySelector('.tab-name').textContent.trim() === name);
          const r = c.getBoundingClientRect();
          return {x: r.left + r.width / 2, y: r.top + r.height / 2};
        }""", name)

    def _rail_point(self):
        return self.page.evaluate("""() => {
          const r = document.getElementById('rail-right').getBoundingClientRect();
          return {x: r.left + r.width / 2, y: r.top + Math.min(40, r.height / 2)};
        }""")

    def _start_drag(self, name):
        self.page.evaluate("""(name) => {
          const card = [...document.querySelectorAll('#tabs-list .tab-card')]
            .find(c => c.querySelector('.tab-name').textContent.trim() === name);
          window.__srcCard = card;
          window.__dt = new DataTransfer();
          card.dispatchEvent(new DragEvent('dragstart', {dataTransfer: window.__dt, bubbles: true}));
        }""", name)
        self.page.wait_for_timeout(50)  # отложенное создание заглушки (setTimeout(0))

    def _dragover_at(self, sel, x, y):
        self.page.evaluate("""([sel, x, y]) => {
          const el = document.querySelector(sel);
          el.dispatchEvent(new DragEvent('dragover', {dataTransfer: window.__dt,
            bubbles: true, cancelable: true, clientX: x, clientY: y}));
        }""", [sel, x, y])

    def _drop_at(self, sel, x, y):
        self.page.evaluate("""([sel, x, y]) => {
          const el = document.querySelector(sel);
          el.dispatchEvent(new DragEvent('drop', {dataTransfer: window.__dt,
            bubbles: true, cancelable: true, clientX: x, clientY: y}));
        }""", [sel, x, y])

    def _end_drag(self):
        self.page.evaluate("""(() => {
          const card = window.__srcCard;
          if (card) card.dispatchEvent(new DragEvent('dragend', {bubbles: true}));
        })()""")

    def test_html5_ghost_hidden_over_rail_and_back_to_list(self):
        # HTML5: dragover в список — призрак виден; dragover над рейкой —
        # спрятан ЦЕЛИКОМ и рейка тёплая; возврат в список — снова виден
        self._load()
        self._start_drag("T1")
        c2 = self._card_box("T2")
        self._dragover_at("#tabs-list", c2["x"], c2["y"])
        d = self._state()
        assert d["ghostExists"] and d["ghostDisplay"] != "none", d
        assert not d["railCls"], d
        rail = self._rail_point()
        self._dragover_at("#rail-right", rail["x"], rail["y"])
        d = self._state()
        assert d["ghostDisplay"] == "none", d
        assert d["railCls"] is True, d
        self._dragover_at("#tabs-list", c2["x"], c2["y"])
        d = self._state()
        assert d["ghostDisplay"] != "none" and d["inList"], d
        assert d["railCls"] is False, d
        self._end_drag()

    def test_html5_first_dragover_race_on_rail(self):
        # Гонка: ПЕРВЫЙ dragover падает на рейку ДО отложенного создания
        # заглушки — после её появления призрак НЕ замигает дома
        self._load()
        self.page.evaluate("""(() => {
          const card = [...document.querySelectorAll('#tabs-list .tab-card')][0];
          window.__srcCard = card;
          window.__dt = new DataTransfer();
          card.dispatchEvent(new DragEvent('dragstart', {dataTransfer: window.__dt, bubbles: true}));
        })()""")
        rail = self._rail_point()
        self._dragover_at("#rail-right", rail["x"], rail["y"])
        self.page.wait_for_timeout(120)  # отложенный applyGhost fired
        d = self._state()
        assert d["ghostExists"] is True, d
        assert d["ghostDisplay"] == "none", d
        assert d["railCls"] is True, d
        self._end_drag()

    def test_html5_drop_on_rail_background_tab_no_leftovers(self):
        # Дроп над рейкой — сайт открывается фоновой вкладкой (mock
        # chrome.tabs.create, active:false), карточка не тронута; dragend —
        # без заглушки/холдеров/тёплого класса
        self._load()
        self._start_drag("T1")
        rail = self._rail_point()
        self._dragover_at("#rail-right", rail["x"], rail["y"])
        self._drop_at("#rail-right", rail["x"], rail["y"])
        bg = json.loads(self.page.evaluate(
            "JSON.stringify((chrome.tabs.createdTabs || []).filter(t => t.active === false))"))
        assert [t["url"] for t in bg] == ["https://t1.com"], bg
        self._end_drag()
        d = self._state()
        assert d["ghostExists"] is False, d
        assert d["railCls"] is False, d
        assert d["keepers"] == 0, d
        assert json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('#tabs-list .tab-card .tab-name')].map(n => n.textContent.trim()))")
        ) == ["T1", "T2"]

    def test_pointer_ghost_hidden_over_rail_visible_back_drop_commits(self):
        # Pointer (реальная мышь): press + движение >8px — вооружено; над
        # рейкой — призрак спрятан, рейка тёплая; возврат в список — снова
        # виден; релиз над рейкой — фоновая вкладка, без остатков
        self._load()
        card = self._card_box("T1")
        rail = self._rail_point()
        c2 = self._card_box("T2")
        pg = self.page
        pg.mouse.move(card["x"], card["y"])
        pg.mouse.down()
        pg.mouse.move(card["x"] + 12, card["y"], steps=3)  # >8px — вооружено
        for i in range(1, 11):
            pg.mouse.move(card["x"] + (rail["x"] - card["x"]) * i / 10,
                          card["y"] + (rail["y"] - card["y"]) * i / 10, steps=2)
        d = self._state()
        assert d["ghostDisplay"] == "none", d
        assert d["railCls"] is True, d
        for i in range(1, 11):
            pg.mouse.move(rail["x"] + (c2["x"] - rail["x"]) * i / 10,
                          rail["y"] + (c2["y"] - rail["y"]) * i / 10, steps=2)
        d = self._state()
        assert d["ghostDisplay"] != "none" and d["inList"], d
        for i in range(1, 11):
            pg.mouse.move(c2["x"] + (rail["x"] - c2["x"]) * i / 10,
                          c2["y"] + (rail["y"] - c2["y"]) * i / 10, steps=2)
        pg.mouse.up()
        self.page.wait_for_timeout(120)
        bg = json.loads(self.page.evaluate(
            "JSON.stringify((chrome.tabs.createdTabs || []).filter(t => t.active === false))"))
        assert [t["url"] for t in bg] == ["https://t1.com"], bg
        self.page.wait_for_timeout(400)  # клон-сета (settleMs ~180) завершён
        d = self._state()
        assert d["ghostExists"] is False, d
        assert d["clones"] == 0
        assert d["railCls"] is False, d

    def test_row_keeper_holds_row_when_ghost_over_rail(self):
        # Сетка 1280x800 (5 колонок), группа 5+1: единственную вкладку
        # последней строки тащим над рейку — призрак спрятан И последнюю
        # строку держит условный row-keeper
        tabs = [{"name": f"T{i}", "url": f"https://t{i}.com",
                 "spaceId": "sp1", "groupId": "g1"} for i in range(1, 7)]
        self._load(tabs=tabs)
        self._start_drag("T6")
        rail = self._rail_point()
        self._dragover_at("#rail-right", rail["x"], rail["y"])
        d = self._state()
        assert d["ghostDisplay"] == "none", d
        assert d["keepers"] == 1, d
        self._end_drag()
        assert self._state()["keepers"] == 0


# ==========================================
#  VIEW.JS: ПУСТОЕ ПРОСТРАНСТВО СЕТКИ — ЗАГЛУШКА СПРЯТАНА, ДРОП — ОТМЕНА
# ==========================================

class TestDragEmptyBandHome:
    """Территории (волна «нет ничейных полос»): зоны (A) между низом шапки
    секции и верхом первой строки, (B) между низом последней строки и
    шапкой следующей секции и (C) row-gap между строками секции — теперь
    ТЕРРИТОРИИ карточек: заглушка ВИДИМА в слоте (midpoint-расщепление:
    зона (B) выше M — хвост верхней секции, ниже M — первая строка нижней;
    зона (C) выше M — верхняя строка, ниже M — нижняя; (A) — первая строка
    по span, подход сверху -> side 'after'), дроп — КОММИТ в слот заглушки.
    Осталась ОДНА полоса — низовая зона (ниже последней строки последней
    секции: строка #add-group-btn + отступ): там по-прежнему заглушка
    СКРЫТА (строку исходной секции держит row-keeper), дроп — ОТМЕНА.
    Пустые ячейки СВОЕЙ строки (справа от последней карточки) — не полоса.
    Дроп на .gbar / .group-empty-slot / карточку / чип / рейку — semantics
    unchanged."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self._errors = []
        page.on("pageerror", self._on_err)
        yield
        assert not self._errors, self._errors
        page.remove_listener("pageerror", self._on_err)

    def _on_err(self, err):
        self._errors.append(str(err))

    SP = [{"id": "sp1", "name": "Main"}]
    GROUPS = [
        {"id": "gA", "name": "A", "spaceId": "sp1", "collapsed": False},
        {"id": "gZ", "name": "Z", "spaceId": "sp1", "collapsed": True},
    ]

    def _tabs(self, group_n=7):
        tabs = [{"name": "A%d" % i, "url": "https://a%d.com" % i,
                 "spaceId": "sp1", "groupId": "gA"} for i in range(1, group_n + 1)]
        tabs.append({"name": "Z1", "url": "https://z1.com", "spaceId": "sp1", "groupId": "gZ"})
        tabs += [{"name": "L%d" % i, "url": "https://l%d.com" % i,
                  "spaceId": "sp1"} for i in range(1, 3)]
        return tabs

    def _load(self, tabs=None):
        load_view(self.page, spaces=self.SP, groups=self.GROUPS,
                  tabs=tabs if tabs is not None else self._tabs(), last_space="sp1")
        css = load_file("theme.css")
        html = load_file("view.html")
        style_block = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate("""(css) => {
          const s = document.createElement('style');
          s.textContent = css;
          document.head.appendChild(s);
        }""", css + style_block)
        self.page.set_viewport_size({"width": 1280, "height": 800})
        self.page.mouse.move(0, 0)
        self.page.wait_for_timeout(200)
        self._maps()

    def _maps(self):
        self.page.evaluate("""(() => {
          window.__cards = {};
          document.querySelectorAll('#tabs-list .tab-card').forEach(c => {
            const n = c.querySelector('.tab-name').textContent.trim();
            window.__cards[n] = c;
          });
        })()""")

    def _start_drag(self, name):
        self.page.evaluate("""(name) => {
          const card = window.__cards[name];
          window.__srcCard = card;
          const dt = new DataTransfer();
          window.__dt = dt;
          card.dispatchEvent(new DragEvent('dragstart', {dataTransfer: dt, bubbles: true, cancelable: true}));
        }""", name)
        self.page.wait_for_timeout(50)

    def _band_point(self, kind, gid, half=None):
        # Точка пустой полосы: 'above' — между шапкой секции и первой
        # видимой строкой карточек; 'below' — между последней строкой и
        # шапкой следующей секции (.gbar / .loose-label / #add-group-btn);
        # 'gap' — vertical grid row-gap between two rows of the section
        # (half: 'above'/'below' — половины зазора по midpoint-расщеплению)
        return self.page.evaluate("""([kind, gid, half]) => {
          const list = document.getElementById('tabs-list').getBoundingClientRect();
          const kids = [...document.getElementById('tabs-list').children];
          const isHeader = el => el.classList.contains('gbar') || el.classList.contains('loose-label');
          const isLooseTab = c => !c.__tab || !c.__tab.groupId ||
            !document.querySelector('#tabs-list .gbar[data-group-id="' + c.__tab.groupId + '"]');
          const inSection = c => gid === 'loose' ? isLooseTab(c)
            : (c.__tab && c.__tab.groupId === gid);
          const cards = [...document.querySelectorAll('#tabs-list .tab-card')]
            .filter(c => c.style.display !== 'none' && inSection(c));
          if (!cards.length) return null;
          const rect = el => el.getBoundingClientRect();
          // шапка секции и шапка следующей секции
          let header = null;
          for (const el of kids) {
            if (el.id === 'add-group-btn') break;
            if (isHeader(el) && (el.classList.contains('loose-label') ||
                (el.classList.contains('gbar') && el.dataset.groupId === gid))) {
              header = el; break;
            }
          }
          const topBound = header ? rect(header).bottom : list.top;
          // следующая шапка после последней карточки секции
          const lastCard = cards[cards.length - 1];
          let nextH = null;
          for (let el = lastCard.nextElementSibling; el; el = el.nextElementSibling) {
            if (el.id === 'add-group-btn' || isHeader(el)) { nextH = el; break; }
          }
          const nextTop = nextH ? rect(nextH).top : list.bottom;
          // строки по координатам верха
          const rows = cards.map(c => rect(c)).sort((a, b) => a.top - b.top);
          const groups = [];
          for (const r of rows) {
            const last = groups[groups.length - 1];
            if (last && Math.abs(last.top - r.top) < 1) { if (r.bottom > last.bottom) last.bottom = r.bottom; }
            else groups.push({top: r.top, bottom: r.bottom});
          }
          let y;
          if (kind === 'above') y = (topBound + groups[0].top) / 2;
          else if (kind === 'below') y = (groups[groups.length - 1].bottom + nextTop) / 2;
          else { if (groups.length < 2) throw new Error('need 2+ rows for gap band');
                 const M = (groups[0].bottom + groups[1].top) / 2;
                 // half: 'above' — верхняя половина зазора (территория верхней
                 // строки), 'below' — нижняя (территория нижней); без half — ровно M
                 if (half === 'above') y = (groups[0].bottom + M) / 2;
                 else if (half === 'below') y = (M + groups[1].top) / 2;
                 else y = M; }
          return [list.left + list.width / 2, y];
        }""", [kind, gid, half])

    def _over_point(self, x, y):
        self.page.evaluate("""([x, y]) => {
          document.getElementById('tabs-list').dispatchEvent(new DragEvent('dragover', {
            dataTransfer: window.__dt, bubbles: true, cancelable: true, clientX: x, clientY: y
          }));
        }""", [x, y])

    def _drop_point(self, x, y):
        self.page.evaluate("""([x, y]) => {
          document.getElementById('tabs-list').dispatchEvent(new DragEvent('drop', {
            dataTransfer: window.__dt, bubbles: true, cancelable: true, clientX: x, clientY: y
          }));
        }""", [x, y])

    def _end_drag(self):
        self.page.evaluate("""(() => {
          const card = window.__srcCard;
          if (card) card.dispatchEvent(new DragEvent('dragend', {bubbles: true, cancelable: true}));
        })()""")

    def _ghost(self):
        return json.loads(self.page.evaluate("""(() => {
          const slot = document.querySelector('.tab-ghost-slot');
          const nm = el => el && el.querySelector && el.querySelector('.tab-name')
            ? el.querySelector('.tab-name').textContent.trim() : null;
          const r = slot ? slot.getBoundingClientRect() : null;
          return JSON.stringify({
            exists: !!slot,
            hidden: slot ? getComputedStyle(slot).display === 'none' : false,
            top: r ? r.top : null,
            prevName: slot ? nm(slot.previousElementSibling) : null,
            nextName: slot ? nm(slot.nextElementSibling) : null,
            keepers: document.querySelectorAll('.tab-row-keeper').length
          });
        })()"""))

    def _names_groups(self):
        return json.loads(self.page.evaluate("""(async () => {
          const d = await chrome.storage.get('blattam-tabs');
          return JSON.stringify((d['blattam-tabs'] || []).map(t => [t.name, t.groupId || null]));
        })()"""))

    def _leftovers(self):
        return json.loads(self.page.evaluate("""() => JSON.stringify({
          slots: document.querySelectorAll('.tab-ghost-slot').length,
          keepers: document.querySelectorAll('.tab-row-keeper').length,
          clones: document.querySelectorAll('.pd-clone').length,
          srcDisplay: window.__srcCard ? window.__srcCard.style.display : null,
          srcConnected: window.__srcCard ? window.__srcCard.isConnected : null
        })"""))

    def _group_rows(self, gid):
        return self.page.evaluate("""(gid) => {
          const bar = document.querySelector('#tabs-list .gbar[data-group-id="' + gid + '"]');
          const tops = [];
          for (let el = bar ? bar.nextElementSibling : document.getElementById('tabs-list').firstElementChild;
               el && el.id !== 'add-group-btn' && !el.classList.contains('gbar') && !el.classList.contains('loose-label');
               el = el.nextElementSibling) {
            if (el.classList.contains('tab-ghost-slot') || el.classList.contains('tab-card') ||
                el.classList.contains('tab-row-keeper')) {
              const r = el.getBoundingClientRect();
              if (r.height > 0 && !tops.some(t => Math.abs(t - r.top) < 1)) tops.push(r.top);
            }
          }
          return tops.length;
        }""", gid)

    def test_ghost_visible_above_first_row_group(self):
        # (A) группа из 7 карточек (2 строки): курсор в зоне ВЫШЕ первой
        # строки (между .gbar и первой строкой) — ТЕРРИТОРИЯ первой строки:
        # заглушка видима в её полосе (owner по span, подход сверху -> 'after')
        self._load()
        self._start_drag("A5")
