        self._over_point(*self._band_point("above", "gA"))
        d = self._ghost()
        assert d["exists"] is True and d["hidden"] is False, d
        assert a1 - 1 <= d["top"] <= a1 + 1, (d, a1)  # в полосе первой строки
        assert d["prevName"] == "A3" and d["nextName"] == "A4", d
        self._end_drag()

