# ==========================================
#  VIEW.JS: POINTER-ДРАГ ШАПКИ ГРУППЫ (wave 2 «grab feel», реальный Chrome UX)
#  Press по имени/чепрону шапки (не по hover-кнопкам) + движение >8 px —
#  нативный HTML5-drag убивается (guard в dragstart: gbarPointerPress), ЦЕЛОЕ
#  отделение группы (gbar + её .tab-card + .group-empty-slot) вырывается
#  (display:none), всё ниже сдвигается ВВЕРХ одним FLIP-проходом (200ms ease),
#  header-pill клон (.pd-clone) следует за курсором 1:1, живой seam-индикатор
#  (волна 1) на целевой шапке. Релиз: на чужую шапку — reorderGroups (верхняя
#  половина = before, нижняя = after); вне шапок / Escape — cancel (renderTabs
#  восстанавливает раскладку, клон домой). Реальная Playwright-мышь;
#  синтетическая HTML5-цепочка харнесса (test_bar_drag_from_name_still_
#  reorders_groups) не тронута.
# ==========================================

class TestGbarPointerDrag:
    """Pointer drag of GROUP HEADERS (real Chrome UX, wave 2 «grab feel»,
    wave 3 gap-ghost): the group moves like a TAB CARD — the whole section is
    yanked, a warm full-width .gbar-ghost-slot walks the GAPS between the other
    groups (parting FLIP), commit happens at the slot's gap (between groups /
    at the list edges). Real Playwright mouse. The synthetic HTML5 DragEvent
    path (seam .drop-before/.drop-after) stays intact."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self.page_errors = []
        page.on("pageerror", lambda err: self.page_errors.append(str(err)))
        page.set_viewport_size({"width": 1280, "height": 900})
        self._load()

    SP = [{"id": "sp1", "name": "Main"}]
    GROUPS = [
        {"id": "g1", "name": "Dev", "spaceId": "sp1", "collapsed": False},
        {"id": "g2", "name": "Read", "spaceId": "sp1", "collapsed": False},
        {"id": "g3", "name": "Work", "spaceId": "sp1", "collapsed": False},
    ]
    TABS = [
        {"name": "D1", "url": "https://d1.com", "spaceId": "sp1", "groupId": "g1"},
        {"name": "D2", "url": "https://d2.com", "spaceId": "sp1", "groupId": "g1"},
        {"name": "R1", "url": "https://r1.com", "spaceId": "sp1", "groupId": "g2"},
        {"name": "W1", "url": "https://w1.com", "spaceId": "sp1", "groupId": "g3"},
        {"name": "W2", "url": "https://w2.com", "spaceId": "sp1", "groupId": "g3"},
    ]

    # === helpers ===

    def _load(self):
        load_view(self.page, tabs=self.TABS, spaces=self.SP, groups=self.GROUPS)
        # реальные стили — геометрия настоящая (карточки ~80px, не 41px)
        theme = load_file("theme.css")
        html = load_file("view.html")
        style = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate("(st) => { const el = document.createElement('style'); el.textContent = st; document.head.appendChild(el); }", theme + "\n" + style)
        self.page.wait_for_timeout(120)
        self.page.mouse.move(0, 0)  # парковка указателя: :hover не дёргает геометрию
        self.page.wait_for_timeout(40)

    def _gname_box(self, gid):
        return self.page.evaluate("""(gid) => {
            const bar = document.querySelector('#tabs-list .gbar[data-group-id="' + gid + '"]');
            const g = bar.querySelector('.gname');
            const r = g.getBoundingClientRect();
            return {x: r.x + r.width/2, y: r.y + r.height/2, left: r.left, top: r.top, width: r.width, height: r.height};
        }""", gid)

    def _gbar_box(self, gid):
        return self.page.evaluate("""(gid) => {
            const bar = document.querySelector('#tabs-list .gbar[data-group-id="' + gid + '"]');
            const r = bar.getBoundingClientRect();
            return {x: r.x + r.width/2, y: r.y + r.height/2, left: r.left, top: r.top,
                    right: r.right, bottom: r.bottom, width: r.width, height: r.height};
        }""", gid)

    def _group_card_els(self, gid):
        return self.page.evaluate("""(gid) => {
            return [...document.querySelectorAll('#tabs-list .tab-card')]
              .filter(c => c.__tab && c.__tab.groupId === gid)
              .map(c => c.style.display);
        }""", gid)

    def _gbar_display(self, gid):
        return self.page.evaluate("document.querySelector('#tabs-list .gbar[data-group-id=\"%s\"]').style.display" % gid)

    def _all_visible(self):
        return self.page.evaluate("""() => [...document.querySelectorAll('#tabs-list .gbar, #tabs-list .tab-card')]
            .every(el => getComputedStyle(el).display !== 'none')""")

    def _press_gbar(self, gid):
        pt = self._gname_box(gid)
        self.page.mouse.move(pt["x"], pt["y"], steps=3)
        self.page.wait_for_timeout(60)
        self.page.mouse.down()
        self.page.wait_for_timeout(60)
        return pt

    def _gmove(self, from_pt, to_pt, steps=10):
        for i in range(1, steps + 1):
            self.page.mouse.move(from_pt["x"] + (to_pt["x"] - from_pt["x"]) * i / steps,
                                 from_pt["y"] + (to_pt["y"] - from_pt["y"]) * i / steps)

    def _clone_state(self):
        return self.page.evaluate("""() => {
            const c = document.querySelector('.pd-clone');
            if (!c) return null;
            const s = c.style.transform;
            const a = s.indexOf('translate3d('), b = s.indexOf(')', a);
            const parts = s.slice(a + 12, b).split(',');
            return {inBody: c.parentElement === document.body,
                    fixed: getComputedStyle(c).position === 'fixed',
                    x: parseFloat(parts[0]), y: parseFloat(parts[1])};
        }""")

    def _group_order(self):
        return [g["id"] for g in read_storage_raw(self.page, "blattam-groups")]

    def _collapsed(self, gid):
        return [g["collapsed"] for g in read_storage_raw(self.page, "blattam-groups") if g["id"] == gid][0]

    def _leftovers(self):
        return self.page.evaluate("""() => ({
            clone: !!document.querySelector('.pd-clone'),
            slot: !!document.querySelector('.gbar-ghost-slot'),
            seam: document.querySelectorAll('.gbar.drop-before, .gbar.drop-after').length,
            hidden: [...document.querySelectorAll('#tabs-list .gbar, #tabs-list .tab-card')]
                    .filter(el => getComputedStyle(el).display === 'none').length,
            cursor: document.body.style.cursor
        })""")

    def _group_write_count(self):
        """Счётчик записей blattam-groups в mock storage (спай на sync.set)."""
        self.page.evaluate("""(() => {
            if (!window.__gWrites) {
                window.__gWrites = 0;
                const orig = chrome.storage.sync.set.bind(chrome.storage.sync);
                chrome.storage.sync.set = function(data, cb) {
                    if (data && data['blattam-groups']) window.__gWrites++;
                    return orig(data, cb);
                };
            }
        })()""")
        return self.page.evaluate("window.__gWrites")

    def _arm_down(self, gid, dy=40, settle=300):
        """press + арм (движение >8px вниз). Pointer остаётся зажатым; после
        оседания FLIP-слайда (200ms) геометрия стабильна — ре-замер целей."""
        pt = self._press_gbar(gid)
        self._gmove(pt, {"x": pt["x"], "y": pt["y"] + dy}, steps=6)
        self.page.wait_for_timeout(settle)
        return pt

    def _slot_info(self):
        """Позиция тёплой .gbar-ghost-slot в #tabs-list (соседи, размер, тон)."""
        return self.page.evaluate("""() => {
            const slot = document.querySelector('#tabs-list .gbar-ghost-slot');
            if (!slot) return null;
            const kids = [...document.getElementById('tabs-list').children];
            const i = kids.indexOf(slot);
            const prev = i > 0 ? kids[i - 1] : null;
            const next = i + 1 < kids.length ? kids[i + 1] : null;
            const gidOf = el => !el ? null : (el.__tab ? el.__tab.groupId
                : (el.dataset && el.dataset.groupId ? el.dataset.groupId : null));
            const r = slot.getBoundingClientRect();
            return {idx: i, prevCls: prev ? prev.className : null, prevGid: gidOf(prev),
                    nextCls: next ? next.className : null, nextGid: gidOf(next),
                    width: r.width, height: r.height,
                    warm: getComputedStyle(slot).borderStyle === 'dashed'};
        }""")

    def _section_box(self, gid):
        """Layout-box групповой секции (верх gbar → низ последней карточки),
        то же правило, что gpdGroupSections в view.js."""
        return self.page.evaluate("""(gid) => {
            const list = document.getElementById('tabs-list');
            const isG = el => el.__tab ? el.__tab.groupId === gid
                : (el.dataset && el.dataset.groupId === gid);
            let top = null, bottom = null, x = null;
            for (const el of list.children) {
                if (el.classList.contains('gbar')) {
                    if (el.dataset.groupId === gid) {
                        const r = el.getBoundingClientRect();
                        top = r.top; bottom = r.bottom; x = r.x + r.width / 2;
                    } else if (top !== null) break;
                    continue;
                }
                if (el.classList.contains('loose-label') || el.id === 'add-group-btn') {
                    if (top !== null) break;
                    continue;
                }
                if (top !== null && isG(el) && el.getBoundingClientRect().height > 0)
                    bottom = el.getBoundingClientRect().bottom;
            }
            return {top, bottom, x};
        }""", gid)

    # === tests ===

    def test_no_arm_under_8px(self):
        pt = self._press_gbar("g1")
        # движение <8px — драг не вооружается (проверяем, пока pointer зажат,
        # до релиза: сам релиз — это обычный клик, свернуть группу — отдельно)
        self.page.mouse.move(pt["x"] + 5, pt["y"])
        self.page.wait_for_timeout(60)
        assert self._clone_state() is None
        assert self.page.evaluate("!!document.querySelector('.pd-clone')") is False
        assert self.page.evaluate("!!document.querySelector('.gbar-ghost-slot')") is False
        assert self.page.evaluate("document.querySelectorAll('#tabs-list .gbar').length") == 3
        assert self._gbar_display("g1") != 'none'
        assert all(d != 'none' for d in self._group_card_els("g1"))
        self.page.mouse.up()
        self.page.wait_for_timeout(120)

    def test_plain_click_still_collapses(self):
        before = self._collapsed("g1")
        self._press_gbar("g1")
        self.page.mouse.up()  # без движения — обычный клик по шапке
        self.page.wait_for_timeout(150)
        after = self._collapsed("g1")
        assert after != before, (before, after)
        assert self._clone_state() is None
        assert self.page.evaluate("!!document.querySelector('.gbar-ghost-slot')") is False

    def test_yank_out_and_part(self):
        s2_before = self._section_box("g2")["top"]
        self._arm_down("g1")  # арм: вниз, к g2
        # целое отделение g1 вырвано: gbar + все её карточки display:none
        assert self._gbar_display("g1") == 'none'
        assert all(d == 'none' for d in self._group_card_els("g1"))
        c = self._clone_state()
        assert c is not None and c["inBody"] and c["fixed"]
        # тёплая полноширинная заглушка ЕСТЬ: grid-column 1/-1 (ширина списка),
        # пунктирный тёплый тон, высота вырванного отделения (не 2px-линия)
        sl = self._slot_info()
        assert sl is not None, "no .gbar-ghost-slot"
        assert sl["warm"], sl
        lw = self.page.evaluate("document.getElementById('tabs-list').getBoundingClientRect().width")
        assert sl["width"] >= lw - 2, (sl["width"], lw)
        assert sl["height"] > 50, sl
        # группа НИЖЕ g1 поднялась (parting FLIP): layout top меньше, чем до арма
        s2_after = self._section_box("g2")["top"]
        assert s2_after < s2_before, (s2_before, s2_after)
        self.page.mouse.up()  # релиз в зазоре (внутри списка) — коммит по зазору
        self.page.wait_for_timeout(300)
        assert self._group_order() == ["g2", "g1", "g3"], self._group_order()

    def test_clone_follows_cursor(self):
        pt = self._press_gbar("g1")
        arm = {"x": pt["x"], "y": pt["y"] + 40}
        self._gmove(pt, arm, steps=6)
        self.page.wait_for_timeout(300)  # FLIP-слайд оседает — геометрия стабильна
        p1 = self._clone_state()
        assert p1 is not None
        # сдвигаем КУРСОР на +40,+20 — клон следует за курсором 1:1
        self.page.mouse.move(arm["x"] + 40, arm["y"] + 20)
        self.page.wait_for_timeout(40)
        p2 = self._clone_state()
        assert abs((p2["x"] - p1["x"]) - 40) < 1.5, (p1, p2)
        assert abs((p2["y"] - p1["y"]) - 20) < 1.5, (p1, p2)
        self.page.mouse.up()
        self.page.wait_for_timeout(200)

    def test_ghost_slot_tracks_gap(self):
        self._arm_down("g1")
        assert self._slot_info() is not None
        # hover в зазоре между g2 и g3 (выше геометрической середины зазора —
        # его границы) — заглушка в ЭТОМ зазоре (между секциями, FLIP-переезд)
        b2 = self._section_box("g2"); b3 = self._section_box("g3")
        gy = b2["bottom"] + (b3["top"] - b2["bottom"]) * 0.25
        self.page.mouse.move(b2["x"], gy, steps=4)
        self.page.wait_for_timeout(300)
        sl = self._slot_info()
        assert sl is not None
        assert sl["nextGid"] == "g3" and "gbar" in sl["nextCls"], sl  # сразу перед шапкой g3
        assert sl["prevGid"] == "g2", sl  # и сразу после секции g2
        # hover у ВЕРХНЕЙ кромки (выше первой группы) — заглушка ПЕРЕД первой
        b2 = self._section_box("g2")  # ре-замер после FLIP
        self.page.mouse.move(b2["x"], b2["top"] - 12, steps=4)
        self.page.wait_for_timeout(300)
        sl = self._slot_info()
        assert sl is not None
        assert sl["nextGid"] == "g2" and "gbar" in sl["nextCls"], sl
        # релиз ВЫШЕ топ-зоны (60px над верхом списка > 24px-полоса) — cancel:
        # порядок без изменений, следов нет
        self.page.mouse.move(b2["x"], b2["top"] - 60, steps=3)
        self.page.wait_for_timeout(150)
        self.page.mouse.up()
        self.page.wait_for_timeout(300)
        assert self._group_order() == ["g1", "g2", "g3"], self._group_order()
        lv = self._leftovers()
        assert lv == {"clone": False, "slot": False, "seam": 0, "hidden": 0, "cursor": ""}, lv

    def test_commit_between_groups(self):
        # зазор между g2 и g3 — коммит: g1 встаёт МЕЖДУ ними
        self._arm_down("g1")
        b2 = self._section_box("g2"); b3 = self._section_box("g3")
        gy = b2["bottom"] + (b3["top"] - b2["bottom"]) * 0.25  # зазор, выше середины
        self.page.mouse.move(b2["x"], gy, steps=4)
        self.page.wait_for_timeout(150)
        self.page.mouse.up()
        self.page.wait_for_timeout(300)
        assert self._group_order() == ["g2", "g1", "g3"], self._group_order()

    def test_commit_at_edge(self):
        # НИЖНЯЯ кромка: ниже последней группы (внутри #tabs-list) — после последней
        self._arm_down("g1")
        b3 = self._section_box("g3")
        self.page.mouse.move(b3["x"], b3["bottom"] + 30, steps=4)
        self.page.wait_for_timeout(150)
        self.page.mouse.up()
        self.page.wait_for_timeout(300)
        assert self._group_order() == ["g2", "g3", "g1"], self._group_order()
        # ВЕРХНЯЯ кромка ВЫШЕ топ-зоны (60px над верхом списка > 24px-полоса)
        # — cancel: порядок без изменений, следов нет (полоса 24px — отдельный
        # тест test_commit_at_top_band)
        self._load()
        self._arm_down("g2")
        b1 = self._section_box("g1")
        self.page.mouse.move(b1["x"], b1["top"] - 60, steps=4)
        self.page.wait_for_timeout(300)
        self.page.mouse.up()
        self.page.wait_for_timeout(300)
        assert self._group_order() == ["g1", "g2", "g3"], self._group_order()
        lv = self._leftovers()
        assert lv == {"clone": False, "slot": False, "seam": 0, "hidden": 0, "cursor": ""}, lv

    def test_commit_at_top_band(self):
        # ТОП-ЗОНА: релиз в полосе 24px над верхом #tabs-list (в пределах ширины
        # колонки) при заглушке перед первой группой — коммит «перед первой»
        # (у списка нет top-padding — внутри списка зона недостижима)
        self._arm_down("g2")
        b1 = self._section_box("g1")
        self.page.mouse.move(b1["x"], b1["top"] - 12, steps=4)
        self.page.wait_for_timeout(300)
        sl = self._slot_info()
        assert sl is not None
        assert sl["nextGid"] == "g1" and "gbar" in sl["nextCls"], sl
        self.page.mouse.up()
        self.page.wait_for_timeout(300)
        assert self._group_order() == ["g2", "g1", "g3"], self._group_order()
        lv = self._leftovers()
        assert lv == {"clone": False, "slot": False, "seam": 0, "hidden": 0, "cursor": ""}, lv

    def test_noop_drop_own_slot_restores_section(self):
        # no-op-дроп: группа возвращена в собственный слот (зазор g1–g3 —
        # её исходная позиция) — порядок не меняется, запись в storage нет
        # (no-op-guard в reorderGroups). Регрессия реального Chrome: set
        # равного значения НЕ шлёт onChanged (mock шлёт — баг в харнессе
        # незаметен), поэтому при no-op-коммите раскладку обязан
        # перерисовать сам pointer-путь — иначе вырванное отделение
        # остаётся display:none до чужой записи (группа «пропадает»)
        before = self._group_write_count()
        self._arm_down("g2")
        b1 = self._section_box("g1"); b3 = self._section_box("g3")
        gy = b1["bottom"] + (b3["top"] - b1["bottom"]) * 0.25  # зазор g1–g3
        self.page.mouse.move(b1["x"], gy, steps=4)
        self.page.wait_for_timeout(300)
        sl = self._slot_info()
        assert sl is not None
        # слот сразу ПЕРЕД шапкой g3 (prev — вырванное, но ещё в DOM
        # отделение g2 — display:none)
        assert sl["prevGid"] == "g2" and sl["nextGid"] == "g3" \
            and "gbar" in sl["nextCls"], sl
        self.page.mouse.up()
        self.page.wait_for_timeout(300)
        # отделение g2 ВИДНО (gbar + карточки не display:none)
        assert self._gbar_display("g2") != 'none'
        assert self.page.evaluate("""() => [...document.querySelectorAll('#tabs-list .tab-card')]
            .filter(c => c.__tab && c.__tab.groupId === 'g2')
            .every(c => getComputedStyle(c).display !== 'none')""") is True
        assert self._group_order() == ["g1", "g2", "g3"], self._group_order()
        # no-op-guard: запись blattam-groups не ушла
        assert self._group_write_count() == before, self._group_write_count()
        lv = self._leftovers()
        assert lv == {"clone": False, "slot": False, "seam": 0, "hidden": 0, "cursor": ""}, lv

    def test_cancel_outside(self):
        before = self._group_order()
        self._arm_down("g1")  # арм
        self.page.mouse.move(110, 300)  # релиз ВНЕ #tabs-list (левая рейка)
        self.page.wait_for_timeout(60)
        self.page.mouse.up()
        self.page.wait_for_timeout(300)
        assert self._group_order() == before
        lv = self._leftovers()
        assert lv == {"clone": False, "slot": False, "seam": 0, "hidden": 0, "cursor": ""}, lv
        assert self.page.evaluate("document.querySelectorAll('#tabs-list .gbar').length") == 3
        assert self._all_visible()

    def test_escape_cancels(self):
        before = self._group_order()
        self._arm_down("g1")  # арм
        self.page.keyboard.press("Escape")
        self.page.wait_for_timeout(300)
        assert self._group_order() == before
        lv = self._leftovers()
        assert lv == {"clone": False, "slot": False, "seam": 0, "hidden": 0, "cursor": ""}, lv
        assert self._all_visible()

    def test_no_leftovers(self):
        # после коммита (зазор между g2 и g3) — никаких следов
        self._arm_down("g1")
        b2 = self._section_box("g2"); b3 = self._section_box("g3")
        gy = b2["bottom"] + (b3["top"] - b2["bottom"]) * 0.25
        self.page.mouse.move(b2["x"], gy, steps=4)
        self.page.wait_for_timeout(150)
        self.page.mouse.up()
        self.page.wait_for_timeout(400)
        lv = self._leftovers()
        assert lv == {"clone": False, "slot": False, "seam": 0, "hidden": 0, "cursor": ""}, lv
        # после cancel (чистый порядок) — тоже без следов
        self._load()
        self._arm_down("g1")
        self.page.mouse.move(110, 300)
        self.page.wait_for_timeout(60)
        self.page.mouse.up()
        self.page.wait_for_timeout(400)
        lv2 = self._leftovers()
        assert lv2 == {"clone": False, "slot": False, "seam": 0, "hidden": 0, "cursor": ""}, lv2


# ==========================================

class TestEmptyGroupAlwaysCollapsed:
    """Пустая группа НЕ РАСКРЫВАЕТСЯ (возможность раскрытия убрана): всегда
    рендерится в свёрнутом виде (gbar-collapsed, «▸», «0 вкладок»), .group-empty-slot
    в DOM нет вообще. Клик по шапке пустой группы — no-op (blattam-groups не пишется);
    непустая группа сворачивается/раскрывается кликом, как раньше. Дроп карточки на
    шапку пустой группы — вкладка в группу, группа стала непустой и разворачивается.
    Pointer-драг шапки над другой пустой группой — заглушка в ЗАЗОРЕ (внутреннего
    якоря нет — нет слота), коммит и порядок прежние, без следов."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self.page_errors = []
        page.on("pageerror", lambda err: self.page_errors.append(str(err)))
        page.set_viewport_size({"width": 1280, "height": 900})

    SP = [{"id": "sp1", "name": "Main"}]

    def _load(self, groups, tabs=None):
        load_view(self.page, tabs=tabs or [], spaces=self.SP, groups=groups)
        theme = load_file("theme.css")
        html = load_file("view.html")
        style = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate("(st) => { const el = document.createElement('style'); el.textContent = st; document.head.appendChild(el); }", theme + "\n" + style)
        self.page.wait_for_timeout(120)
        self.page.mouse.move(0, 0)  # парковка указателя: :hover не дёргает геометрию
        self.page.wait_for_timeout(40)

    def _empty_groups(self, ids):
        return [{"id": i, "name": i.upper(), "spaceId": "sp1", "collapsed": False} for i in ids]

    def _slots(self):
        return self.page.evaluate("document.querySelectorAll('#tabs-list .group-empty-slot').length")

    def _bar_state(self, gid):
        return json.loads(self.page.evaluate("""(gid) => {
            const bar = document.querySelector('#tabs-list .gbar[data-group-id="' + gid + '"]');
            return JSON.stringify({
                collapsed: bar.classList.contains('gbar-collapsed'),
                chev: bar.querySelector('.chev').textContent,
                count: bar.querySelector('.gcount').textContent
            });
        }""", gid))

    def _group_of(self, name):
        tabs = read_storage_raw(self.page, "blattam-tabs")
        return next((t.get("groupId") for t in tabs if t["name"] == name), "MISSING")

    def _group_order(self):
        return [g["id"] for g in read_storage_raw(self.page, "blattam-groups")]

    def _gname_pt(self, gid):
        return self.page.evaluate("""(gid) => {
            const el = document.querySelector('#tabs-list .gbar[data-group-id="' + gid + '"] .gname');
            const r = el.getBoundingClientRect();
            return {x: r.x + r.width / 2, y: r.y + r.height / 2};
        }""", gid)

    def _slot_info(self):
        """Позиция тёплой .gbar-ghost-slot в #tabs-list (соседи)."""
        return self.page.evaluate("""() => {
            const slot = document.querySelector('#tabs-list .gbar-ghost-slot');
            if (!slot) return null;
            const kids = [...document.getElementById('tabs-list').children];
            const i = kids.indexOf(slot);
            const prev = i > 0 ? kids[i - 1] : null;
            const next = i + 1 < kids.length ? kids[i + 1] : null;
            const gidOf = el => !el ? null : (el.__tab ? el.__tab.groupId
                : (el.dataset && el.dataset.groupId ? el.dataset.groupId : null));
            return {idx: i, prevCls: prev ? prev.className : null, prevGid: gidOf(prev),
                    nextCls: next ? next.className : null, nextGid: gidOf(next)};
        }""")

    def _leftovers(self):
        return self.page.evaluate("""() => ({
            clone: !!document.querySelector('.pd-clone'),
            slot: !!document.querySelector('.gbar-ghost-slot'),
            seam: document.querySelectorAll('.gbar.drop-before, .gbar.drop-after').length,
            hidden: [...document.querySelectorAll('#tabs-list .gbar, #tabs-list .tab-card')]
                    .filter(el => getComputedStyle(el).display === 'none').length,
            cursor: document.body.style.cursor
        })""")

    # === tests ===

    def test_click_empty_group_bar_is_noop(self):
        # Клик по шапке пустой группы (данные collapsed=False): не раскрывает —
        # вид свёрнутый, blattam-groups не пишется
        self._load(self._empty_groups(["g1"]))
        before = json.dumps(read_storage_raw(self.page, "blattam-groups"), sort_keys=True)
        self.page.evaluate("document.querySelector('#tabs-list .gbar[data-group-id=\\\"g1\\\"]').click()")
        self.page.wait_for_timeout(80)
        assert json.dumps(read_storage_raw(self.page, "blattam-groups"), sort_keys=True) == before
        d = self._bar_state("g1")
        assert d == {"collapsed": True, "chev": "▸", "count": "0 вкладок"}, d
        assert self._slots() == 0

    def test_nonempty_group_still_toggles(self):
        # Регрессия: непустая группа кликом сворачивается и раскрывается,
        # карточки уходят из DOM/возвращаются
        self._load(self._empty_groups(["g1"]),
                   tabs=[{"name": "T1", "url": "https://t1.com", "spaceId": "sp1", "groupId": "g1"}])
        d = self._bar_state("g1")
        assert d == {"collapsed": False, "chev": "▾", "count": "1 вкладка"}, d
        self.page.evaluate("document.querySelector('#tabs-list .gbar[data-group-id=\\\"g1\\\"]').click()")
        self.page.wait_for_timeout(80)
        d = self._bar_state("g1")
        assert d["collapsed"] is True and d["chev"] == "▸", d
        assert self.page.evaluate("document.querySelectorAll('#tabs-list .tab-card').length") == 0
        self.page.evaluate("document.querySelector('#tabs-list .gbar[data-group-id=\\\"g1\\\"]').click()")
        self.page.wait_for_timeout(80)
        d = self._bar_state("g1")
        assert d["collapsed"] is False and d["chev"] == "▾", d
        assert self.page.evaluate("document.querySelectorAll('#tabs-list .tab-card').length") == 1

    def test_drop_card_on_empty_bar_expands_group(self):
        # Дроп карточки на шапку пустой группы: вкладка в группу (place-tab),
        # группа стала непустой — развёрнута (▾), карточка видна, слота нет
        self._load(self._empty_groups(["g1"]),
                   tabs=[{"name": "T", "url": "https://t.com", "spaceId": "sp1"}])
        self.page.evaluate("""() => {
            const card = document.querySelector('#tabs-list .tab-card');
            const bar = document.querySelector('#tabs-list .gbar[data-group-id="g1"]');
            const dt = new DataTransfer();
            card.dispatchEvent(new DragEvent('dragstart', {dataTransfer: dt, bubbles: true}));
            bar.dispatchEvent(new DragEvent('dragover', {dataTransfer: dt, bubbles: true, cancelable: true}));
            bar.dispatchEvent(new DragEvent('drop', {dataTransfer: dt, bubbles: true, cancelable: true}));
            card.dispatchEvent(new DragEvent('dragend', {bubbles: true}));
        }""")
        self.page.wait_for_timeout(80)
        assert self._group_of("T") == "g1"
        d = self._bar_state("g1")
        assert d == {"collapsed": False, "chev": "▾", "count": "1 вкладка"}, d
        assert self._slots() == 0
        assert self.page.evaluate("document.querySelectorAll('#tabs-list .tab-card').length") == 1

    def test_gbar_drag_over_empty_group_ghost_in_gap(self):
        # Pointer-драг шапки g1 над пустой g2 (реальная Playwright-мышь):
        # заглушка в ЗАЗОРЕ (prev — g2-gbar, next — НЕ .group-empty-slot, его
        # нет), дроп — порядок [g2, g1], без следов
        self._load(self._empty_groups(["g1", "g2"]))
        assert self._slots() == 0
        pt = self._gname_pt("g1")
        self.page.mouse.move(pt["x"], pt["y"], steps=3)
        self.page.wait_for_timeout(60)
        self.page.mouse.down()
        self.page.wait_for_timeout(60)
        for i in range(1, 7):  # arm: >8px вниз
            self.page.mouse.move(pt["x"], pt["y"] + 40 * i / 6)
            self.page.wait_for_timeout(10)
        self.page.wait_for_timeout(320)  # оседание FLIP-слайда (200ms)
        box = self.page.evaluate("""(() => {
            const bar = document.querySelector('#tabs-list .gbar[data-group-id="g2"]');
            const r = bar.getBoundingClientRect();
            return {x: r.x + r.width / 2, y: r.bottom + 10};
        })()""")
        self.page.mouse.move(box["x"], box["y"], steps=8)
        self.page.wait_for_timeout(200)
        si = self._slot_info()
        assert si is not None, "тёплая заглушка не появилась"
        assert si["prevCls"] and "gbar" in si["prevCls"] and si["prevGid"] == "g2", si
        assert si["nextCls"] != "group-empty-slot", si
        self.page.mouse.up()
        self.page.wait_for_timeout(300)
        assert self._group_order() == ["g2", "g1"], self._group_order()
        assert self._leftovers() == {"clone": False, "slot": False, "seam": 0, "hidden": 0, "cursor": ""}

    def test_no_slot_with_three_empty_groups(self):
        # 3 пустые группы (данные collapsed false/false/true): слотов нигде нет,
        # все три шапки в свёрнутом виде; строка «+ Группа» из списка удалена
        self._load(self._empty_groups(["g1", "g2"]) + [
            {"id": "g3", "name": "G3", "spaceId": "sp1", "collapsed": True}])
        assert self._slots() == 0
        for gid in ("g1", "g2", "g3"):
            d = self._bar_state(gid)
            assert d == {"collapsed": True, "chev": "▸", "count": "0 вкладок"}, (gid, d)
        assert self.page.evaluate("document.getElementById('add-group-btn')") is None
        assert json.loads(self.page.evaluate(
            "JSON.stringify([...document.getElementById('tabs-list').children].map(e => e.className))")) == \
            ["gbar gbar-collapsed", "gbar gbar-collapsed", "gbar gbar-collapsed"]

# ==========================================
#  Quick search (experimental mode)
# ==========================================
class TestQuickSearch:
    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page

    TABS = [
        {"name": "Питон", "url": "https://python.org"},
        {"name": "Гитхаб", "url": "https://github.com"},
        {"name": "Таблица", "url": "https://table.example"},
    ]

    def _key(self, key):
        self.page.evaluate(f"""(() => {{
          document.dispatchEvent(new KeyboardEvent('keydown', {{key: '{key}', bubbles: true, cancelable: true}}));
        }})()""")

    def _card_names(self):
        return json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('.tab-card .tab-name')].map(e => e.textContent))"))

    def _search_value(self):
        return self.page.evaluate("document.getElementById('search').value")

    def _overlay_letter(self):
        return self.page.evaluate("document.getElementById('qs-letter').textContent")

    def _overlay_opacity(self):
        return float(self.page.evaluate(
            "getComputedStyle(document.getElementById('qs-overlay')).opacity"))

    def _inject_real_styles(self):
        # Harness sets only body.innerHTML — load the real styles (theme.css + view.html style block)
        theme = load_file("theme.css")
        html = load_file("view.html")
        style = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate(
            "(styles) => { var st = document.createElement('style'); st.textContent = styles; document.head.appendChild(st); }",
            [theme + "\n" + style])

    def _open_settings(self):
        self.page.evaluate("document.getElementById('settings-btn').click()")

    def _open_pane(self, section):
        self.page.locator("#settings-modal .settings-nav-item[data-section='" + section + "']").click()

    def _flip_toggle(self):
        self._open_pane("experimental")
        self.page.evaluate("""(() => {
          const t = document.getElementById('qs-toggle');
          t.click();
          t.dispatchEvent(new Event('change', {bubbles: true}));
        })()""")

    # --- Settings ---

    def test_settings_section_toggle_default_off(self):
        load_view(self.page, tabs=self.TABS)
        self._open_settings()
        assert self.page.evaluate("!!document.getElementById('qs-section')")
        assert self.page.evaluate(
            "document.querySelector('#qs-section .settings-section-title').textContent") == "Экспериментальное"
        assert not self.page.evaluate("document.getElementById('qs-toggle').checked")

    def test_toggle_writes_storage(self):
        load_view(self.page, tabs=self.TABS)
        self._open_settings()
        self._flip_toggle()
        assert self.page.evaluate("chrome.storage.local._data['blattam-quick-search']") is True
        self._flip_toggle()
        assert self.page.evaluate("chrome.storage.local._data['blattam-quick-search']") is False

    def test_toggle_reflects_seeded_storage(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self._open_settings()
        assert self.page.evaluate("document.getElementById('qs-toggle').checked")

    # --- Letters ---

    def test_letter_starts_search_without_click(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self._key("п")
        assert self._search_value() == "п"
        assert self._card_names() == ["Питон"]
        assert self._overlay_letter() == "п"

    def test_letter_updates_overlay_and_query(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self._key("п")
        self._key("т")
        assert self._search_value() == "пт"
        assert self._overlay_letter() == "т"
        assert self._card_names() == []  # «пт» matches nothing — live filter

    def test_overlay_fades_out(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self._inject_real_styles()
        self._key("п")
        # right after the keystroke the overlay is fully visible (fade just started)
        assert self._overlay_opacity() > 0.9
        self.page.wait_for_timeout(900)
        assert self._overlay_opacity() < 0.05

    def test_digits_and_symbols_ignored(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self._key("5")
        self._key("!")
        self._key(" ")
        assert self._search_value() == ""
        assert self._overlay_letter() == ""
        assert self._card_names() == ["Питон", "Гитхаб", "Таблица"]

    def test_disabled_by_default(self):
        load_view(self.page, tabs=self.TABS)  # no quick_search seed — mode off
        self._key("п")
        assert self._search_value() == ""
        assert self._overlay_letter() == ""
        assert self._card_names() == ["Питон", "Гитхаб", "Таблица"]

    def test_uppercase_shift_letter(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self._key("П")
        assert self._search_value() == "П"
        assert self._overlay_letter() == "П"
        assert self._card_names() == ["Питон"]  # search is case-insensitive

    def test_escape_clears_and_hides_overlay(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self._inject_real_styles()
        self._key("п")
        self._key("т")
        self._key("Escape")
        assert self._search_value() == ""
        assert self._card_names() == ["Питон", "Гитхаб", "Таблица"]
        assert self._overlay_opacity() < 0.05

    def test_backspace_deletes_last_char(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self._key("п")
        self._key("т")
        assert self._search_value() == "пт"
        self._key("Backspace")
        assert self._search_value() == "п"
        assert self._card_names() == ["Питон"]
        self._key("Backspace")
        assert self._search_value() == ""
        assert self._card_names() == ["Питон", "Гитхаб", "Таблица"]
        # Backspace on an empty query — old behavior: no active card, nothing deleted
        self._key("Backspace")
        assert [t["name"] for t in read_storage_raw(self.page, "blattam-tabs")] == ["Питон", "Гитхаб", "Таблица"]

    def test_letter_ignored_when_search_focused(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self.page.evaluate("document.getElementById('search').focus()")
        self._key("п")
        # the global handler must not double-process a focused editable field
        assert self._search_value() == ""

    def test_letter_ignored_when_modal_open(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self._open_settings()
        self._key("п")
        assert self._search_value() == ""
        assert self._overlay_letter() == ""

    def test_toggle_off_hides_overlay(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self._inject_real_styles()
        self._key("п")
        assert self._overlay_opacity() > 0.9
        self._open_settings()
        self._flip_toggle()
        assert self.page.evaluate("chrome.storage.local._data['blattam-quick-search']") is False
        assert self._overlay_opacity() < 0.05

# ==========================================
#  Quick search — focus grab (Ctrl+T / "+" leaves focus in the omnibox)
# ==========================================

class TestQuickSearchFocus:
    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page

    TABS = [{"name": "Питон", "url": "https://python.org"}]

    def test_focus_init_called_when_quick_search_on(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self.page.wait_for_timeout(800)
        assert self.page.evaluate("window.__qsFocusInitCalls") >= 1

    def test_focus_init_not_called_when_quick_search_off(self):
        load_view(self.page, tabs=self.TABS)
        self.page.wait_for_timeout(800)
        assert self.page.evaluate("window.__qsFocusInitCalls") == 0

    def test_grab_focus_moves_focus_to_body(self):
        load_view(self.page, tabs=self.TABS, quick_search=True)
        self.page.evaluate("document.getElementById('settings-btn').focus()")
        assert self.page.evaluate("document.activeElement.id") == "settings-btn"
        self.page.evaluate("grabPageFocus(true)")
        assert self.page.evaluate("document.activeElement.tagName") == "BODY"


class TestRailCenterTerritories:
    """Rail tab drag to center: the central ghost walks by the SAME territory
    rules as the card drag (cursorCardAnchor): row midpoint tiling, touch
    freeze on entering a card's rect, the ghost's own cell is STICKY, the
    empty end of a row keeps the legacy tail, the bottom band of the list =
    ghost hidden + drop cancels, and the drop resolves the slot like
    placeCardToSlot (a mid-section "after" lands right after the card — not
    at the end of the section). Geometry: styled page (theme.css + view.html
    <style>), viewport 1280x800, 3 loose cards in one 5-column row, 12px
    gaps, 110px bottom padding band."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self._errors = []
        page.on("pageerror", self._on_err)
        yield
        assert not self._errors, self._errors
        page.remove_listener("pageerror", self._on_err)

    def _on_err(self, err):
        self._errors.append(str(err))

    BT = [
        {"id": "bt1", "title": "Wiki", "url": "https://wiki.example",
         "favIconUrl": "https://fav.example/1.ico", "windowId": 1, "index": 0},
        {"id": "bt2", "title": "Mail", "url": "https://mail.example",
         "favIconUrl": "https://fav.example/2.ico", "windowId": 1, "index": 1},
    ]
    SP = [{"id": "sp1", "name": "Main"}]
    TABS3 = [
        {"name": "A", "url": "https://a.com", "spaceId": "sp1"},
        {"name": "B", "url": "https://b.com", "spaceId": "sp1"},
        {"name": "C", "url": "https://c.com", "spaceId": "sp1"},
    ]
    GROUPS = [{"id": "g1", "name": "Grp", "spaceId": "sp1", "collapsed": False}]

    def _load(self, tabs=None, groups=None):
        load_view(self.page, tabs=self.TABS3 if tabs is None else tabs,
                  spaces=self.SP, groups=groups, browser_tabs=self.BT)
        css = load_file("theme.css")
        html = load_file("view.html")
        style_block = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate("""(css) => {
          const s = document.createElement('style');
          s.textContent = css;
          document.head.appendChild(s);
        }""", css + style_block)
        self.page.set_viewport_size({"width": 1280, "height": 800})
        self.page.mouse.move(0, 0)
        self.page.wait_for_timeout(150)

    # === geometry helpers ===

    def _cards(self):
        return json.loads(self.page.evaluate("""(() => JSON.stringify(
            [...document.querySelectorAll('#tabs-list .tab-card')].map(c => {
                const r = c.getBoundingClientRect();
                return {left: r.left, top: r.top, right: r.right, bottom: r.bottom,
                        width: r.width, height: r.height,
                        name: c.querySelector('.tab-name').textContent.trim()};
            })))()"""))

    def _slot(self):
        return self.page.evaluate("""(() => {
            const s = document.querySelector('#tabs-list .tab-ghost-slot');
            if (!s) return null;
            const r = s.getBoundingClientRect();
            return {left: r.left, top: r.top, right: r.right, bottom: r.bottom,
                    x: r.left + r.width / 2, y: r.top + r.height / 2,
                    display: getComputedStyle(s).display};
        })()""")

    def _slot_order(self):
        return json.loads(self.page.evaluate("""(() => JSON.stringify(
            [...document.getElementById('tabs-list').children].map(c =>
                c.classList.contains('tab-card') ? 'card' :
                (c.classList.contains('tab-ghost-slot') && c.style.display !== 'none') ? 'slot' : 'other')))()"""))

    def _center_names(self):
        return json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('#tabs-list .tab-card .tab-name')].map(e => e.textContent.trim()))"))

    def _stored(self):
        return read_local(self.page, "blattam-tabs") or []

    def _item_box(self, id):
        return self.page.evaluate("""(id) => {
            const c = document.querySelector('#browser-tabs-list .bt-tab[data-id="' + id + '"]');
            const r = c.getBoundingClientRect();
            return {x: r.left + r.width / 2, y: r.top + r.height / 2};
        }""", id)

    def _row_y(self):
        cards = self._cards()
        return (cards[0]["top"] + cards[0]["bottom"]) / 2

    def _list_box(self):
        return self.page.evaluate("""(() => {
            const r = document.getElementById('tabs-list').getBoundingClientRect();
            return {left: r.left, right: r.right, bottom: r.bottom};
        })()""")

    def _arm_flip_counter(self):
        self.page.evaluate("""(() => {
            window.__flip = 0;
            document.querySelectorAll('#tabs-list .tab-card').forEach(c => {
                c.addEventListener('transitionstart', (e) => {
                    if (e.propertyName === 'transform') window.__flip++;
                });
            });
        })()""")

    # === pointer path helpers (real mouse) ===

    def _pd_move(self, from_pt, to_pt, steps=10):
        pg = self.page
        pg.mouse.move(from_pt["x"], from_pt["y"])
        pg.mouse.down()
        for i in range(1, steps + 1):
            pg.mouse.move(from_pt["x"] + (to_pt["x"] - from_pt["x"]) * i / steps,
                          from_pt["y"] + (to_pt["y"] - from_pt["y"]) * i / steps)

    def _hover(self, x, y):
        self.page.mouse.move(x, y)

    def _cancel(self):
        # release over the LEFT RAIL — not a drop target -> cancel
        self.page.mouse.move(100, 400)
        self.page.mouse.up()
        self.page.wait_for_timeout(150)

    def _touch_b(self):
        """Drag bt1 from the rail and touch card B (ghost lands before B)."""
        b1 = self._item_box("bt1")
        cards = self._cards()
        b = [c for c in cards if c["name"] == "B"][0]
        self._pd_move(b1, {"x": b["left"] + b["width"] * 0.25,
                           "y": b["top"] + b["height"] * 0.25}, steps=12)
        self.page.wait_for_timeout(350)  # settle the FLIP slide before geometry reads

    # --- pointer tests ---

    def test_pointer_touch_ghost_before_card(self):
        # Touch card B from the rail: the ghost lands BEFORE B (touch rule,
        # no ghost yet -> side 'before'); release outside a target — cancel
        self._load()
        self._touch_b()
        assert self._slot_order() == ["card", "slot", "card", "card"]
        self._cancel()
        assert [t["url"] for t in self._stored()] == [t["url"] for t in self.TABS3]
        assert self._slot() is None

    def test_pointer_sticky_ghost_cell(self):
        # The ghost's own cell is STICKY: hovering inside it does not move the slot
        self._load()
        self._touch_b()
        assert self._slot_order() == ["card", "slot", "card", "card"]
        s = self._slot()
        assert s and s["display"] != "none"
        self._hover(s["x"], s["y"])
        assert self._slot_order() == ["card", "slot", "card", "card"]
        self._cancel()

    def test_pointer_gap_left_half_anchor_before(self):
        # The left half of the gap A|ghost is A's territory; the cursor
        # approaches A from the right -> side 'before': the slot moves before A
        self._load()
        self._touch_b()
        cards = self._cards()
        a = [c for c in cards if c["name"] == "A"][0]
        s = self._slot()
        self._hover(a["right"] + (s["left"] - a["right"]) * 0.25, self._row_y())
        assert self._slot_order() == ["slot", "card", "card", "card"]
        self._cancel()

    def test_pointer_gap_right_half_anchor_after(self):
        # The right half of the gap ghost|B is B's territory; approach from
        # the left -> side 'after': the slot moves after B (before C)
        self._load()
        self._touch_b()
        cards = self._cards()
        b = [c for c in cards if c["name"] == "B"][0]
        s = self._slot()
        self._hover(s["right"] + (b["left"] - s["right"]) * 0.75, self._row_y())
        assert self._slot_order() == ["card", "card", "slot", "card"]
        self._cancel()

    def test_pointer_row_end_tail(self):
        # The empty cell right of the last card C — the row end (legacy A3a):
        # the slot after C (list end); releasing there still cancels? No —
        # this test only hovers, then cancels; nothing is written
        self._load()
        b1 = self._item_box("bt1")
        cards = self._cards()
        c = [c for c in cards if c["name"] == "C"][0]
        self._pd_move(b1, {"x": c["right"] + 6, "y": self._row_y()}, steps=12)
        assert self._slot_order() == ["card", "card", "card", "slot"]
        self._cancel()
        assert [t["url"] for t in self._stored()] == [t["url"] for t in self.TABS3]
        assert self._slot() is None

    def test_pointer_band_hides_ghost_and_drop_cancels(self):
        # The bottom band (below the last row, in the list's 110px
        # padding-bottom zone): the ghost is hidden; releasing there — cancel,
        # nothing is written, the rail is untouched
        self._load()
        self._touch_b()
        assert self._slot_order() == ["card", "slot", "card", "card"]
        tl = self._list_box()
        cards = self._cards()
        band_y = (cards[0]["bottom"] + tl["bottom"]) / 2
        self._hover((tl["left"] + tl["right"]) / 2, band_y)
        s = self._slot()
        assert s and s["display"] == "none"
        self.page.mouse.up()
        self.page.wait_for_timeout(150)
        assert [t["url"] for t in self._stored()] == [t["url"] for t in self.TABS3]
        assert self._slot() is None
        assert self.page.evaluate("document.querySelectorAll('#browser-tabs-list .bt-tab').length") == 2

    def test_pointer_mid_section_drop_lands_mid_section(self):
        # REGRESSION (the saveBtToCenter fix): dropping "after" a MID-SECTION
        # card lands right after it — not at the end of the section
        # (placeCardToSlot parity). Old code: [A, B, C, Wiki]; new: [A, B, Wiki, C]
        tabs = [dict(t, groupId="g1") for t in self.TABS3]
        self._load(tabs=tabs, groups=self.GROUPS)
        self._touch_b()
        cards = self._cards()
        b = [c for c in cards if c["name"] == "B"][0]
        s = self._slot()
        # right half of the gap ghost|B -> owner B, approach from the left
        self._hover(s["right"] + (b["left"] - s["right"]) * 0.75, self._row_y())
        assert self._slot_order() == ["other", "card", "card", "slot", "card"]
        self.page.mouse.up()
        self.page.wait_for_timeout(150)
        assert self._center_names() == ["A", "B", "Wiki", "C"]
        wiki = [t for t in self._stored() if t["url"] == "https://wiki.example"]
        assert len(wiki) == 1 and wiki[0].get("groupId") == "g1"
        assert self._slot() is None

    def test_pointer_gbar_hover_hides_central_ghost(self):
        # Crossing the group header: the central ghost is hidden (drop-into-
        # group semantics); releasing on the header — to the group
        tabs = [dict(t, groupId="g1") for t in self.TABS3]
        self._load(tabs=tabs, groups=self.GROUPS)
        self._touch_b()
        s = self._slot()
        assert s and s["display"] != "none"
        gbar = self.page.evaluate("""(() => {
            const r = document.querySelector('.gbar').getBoundingClientRect();
            return {x: r.left + r.width / 2, y: r.top + r.height / 2};
        })()""")
        self._hover(gbar["x"], gbar["y"])
        s = self._slot()
        assert s and s["display"] == "none"
        self.page.mouse.up()
        self.page.wait_for_timeout(150)
        wiki = [t for t in self._stored() if t["url"] == "https://wiki.example"]
        assert len(wiki) == 1 and wiki[0].get("groupId") == "g1"
        assert self._slot() is None

    def test_pointer_flip_on_central_anchor_change(self):
        # FLIP (pointer path, parity with the card drag): a real slot move
        # slides the cards (transitionstart transform events on #tabs-list)
        self._load()
        self._arm_flip_counter()
        self._touch_b()
        self.page.evaluate("window.__flip = 0")  # initial touch — reset
        cards = self._cards()
        a = [c for c in cards if c["name"] == "A"][0]
        s = self._slot()
        # left half of the gap A|ghost -> slot moves before A (A slides)
        self._hover(a["right"] + (s["left"] - a["right"]) * 0.25, self._row_y())
        self.page.wait_for_timeout(50)
        assert self.page.evaluate("window.__flip") >= 1
        self._cancel()

    def test_pointer_freeze_no_reflow_in_territory(self):
        # Freeze (touch rule): while the cursor stays INSIDE B's rect, the
        # anchor is frozen — no card slides. (The drag path enters the list
        # from the right, so the last touch on arrival may be another card —
        # establish the touch on B first, then reset the counter.)
        self._load()
        self._arm_flip_counter()
        self._touch_b()  # includes a settle wait — the slide is done
        cards = self._cards()
        b = [c for c in cards if c["name"] == "B"][0]
        self._hover(b["left"] + 4, self._row_y())  # touch B (one possible reflow)
        self.page.wait_for_timeout(30)
        self.page.evaluate("window.__flip = 0")
        order_before = self._slot_order()
        # wander inside B's rect: frozen — no reflow
        for x in (b["left"] + b["width"] * 0.5, b["right"] - 4):
            self._hover(x, self._row_y())
        self.page.wait_for_timeout(50)
        assert self.page.evaluate("window.__flip") == 0
        assert self._slot_order() == order_before
        self._cancel()

    # --- HTML5 synthetic path (like TestRailCenterGhost) ---

    def test_html5_touch_anchor_and_drop(self):
        self._load()
        pg = self.page
        pg.evaluate("""(() => {
            const item = document.querySelector('#browser-tabs-list .bt-tab[data-id="bt1"]');
            const dt = new DataTransfer();
            item.dispatchEvent(new DragEvent('dragstart', {dataTransfer: dt, bubbles: true, cancelable: true}));
            window.__dt = dt;
        })()""")
        cards = self._cards()
        b = [c for c in cards if c["name"] == "B"][0]
        over_x, over_y = b["left"] + b["width"] * 0.25, b["top"] + b["height"] * 0.25
        pg.evaluate("""([x, y]) => {
            document.getElementById('tabs-list').dispatchEvent(new DragEvent('dragover', {
                dataTransfer: window.__dt, bubbles: true, cancelable: true, clientX: x, clientY: y
            }));
        }""", [over_x, over_y])
        assert self._slot_order() == ["card", "slot", "card", "card"]
        # re-read B's rect: the reflowed position (the ghost took B's old cell)
        cards2 = self._cards()
        b2 = [c for c in cards2 if c["name"] == "B"][0]
        pg.evaluate("""([x, y]) => {
            document.getElementById('tabs-list').dispatchEvent(new DragEvent('drop', {
                dataTransfer: window.__dt, bubbles: true, cancelable: true, clientX: x, clientY: y
            }));
        }""", [b2["left"] + b2["width"] * 0.25, b2["top"] + b2["height"] * 0.25])
        pg.wait_for_timeout(100)
        assert self._center_names() == ["A", "Wiki", "B", "C"]
        assert self._slot() is None
        assert [t["url"] for t in self._stored()] == ["https://a.com", "https://wiki.example",
                                                       "https://b.com", "https://c.com"]

    def test_html5_band_drop_cancels(self):
        self._load()
        pg = self.page
        pg.evaluate("""(() => {
            const item = document.querySelector('#browser-tabs-list .bt-tab[data-id="bt1"]');
            const dt = new DataTransfer();
            item.dispatchEvent(new DragEvent('dragstart', {dataTransfer: dt, bubbles: true, cancelable: true}));
            window.__dt = dt;
        })()""")
        cards = self._cards()
        b = [c for c in cards if c["name"] == "B"][0]
        tl = self._list_box()
        band_x = (tl["left"] + tl["right"]) / 2
        band_y = (cards[0]["bottom"] + tl["bottom"]) / 2
        pg.evaluate("""([x, y]) => {
            document.getElementById('tabs-list').dispatchEvent(new DragEvent('dragover', {
                dataTransfer: window.__dt, bubbles: true, cancelable: true, clientX: x, clientY: y
            }));
        }""", [b["left"] + b["width"] * 0.25, b["top"] + b["height"] * 0.25])
        assert self._slot_order() == ["card", "slot", "card", "card"]
        pg.evaluate("""([x, y]) => {
            document.getElementById('tabs-list').dispatchEvent(new DragEvent('dragover', {
                dataTransfer: window.__dt, bubbles: true, cancelable: true, clientX: x, clientY: y
            }));
        }""", [band_x, band_y])
        s = self._slot()
        assert s and s["display"] == "none"
        pg.evaluate("""([x, y]) => {
            document.getElementById('tabs-list').dispatchEvent(new DragEvent('drop', {
                dataTransfer: window.__dt, bubbles: true, cancelable: true, clientX: x, clientY: y
            }));
        }""", [band_x, band_y])
        pg.evaluate("""(() => {
            const item = document.querySelector('#browser-tabs-list .bt-tab[data-id="bt1"]');
            item.dispatchEvent(new DragEvent('dragend', {bubbles: true}));
        })()""")
        pg.wait_for_timeout(100)
        assert [t["url"] for t in self._stored()] == [t["url"] for t in self.TABS3]
        assert self._slot() is None


class TestCustomTheme:
    """«Кастомизация визуала»: цвета, размер и форма, шрифт (blattam-custom-theme, local)."""

    TOKENS = ["--bg", "--rail-bg", "--surface", "--text", "--text-muted",
              "--card-name", "--ink", "--ghost-bg", "--ghost-ring",
              "--card-radius", "--card-gap", "--card-min", "--card-name-size", "--font-ui"]
    TITLES = ["Пресеты", "Тема", "Цвета", "Размер и форма", "Шрифт", "Фон", "Фон левой рейки", "Фон правой рейки",
              "Цвет вкладок", "Язык", "Горячие клавиши", "Экспериментальное",
              "Частые вопросы", "О программе"]

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self.page_errors = []
        self._on_pageerror = lambda exc: self.page_errors.append(str(exc))
        self.page.on("pageerror", self._on_pageerror)
        yield
        self.page.remove_listener("pageerror", self._on_pageerror)

    def _inject_css(self):
        # реальный CSS (theme.css + <style> view.html) — для computed-style проверок
        theme = open(f"{EXT_PATH}/theme.css", encoding="utf-8").read()
        html = open(f"{EXT_PATH}/view.html", encoding="utf-8").read()
        style = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate(
            "(() => { const st = document.createElement('style'); st.textContent = "
            + json.dumps(theme + style)
            + "; (document.head || document.documentElement).appendChild(st); })()")

    def _load(self, **kw):
        load_view(self.page, **kw)
        self._inject_css()

    def _open(self):
        self.page.locator("#settings-btn").click()

    def _tabs(self, n=2):
        return [{"name": f"Вкладка {i}", "url": f"https://example.com/{i}"} for i in range(1, n + 1)]

    def _stored(self):
        return self.page.evaluate("chrome.storage.local._data['blattam-custom-theme']")

    def _inline(self, token):
        return self.page.evaluate(
            "document.documentElement.style.getPropertyValue(" + json.dumps(token) + ")")

    def _set_color(self, cid, hex_val):
        self.page.evaluate(
            "(() => { const i = document.getElementById('cust-color-' + " + json.dumps(cid)
            + "); i.value = " + json.dumps(hex_val)
            + "; i.dispatchEvent(new Event('input', {bubbles: true})); })()")

    def test_defaults_no_inline_no_key(self):
        self._load(tabs=self._tabs())
        for tk in self.TOKENS:
            assert self._inline(tk) == ""
        assert self._stored() is None

    def test_sections_present_and_defaults(self):
        self._load(tabs=self._tabs())
        self._open()
        titles = json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('#settings-modal .settings-section-title')]"
            ".map(el => el.textContent.trim()))"))
        assert titles == self.TITLES
        assert self.page.evaluate("document.getElementById('cust-color-bg').type") == "color"
        disp = json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('[data-cust-reset]')]"
            ".map(b => b.style.display))"))
        assert disp == ["none"] * 15
        assert self.page.evaluate("document.getElementById('cust-colors-reset-all').style.display") == "none"
        assert self.page.evaluate("document.getElementById('cust-geo-reset-all').style.display") == "none"
        assert self.page.evaluate("document.getElementById('cust-font').value") == "default"
        # пикеры показывают дефолты темы
        assert self.page.evaluate("document.getElementById('cust-color-bg').value") == "#ffffff"
        assert self.page.evaluate("document.getElementById('cust-geo-radius').value") == "8"
        assert self.page.evaluate("document.getElementById('cust-geo-gap-val').textContent") == "12px"
        # тёмная тема — дефолт темы
        self._load(tabs=self._tabs(), theme="dark")
        self._open()
        assert self.page.evaluate("document.getElementById('cust-color-bg').value") == "#1f1c1b"

    def test_color_set_live(self):
        self._load(tabs=self._tabs())
        self._open()
        self._set_color("bg", "#123456")
        assert self._stored() == {"--bg": "#123456"}
        assert self._inline("--bg") == "#123456"
        assert self.page.evaluate("getComputedStyle(document.body).backgroundColor") == "rgb(18, 52, 86)"
        assert self.page.evaluate(
            "document.querySelector('[data-cust-reset=\"bg\"]').style.display") != "none"
        assert self.page.evaluate("document.getElementById('cust-colors-reset-all').style.display") != "none"

    def test_color_reset_row(self):
        self._load(tabs=self._tabs(), custom_theme={"--bg": "#336699"})
        assert self.page.evaluate(
            "document.querySelector('[data-cust-reset=\"bg\"]').style.display") != "none"
        self._open()
        self.page.locator('[data-cust-reset="bg"]').click()
        assert self._stored() is None
        assert self._inline("--bg") == ""
        assert self.page.evaluate("getComputedStyle(document.body).backgroundColor") == "rgb(255, 255, 255)"
        assert self.page.evaluate(
            "document.querySelector('[data-cust-reset=\"bg\"]').style.display") == "none"

    def test_reset_all_colors(self):
        self._load(tabs=self._tabs(), custom_theme={"--bg": "#336699", "--ink": "#663399"})
        self._open()
        self.page.locator("#cust-colors-reset-all").click()
        assert self._stored() is None
        assert self._inline("--bg") == ""
        assert self._inline("--ink") == ""
        assert self.page.evaluate(
            "document.querySelector('[data-cust-reset=\"bg\"]').style.display") == "none"
        assert self.page.evaluate(
            "document.querySelector('[data-cust-reset=\"ink\"]').style.display") == "none"

    def test_geometry_gap_applies(self):
        self._load(tabs=self._tabs(), custom_theme={"--card-gap": "20px"})
        g = json.loads(self.page.evaluate(
            "(() => { const s = getComputedStyle(document.querySelector('.tabs-list'));"
            " return JSON.stringify({cg: s.columnGap, rg: s.rowGap}); })()"))
        assert g["cg"] == "20px" and g["rg"] == "20px"
        assert self.page.evaluate("document.getElementById('cust-geo-gap').value") == "20"
        assert self.page.evaluate("document.getElementById('cust-geo-gap-val').textContent") == "20px"

    def test_geometry_width_applies(self):
        self._load(tabs=self._tabs(), custom_theme={"--card-min": "180px"})
        assert self._inline("--card-min") == "180px"
        # токен применяется к сетке: computed --card-min на .tabs-list = 180px
        assert self.page.evaluate(
            "getComputedStyle(document.querySelector('.tabs-list')).getPropertyValue('--card-min')") == "180px"

    def test_geometry_reset_all(self):
        self._load(tabs=self._tabs(), custom_theme={"--card-radius": "16px", "--card-gap": "20px"})
        self._open()
        self.page.locator("#cust-geo-reset-all").click()
        assert self._stored() is None
        assert self._inline("--card-radius") == ""
        assert self._inline("--card-gap") == ""
        assert self.page.evaluate("document.getElementById('cust-geo-radius-val').textContent") == "8px"
        assert self.page.evaluate("document.getElementById('cust-geo-gap-val').textContent") == "12px"
        assert self.page.evaluate("document.getElementById('cust-geo-railleft-val').textContent") == "220px"
        assert self.page.evaluate("document.getElementById('cust-geo-railright-val').textContent") == "190px"

    def test_font_serif_applies(self):
        self._load(tabs=self._tabs(), custom_theme={"--font-ui": "serif"})
        assert "Georgia" in self._inline("--font-ui")
        assert self.page.evaluate("document.getElementById('cust-font').value") == "serif"
        fam = self.page.evaluate(
            "getComputedStyle(document.querySelector('.rail-item .t')).fontFamily")
        assert "Georgia" in fam

    def test_persists_across_reload(self):
        self._load(tabs=self._tabs())
        self._open()
        self._set_color("bg", "#336699")
        stored = self._stored()
        assert stored == {"--bg": "#336699"}
        # пересоздаём страницу с тем же ключом в local — применяется при init
        self._load(tabs=self._tabs(), custom_theme=stored)
        assert self._inline("--bg") == "#336699"
        assert self.page.evaluate("document.getElementById('cust-color-bg').value") == "#336699"
        assert self.page.evaluate(
            "document.querySelector('[data-cust-reset=\"bg\"]').style.display") != "none"

    def test_onchanged_external(self):
        self._load(tabs=self._tabs())
        self.page.evaluate("chrome.storage.local.set({'blattam-custom-theme': {'--rail-bg': '#554433'}})")
        self.page.wait_for_timeout(50)
        assert self._inline("--rail-bg") == "#554433"
        self.page.evaluate("chrome.storage.local.set({'blattam-custom-theme': {}})")
        self.page.wait_for_timeout(50)
        assert self._inline("--rail-bg") == ""

    def test_theme_switch_keeps_custom(self):
        self._load(tabs=self._tabs(), theme="dark", custom_theme={"--bg": "#336699"})
        self._open()
        self.page.locator("#theme-btn-light").click()
        assert self.page.evaluate("document.documentElement.dataset.theme") == "light"
        assert self._inline("--bg") == "#336699"
        assert self.page.evaluate("getComputedStyle(document.body).backgroundColor") == "rgb(51, 102, 153)"

    def test_i18n_en(self):
        self._load(tabs=self._tabs(), lang="en")
        self._open()
        titles = json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('#settings-modal .settings-section-title')]"
            ".map(el => el.textContent.trim()))"))
        assert "Colors" in titles and "Size and shape" in titles and "Font" in titles
        assert self.page.evaluate(
            "document.querySelector('[data-i18n=\"cust_bg\"]').textContent.trim()") == "Page background"

    def test_no_pageerrors(self):
        self._load(tabs=self._tabs(), custom_theme={"--bg": "#336699", "--card-gap": "20px", "--font-ui": "serif"})
        self._open()
        # модалка перехватывает pointer events — клик по кнопке темы через JS (панель «Внешний вид»)
        self.page.evaluate("document.getElementById('theme-btn-dark').click()")
        # закрыть модалку (кнопка закрытия вне viewport харнесса — Escape, тот же путь, что в view.js)
        self.page.keyboard.press("Escape")
        self.page.wait_for_timeout(100)
        assert self.page_errors == []
class TestAccountDeviceCode:
    """GitHub Device Flow: строка кода — ВНУТРИ модалки #github-modal.

    Код показывается строкой #account-device ВНУТРИ модалки #github-modal
    (открывается кликом по карточке аккаунта в рейке; кнопка Подключить):
    выделяемый текст (user-select: text — внутри <button> в Chrome текст
    не выделяется) + кнопка копирования (navigator.clipboard). Вкладка
    открывается по verification_uri_complete — страница с подставленным
    кодом (вводить руками не нужно)."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page

    def _install_flow_mocks(self, user_code="ABCD-1234"):
        """device-flow-start → фиксированный ответ; auth-окно «падает»
        (lastError) → путь device flow; getManifest — с oauth2."""
        self.page.evaluate("""(uc) => {
          window.__deviceRes = {
            user_code: uc,
            verification_uri: 'https://github.com/login/device',
            verification_uri_complete: 'https://github.com/login/device#' + uc,
            interval: 5,
            expires_at: Date.now() + 900000
          };
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'device-flow-poll') {
              if (window.__pollResponder) {
                const r = window.__pollResponder(msg);
                if (cb) cb(r);
                return Promise.resolve(r);
              }
              return Promise.resolve(undefined);
            }
            if (msg && msg.action === 'device-flow-start') {
              if (cb) cb(window.__deviceRes);
              return Promise.resolve(window.__deviceRes);
            }
            return orig(msg, cb);
          };
          chrome.identity = {
            getRedirectURL: function () { return 'https://mock-extension-id.chromiumapp.org/'; },
            launchWebAuthFlow: function (opts, cb) {
              chrome.runtime.lastError = { message: 'mock: auth window failed' };
              if (cb) cb();
              return Promise.resolve(undefined);
            }
          };
          const origManifest = chrome.runtime.getManifest.bind(chrome.runtime);
          chrome.runtime.getManifest = function () {
            return Object.assign({}, origManifest(), { oauth2: { client_id: 'mock-client' } });
          };
        }""", user_code)

    def _stub_clipboard(self):
        self.page.evaluate("""() => {
          window.__clipboard = [];
          navigator.clipboard = {
            writeText: (t) => { window.__clipboard.push(t); return Promise.resolve(); }
          };
        }""")

    def _start_flow(self):
        load_view(self.page)
        self.page.wait_for_timeout(150)
        self._install_flow_mocks()
        self.page.click("#account-slot")
        self.page.wait_for_timeout(100)
        self.page.click("#github-connect-btn")

    def _device_state(self):
        return json.loads(self.page.evaluate("""(() => JSON.stringify({
          rowHidden: document.getElementById('account-device').hidden,
          rowDisplay: getComputedStyle(document.getElementById('account-device')).display,
          code: document.getElementById('account-device-code').textContent,
          codeUserSelect: getComputedStyle(document.getElementById('account-device-code')).userSelect,
          sub: document.querySelector('#account-slot .a-s').textContent,
          codeInModal: !!document.getElementById('account-device-code').closest('#github-modal'),
          lastTab: (chrome.tabs.createdTabs.length ? chrome.tabs.createdTabs[chrome.tabs.createdTabs.length - 1].url : null)
        }))()"""))

    def test_device_row_hidden_by_default(self):
        load_view(self.page)
        self.page.wait_for_timeout(150)
        d = self._device_state()
        assert d["rowHidden"] is True, d
        assert d["rowDisplay"] == "none", d
        assert d["code"] == "", d

    def test_device_flow_shows_code_row(self):
        self._start_flow()
        d = self._device_state()
        assert d["rowHidden"] is False, d
        assert d["rowDisplay"] != "none", d
        assert d["code"] == "ABCD-1234", d
        # Ядро фикса: текст КОДА ВЫДЕЛЯЕМЫЙ (внутри кнопки Chrome не выделяет)
        # и строка кода живёт ВНУТРИ модалки #github-modal
        assert d["codeUserSelect"] == "text", d
        assert d["codeInModal"] is True, d
        assert d["sub"] == "Введите код в открытой вкладке", d

    def test_tab_opens_prefilled_device_page(self):
        self._start_flow()
        d = self._device_state()
        assert d["lastTab"] == "https://github.com/login/device#ABCD-1234", d

    def test_copy_button_writes_code_to_clipboard(self):
        self._start_flow()
        self._stub_clipboard()
        self.page.click("#account-device-copy")
        self.page.wait_for_timeout(100)
        d = json.loads(self.page.evaluate("""(() => JSON.stringify({
          written: window.__clipboard,
          glyph: document.getElementById('account-device-copy').textContent
        }))()"""))
        assert d["written"] == ["ABCD-1234"], d
        assert d["glyph"] == "✓", d

    def test_connected_hides_device_row(self):
        self._start_flow()
        self.page.evaluate("""() => {
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'verify-github') {
              const r = { success: true, user: { login: 'roach' } };
              if (cb) cb(r);
              return Promise.resolve(r);
            }
            return orig(msg, cb);
          };
          chrome.storage.local.set({ 'github-token': 'mock-token' });
        }""")
        self.page.wait_for_timeout(200)
        d = self._device_state()
        assert d["rowHidden"] is True, d
        assert d["code"] == "", d
        assert d["sub"] == "Синхронизация через GitHub", d
        label = self.page.evaluate("document.querySelector('#account-slot .a-t').textContent")
        assert label == "GitHub: roach", label

    def test_i18n_en_device_row(self):
        load_view(self.page, lang="en")
        self.page.wait_for_timeout(150)
        self._install_flow_mocks()
        self.page.click("#account-slot")
        self.page.wait_for_timeout(100)
        self.page.click("#github-connect-btn")
        d = json.loads(self.page.evaluate("""(() => JSON.stringify({
          sub: document.querySelector('#account-slot .a-s').textContent,
          copyTitle: document.getElementById('account-device-copy').title,
          codeTitle: document.getElementById('account-device-code').title
        }))()"""))
        assert d["sub"] == "Enter the code in the opened tab", d
        assert d["copyTitle"] == "Copy", d
        assert d["codeTitle"] == "Code for github.com/login/device", d

# ==========================================
#  VIEW.JS: DEVICE FLOW — ПОЛЛИНГ СО СТРАНИЦЫ
# ==========================================

class TestDeviceFlowPolling:
    """Поллинг device flow ведёт СТРАНИЦА (view.js): каждое сообщение
    device-flow-poll будит service worker, он делает один шаг поллинга и
    возвращает результат; успех/финальная ошибка останавливают интервал,
    токен в storage → refreshAccount (storage.onChanged)."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page

    def _install_flow_mocks(self, user_code="ABCD-1234"):
        TestAccountDeviceCode._install_flow_mocks(self, user_code)

    def _start_flow(self, short=True):
        load_view(self.page)
        self.page.wait_for_timeout(150)
        self._install_flow_mocks()
        if short:
            self.page.evaluate("window.__deviceRes.interval = 1")
        self.page.click("#account-slot")
        self.page.wait_for_timeout(100)
        self.page.click("#github-connect-btn")

    def test_view_polls_while_pending(self):
        self._start_flow()
        self.page.evaluate("""() => {
          window.__pollCalls = [];
          window.__pollResponder = (m) => {
            window.__pollCalls.push(m);
            return { ok: true, connected: false, pending: true };
          };
        }""")
        self.page.wait_for_timeout(2500)
        n = self.page.evaluate("window.__pollCalls.length")
        assert n >= 2, n

    def test_success_stops_polling_and_connects(self):
        self._start_flow()
        self.page.evaluate("""() => {
          window.__pollCalls = [];
          let n = 0;
          window.__pollResponder = (m) => {
            window.__pollCalls.push(m);
            n += 1;
            if (n === 1) return { ok: true, connected: false, pending: true };
            chrome.storage.local.set({ 'github-token': 'mock-token' });
            return { ok: true, connected: true };
          };
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'verify-github') {
              const r = { success: true, user: { login: 'roach' } };
              if (cb) cb(r);
              return Promise.resolve(r);
            }
            return orig(msg, cb);
          };
        }""")
        label = ""
        for _ in range(30):
            label = self.page.evaluate("document.querySelector('#account-slot .a-t').textContent")
            if label == "GitHub: roach":
                break
            self.page.wait_for_timeout(200)
        assert label == "GitHub: roach", label
        d = json.loads(self.page.evaluate("""JSON.stringify({
          rowHidden: document.getElementById('account-device').hidden,
          sub: document.querySelector('#account-slot .a-s').textContent,
          calls: window.__pollCalls.length
        })"""))
        assert d["rowHidden"] is True, d
        assert d["sub"] == "Синхронизация через GitHub", d
        assert d["calls"] == 2, d
        self.page.wait_for_timeout(2500)
        assert self.page.evaluate("window.__pollCalls.length") == 2

    def test_inactive_stops_polling(self):
        self._start_flow()
        self.page.evaluate("""() => {
          window.__pollCalls = [];
          window.__pollResponder = (m) => {
            window.__pollCalls.push(m);
            return { ok: true, connected: false, inactive: true };
          };
        }""")
        self.page.wait_for_timeout(3000)
        n1 = self.page.evaluate("window.__pollCalls.length")
        self.page.wait_for_timeout(1500)
        n2 = self.page.evaluate("window.__pollCalls.length")
        assert n1 >= 1 and n1 == n2, (n1, n2)
        sub = self.page.evaluate("document.querySelector('#account-slot .a-s').textContent")
        assert sub == "Нажмите, чтобы войти в GitHub", sub
    def test_final_error_shown_in_sub(self):
        self._start_flow()
        self.page.evaluate("""() => {
          window.__pollCalls = [];
          window.__pollResponder = (m) => {
            window.__pollCalls.push(m);
            return { ok: true, connected: false, inactive: true, error: 'access_denied' };
          };
        }""")
        self.page.wait_for_timeout(2500)
        sub = self.page.evaluate("document.querySelector('#account-slot .a-s').textContent")
        assert sub == "access_denied", sub
        n1 = self.page.evaluate("window.__pollCalls.length")
        self.page.wait_for_timeout(1500)
        assert self.page.evaluate("window.__pollCalls.length") == n1, (n1,)

    def test_expired_flow_stops_polling(self):
        load_view(self.page)
        self.page.wait_for_timeout(150)
        self._install_flow_mocks()
        self.page.evaluate("""() => {
          window.__deviceRes.interval = 1;
          window.__deviceRes.expires_at = Date.now() + 1200;
          window.__pollCalls = [];
          window.__pollResponder = (m) => {
            window.__pollCalls.push(m);
            return { ok: true, connected: false, pending: true };
          };
        }""")
        self.page.click("#account-slot")
        self.page.click("#github-connect-btn")
        self.page.wait_for_timeout(4100)
        n1 = self.page.evaluate("window.__pollCalls.length")
        assert n1 <= 2, n1
        self.page.wait_for_timeout(1500)
        assert self.page.evaluate("window.__pollCalls.length") == n1, (n1,)
        assert self.page.evaluate("document.getElementById('account-device').hidden") is True



    def test_slow_down_pauses_and_resumes(self):
        self._start_flow(short=True)
        self.page.evaluate("""() => {
          window.__pollCalls = [];
          let n = 0;
          window.__pollResponder = (m) => {
            window.__pollCalls.push(m);
            n += 1;
            if (n === 1) return { ok: true, connected: false, pending: true, slow_down: true, wait_ms: 1200 };
            return { ok: true, connected: false, pending: true };
          };
        }""")
        self.page.wait_for_timeout(1500)
        d = json.loads(self.page.evaluate("""JSON.stringify({
          sub: document.querySelector('#account-slot .a-s').textContent,
          calls: window.__pollCalls.length
        })"""))
        assert d["sub"] == "GitHub просит подождать — продолжим автоматически", d
        assert d["calls"] == 1, d
        self.page.wait_for_timeout(2500)
        n2 = self.page.evaluate("window.__pollCalls.length")
        assert n2 >= 2, n2

