class TestGithubModal:
    """GitHub-модалка #github-modal (newtab): панель аккаунта, перенесённая
    из popup. Открывается по клику на карточку аккаунта (левая рейка);
    закрытие — ✕ / Escape / клик по фону. Состояния: не подключён
    (кнопка Подключить) / подключён (логин + sync-статус +
    Синхронизировать/Очистить/Отключить). Строка кода Device Flow — в модалке."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self._errors = []
        page.on("pageerror", self._on_err)
        yield
        assert not self._errors, self._errors
        page.remove_listener("pageerror", self._on_err)

    def _on_err(self, err):
        self._errors.append(str(err))

    def _inject_real_styles(self):
        theme = load_file("theme.css")
        html = load_file("view.html")
        style = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate(
            "(styles) => { var st = document.createElement('style'); st.textContent = styles; document.head.appendChild(st); }",
            [theme + "\n" + style])

    def _load(self):
        load_view(self.page)
        self.page.wait_for_timeout(120)
        self._inject_real_styles()
        self.page.wait_for_timeout(50)

    def _modal_state(self):
        return json.loads(self.page.evaluate("""JSON.stringify({
          open: document.getElementById('github-modal').classList.contains('open'),
          display: getComputedStyle(document.getElementById('github-modal')).display,
          connect: getComputedStyle(document.getElementById('github-connect-btn')).display,
          sync: getComputedStyle(document.getElementById('github-sync-btn')).display,
          clear: getComputedStyle(document.getElementById('github-clear-btn')).display,
          disconnect: getComputedStyle(document.getElementById('github-disconnect-btn')).display,
          status: document.getElementById('github-modal-status').textContent
        })"""))

    def _install_flow_mocks(self, user_code="ABCD-1234"):
        """device-flow-start → фиксированный ответ; auth-окно «падает»
        (lastError) → путь device flow; getManifest — с oauth2.
        (копия TestAccountDeviceCode._install_flow_mocks)"""
        self.page.evaluate("""(uc) => {
          window.__deviceRes = {
            user_code: uc,
            verification_uri: 'https://github.com/login/device',
            verification_uri_complete: 'https://github.com/login/device#' + uc,
            interval: 5,
            expires_at: Date.now() + 900000
          };
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'device-flow-poll') {
              if (window.__pollResponder) {
                const r = window.__pollResponder(msg);
                if (cb) cb(r);
                return Promise.resolve(r);
              }
              return Promise.resolve(undefined);
            }
            if (msg && msg.action === 'device-flow-start') {
              if (cb) cb(window.__deviceRes);
              return Promise.resolve(window.__deviceRes);
            }
            return orig(msg, cb);
          };
          chrome.identity = {
            getRedirectURL: function () { return 'https://mock-extension-id.chromiumapp.org/'; },
            launchWebAuthFlow: function (opts, cb) {
              chrome.runtime.lastError = { message: 'mock: auth window failed' };
              if (cb) cb();
              return Promise.resolve(undefined);
            }
          };
          const origManifest = chrome.runtime.getManifest.bind(chrome.runtime);
          chrome.runtime.getManifest = function () {
            return Object.assign({}, origManifest(), { oauth2: { client_id: 'mock-client' } });
          };
        }""", user_code)

    def _mock_connected(self, status="synced"):
        """Токен + verify-github успех + check-sync-status → «подключено»"""
        self.page.evaluate("""(st) => {
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'verify-github') {
              const r = { success: true, user: { login: 'roach' } };
              if (cb) cb(r);
              return Promise.resolve(r);
            }
            if (msg && msg.action === 'check-sync-status') {
              if (cb) cb(st);
              return Promise.resolve(st);
            }
            return orig(msg, cb);
          };
          chrome.storage.local.set({ 'github-token': 't' });
        }""", status)

    def _open_modal(self):
        self.page.click("#account-slot")
        self.page.wait_for_timeout(150)

    def test_modal_hidden_by_default(self):
        self._load()
        d = self._modal_state()
        assert d["open"] is False, d
        assert d["display"] == "none", d

    def test_slot_click_opens_modal(self):
        self._load()
        self.page.click("#account-slot")
        self.page.wait_for_timeout(150)
        d = self._modal_state()
        assert d["open"] is True, d
        assert d["display"] == "flex", d

    def test_not_connected_buttons_and_status(self):
        self._load()
        self._open_modal()
        d = self._modal_state()
        assert d["connect"] != "none", d
        assert d["sync"] == "none", d
        assert d["clear"] == "none", d
        assert d["disconnect"] == "none", d
        assert d["status"] == "Не подключён", d

    def test_connect_starts_device_flow(self):
        self._load()
        self._install_flow_mocks()
        self._open_modal()
        self.page.click("#github-connect-btn")
        self.page.wait_for_timeout(250)
        d = json.loads(self.page.evaluate("""JSON.stringify({
          status: document.getElementById('github-modal-status').textContent,
          rowInModal: !!document.getElementById('account-device').closest('#github-modal'),
          rowHidden: document.getElementById('account-device').hidden,
          code: document.getElementById('account-device-code').textContent,
          lastTab: (chrome.tabs.createdTabs.length ? chrome.tabs.createdTabs[chrome.tabs.createdTabs.length - 1].url : null)
        })"""))
        assert d["rowInModal"] is True, d
        assert d["rowHidden"] is False, d
        assert d["code"] == "ABCD-1234", d
        assert d["lastTab"] == "https://github.com/login/device#ABCD-1234", d
        assert d["status"] == "Введите код в открытой вкладке", d

    def test_connected_buttons_and_status(self):
        self._load()
        self._mock_connected("synced")
        self._open_modal()
        self.page.wait_for_timeout(200)
        d = self._modal_state()
        assert d["connect"] == "none", d
        assert d["sync"] != "none", d
        assert d["clear"] != "none", d
        assert d["disconnect"] != "none", d
        assert d["status"].startswith("GitHub: roach"), d
        assert "✅" in d["status"], d

    def test_sync_now(self):
        self._load()
        self._mock_connected("synced")
        self._open_modal()
        self.page.wait_for_timeout(100)
        self.page.evaluate("""() => {
          window.__syncMsgs = [];
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'sync-now') {
              window.__syncMsgs.push(msg.action);
              if (cb) cb({ pushed: true });
              return Promise.resolve({ pushed: true });
            }
            return orig(msg, cb);
          };
        }""")
        self.page.click("#github-sync-btn")
        self.page.wait_for_timeout(200)
        d = json.loads(self.page.evaluate("""JSON.stringify({
          msgs: window.__syncMsgs,
          status: document.getElementById('github-modal-status').textContent
        })"""))
        assert d["msgs"] == ["sync-now"], d
        assert d["status"] == "Синхронизировано", d

    def test_disconnect_returns_to_not_connected(self):
        self._load()
        self._mock_connected("synced")
        self._open_modal()
        self.page.wait_for_timeout(200)
        self.page.evaluate("""() => {
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'disconnect-github') {
              chrome.storage.local.remove('github-token');
              if (cb) cb({ ok: true });
              return Promise.resolve({ ok: true });
            }
            return orig(msg, cb);
          };
        }""")
        self.page.click("#github-disconnect-btn")
        d = None
        for _ in range(10):
            d = self._modal_state()
            if d["status"] == "Не подключён":
                break
            self.page.wait_for_timeout(200)
        assert d["connect"] != "none", d
        assert d["sync"] == "none", d
        assert d["status"] == "Не подключён", d

    def test_clear_cloud_with_confirm(self):
        self._load()
        self._mock_connected("synced")
        self._open_modal()
        self.page.wait_for_timeout(200)
        self.page.evaluate("""() => {
          window.confirm = () => true;
          window.__clearMsgs = [];
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'clear-cloud') {
              window.__clearMsgs.push(msg.action);
              if (cb) cb({ ok: true });
              return Promise.resolve({ ok: true });
            }
            return orig(msg, cb);
          };
        }""")
        self.page.click("#github-clear-btn")
        self.page.wait_for_timeout(200)
        d = json.loads(self.page.evaluate("""JSON.stringify({
          msgs: window.__clearMsgs,
          status: document.getElementById('github-modal-status').textContent
        })"""))
        assert d["msgs"] == ["clear-cloud"], d
        assert d["status"] == "🧹 Облачные данные очищены", d

    def test_close_esc_closebtn_overlay(self):
        self._load()
        # Escape
        self._open_modal()
        assert self._modal_state()["open"] is True, "не открылась"
        self.page.keyboard.press("Escape")
        self.page.wait_for_timeout(100)
        assert self._modal_state()["open"] is False, "Escape не закрыл"
        # ✕
        self._open_modal()
        self.page.click("#github-modal-close")
        self.page.wait_for_timeout(100)
        assert self._modal_state()["open"] is False, "крестик не закрыл"
        # клик по фону (левый край оверлея, вне .modal)
        self._open_modal()
        p = json.loads(self.page.evaluate("""JSON.stringify((() => {
          const m = document.querySelector('#github-modal .modal');
          const r = m.getBoundingClientRect();
          return { x: 10, y: r.top };
        })())"""))
        self.page.mouse.click(p["x"], p["y"])
        self.page.wait_for_timeout(100)
        assert self._modal_state()["open"] is False, "клик по фону не закрыл"

    def test_en_locale(self):
        self._load()
        self.page.evaluate("""() => {
          chrome.storage.local.set({ 'blattam-lang': 'en' });
          switchLanguage('en');
        }""")
        self.page.wait_for_timeout(100)
        self._open_modal()
        d = self._modal_state()
        assert d["status"] == "Not connected", d
        assert self.page.evaluate("document.getElementById('github-connect-btn').textContent") == "Connect GitHub", d
        assert self.page.evaluate("document.querySelector('#github-modal h3').textContent") == "GitHub", d


class TestVerifyAuthErrorAndRetry:
    """Wave 2: verify-github несёт error ('network' / 'api 401' / 'api 403').
    401/403 → рейка/модалка «Токен недействителен — войдите заново» БЕЗ retry
    (мёртвый токен не лечится повтором); сеть → «подключено · проверяем» +
    авто-retry 30 c со страницы (таймер view.js, стоп при успехе) + кнопка
    «Проверить ещё раз» в модалке (немедленный повтор verify).
    Background-уровень: verify-github → {success: false, token_present, error}."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self._errors = []
        page.on("pageerror", self._on_err)
        yield
        assert not self._errors, self._errors
        page.remove_listener("pageerror", self._on_err)

    def _on_err(self, err):
        self._errors.append(str(err))

    # --- view-уровень (паттерны TestDeviceFlowPolling / TestGithubModal) ---

    def _load_view(self, lang=None):
        load_view(self.page, lang=lang)
        self.page.wait_for_timeout(150)

    def _rail(self):
        return json.loads(self.page.evaluate("""JSON.stringify({
          label: document.querySelector('#account-slot .a-t').textContent,
          sub: document.querySelector('#account-slot .a-s').textContent
        })"""))

    def _install_verify_mock(self, queue, token=True, retry_ms=250):
        """Обёртка sendMessage: verify-github берёт ответ из очереди (счётчик —
        window.__verifyCalls), опустела → network-провал; check-sync-status →
        'synced'. Ставит window.__verifyRetryMs (хук 30 c) и github-token в
        storage (onChanged → refreshAccount → первый verify-вызов)."""
        self.page.evaluate("""(args) => {
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          window.__verifyCalls = 0;
          window.__verifyQueue = args.queue;
          window.__verifyRetryMs = args.retryMs;
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'verify-github') {
              window.__verifyCalls += 1;
              const r = window.__verifyQueue.length
                ? window.__verifyQueue.shift()
                : { success: false, token_present: true, error: 'network' };
              if (cb) cb(r);
              return Promise.resolve(r);
            }
            if (msg && msg.action === 'check-sync-status') {
              if (cb) cb('synced');
              return Promise.resolve('synced');
            }
            return orig(msg, cb);
          };
          if (args.token) chrome.storage.local.set({ 'github-token': 't' });
        }""", {"queue": queue, "retryMs": retry_ms, "token": token})

    def _open_modal(self):
        self.page.click("#account-slot")
        self.page.wait_for_timeout(100)

    def _modal(self):
        return json.loads(self.page.evaluate("""JSON.stringify({
          status: document.getElementById('github-modal-status').textContent,
          retry: document.getElementById('github-retry-btn').style.display
        })"""))

    def test_rail_network_error_shows_error(self):
        self._load_view()
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "network"}])
        d = {}
        for _ in range(10):
            d = self._rail()
            if d["sub"] == "GitHub недоступен — проверьте сеть":
                break
            self.page.wait_for_timeout(200)
        assert d["sub"] == "GitHub недоступен — проверьте сеть", d
        assert d["label"] == "Аккаунт", d

    def test_rail_network_retry_recovers(self):
        self._load_view()
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "network"},
            {"success": True, "user": {"login": "testuser"}},
        ])
        d = {}
        for _ in range(15):
            d = self._rail()
            if d["label"] == "GitHub: testuser":
                break
            self.page.wait_for_timeout(100)
        assert d["label"] == "GitHub: testuser", d
        assert self.page.evaluate("window.__verifyCalls") >= 2
        assert read_local(self.page, "blattam-github-login") == "testuser"

    def test_rail_401_shows_invalid_no_retry(self):
        self._load_view()
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "api 401"}])
        d = {}
        for _ in range(10):
            d = self._rail()
            if d["sub"] == "Токен недействителен — войдите заново":
                break
            self.page.wait_for_timeout(200)
        assert d["sub"] == "Токен недействителен — войдите заново", d
        # retry-хук 250 ms: если retry был бы — счётчик стал бы ≥ 2
        self.page.wait_for_timeout(700)
        assert self.page.evaluate("window.__verifyCalls") == 1

    def test_rail_success_clears_retry(self):
        self._load_view()
        self._install_verify_mock([
            {"success": True, "user": {"login": "testuser"}}])
        d = {}
        for _ in range(10):
            d = self._rail()
            if d["label"] == "GitHub: testuser":
                break
            self.page.wait_for_timeout(200)
        assert d["label"] == "GitHub: testuser", d
        self.page.wait_for_timeout(700)
        assert self.page.evaluate("window.__verifyCalls") == 1

    def test_no_token_no_verify_no_retry(self):
        self._load_view()
        self.page.evaluate("""() => {
          window.__verifyCalls = 0;
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'verify-github') window.__verifyCalls += 1;
            return orig(msg, cb);
          };
        }""")
        self.page.wait_for_timeout(400)
        assert self.page.evaluate("window.__verifyCalls") == 0
        d = self._rail()
        assert d["sub"] == "Нажмите, чтобы войти в GitHub", d

    def test_modal_network_error_status_and_retry_btn(self):
        self._load_view()
        # 2 провала: рейка (onChanged при установке токена) + модалка
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "network"},
            {"success": False, "token_present": True, "error": "network"},
        ])
        self._open_modal()
        d = {}
        for _ in range(10):
            d = self._modal()
            if d["status"] == "GitHub недоступен — проверьте сеть":
                break
            self.page.wait_for_timeout(200)
        assert d["status"] == "GitHub недоступен — проверьте сеть", d
        assert d["retry"] != "none", d

    def test_modal_401_shows_invalid(self):
        self._load_view()
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "api 401"},
            {"success": False, "token_present": True, "error": "api 401"},
        ])
        self._open_modal()
        d = {}
        for _ in range(10):
            d = self._modal()
            if d["status"] == "Токен недействителен — войдите заново":
                break
            self.page.wait_for_timeout(200)
        assert d["status"] == "Токен недействителен — войдите заново", d
        assert d["retry"] != "none", d

    def test_modal_success_hides_retry_btn(self):
        self._load_view()
        self._install_verify_mock([
            {"success": True, "user": {"login": "testuser"}},
            {"success": True, "user": {"login": "testuser"}},
        ])
        self._open_modal()
        d = {}
        for _ in range(10):
            d = self._modal()
            if d["status"].startswith("GitHub: testuser · "):
                break
            self.page.wait_for_timeout(200)
        assert d["status"].startswith("GitHub: testuser · "), d
        assert d["retry"] == "none", d

    def test_modal_retry_btn_click_reverifies(self):
        self._load_view()
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "network"},
            {"success": False, "token_present": True, "error": "network"},
        ])
        self._open_modal()
        for _ in range(10):
            if self._modal()["status"] == "GitHub недоступен — проверьте сеть":
                break
            self.page.wait_for_timeout(200)
        before = self.page.evaluate("window.__verifyCalls")
        self.page.click("#github-retry-btn")
        self.page.wait_for_timeout(150)
        after = self.page.evaluate("window.__verifyCalls")
        assert after > before, (before, after)

    def test_en_locale_401_text(self):
        self._load_view(lang="en")
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "api 401"},
            {"success": False, "token_present": True, "error": "api 401"},
        ])
        self._open_modal()
        d = {}
        for _ in range(10):
            d = self._modal()
            if d["status"] == "Token invalid — sign in again":
                break
            self.page.wait_for_timeout(200)
        assert d["status"] == "Token invalid — sign in again", d

    # --- background-уровень (паттерн TestDeviceFlowBackground: fetch-мок
    #     ставится ДО загрузки background.js) ---

    def _load_bg(self, setup_js):
        self.page.goto("about:blank")
        self.page.evaluate(MOCK_CHROME + setup_js)
        self.page.evaluate(load_file("background.js") + "; 'loaded'")

    def test_bg_verify_401_shape(self):
        self._load_bg("""
          window.fetch = async function (url) {
            if (String(url).indexOf('api.github.com/user') !== -1) {
              return { json: async () => ({ message: 'Bad credentials' }), ok: false, status: 401 };
            }
            throw new Error('unexpected fetch: ' + url);
          };
          // Маркер gist-1 — иначе стартовая проверка SW удалила бы токен
          chrome.storage.local.set({ 'github-token': 't', 'blattam-auth-scope': 'gist-1' });
        """)
        res = call_msg(self.page, "verify-github")
        assert res == {"success": False, "token_present": True, "error": "api 401"}, res

    def test_bg_verify_network_shape(self):
        self._load_bg("""
          window.__fetchTimeoutMs = 50;
          window.fetch = async function (url) {
            throw new Error('mock network failure: ' + url);
          };
          // Маркер gist-1 — иначе стартовая проверка SW удалила бы токен
          chrome.storage.local.set({ 'github-token': 't', 'blattam-auth-scope': 'gist-1' });
        """)
        res = call_msg(self.page, "verify-github")
        assert res == {"success": False, "token_present": True, "error": "network"}, res


class TestVerifyErrorSteadyState:
    """Стейди-стейт устойчивого провала verify (сеть, токен есть, кэша
    логина нет): рейка и модалка показывают ошибку account_verify_error
    вместо вечного «проверяем»; тихий авто-retry (хук __verifyRetryMs =
    250 ms) — модалка не мигает «проверяем» (renderGitHubModal(false));
    401/403 и success — без изменений. (Не наследуется от
    TestVerifyAuthErrorAndRetry: pytest исполняет наследованные тесты
    повторно — счёт сьюта бы вырос на число тестов родителя.)"""

    ERR = "GitHub недоступен — проверьте сеть"
    VERIFYING = "Подключено · проверяем аккаунт…"

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self._errors = []
        page.on("pageerror", self._on_err)
        yield
        assert not self._errors, self._errors
        page.remove_listener("pageerror", self._on_err)

    def _on_err(self, err):
        self._errors.append(str(err))

    def _load_view(self, lang=None):
        load_view(self.page, lang=lang)
        self.page.wait_for_timeout(150)

    def _rail(self):
        return json.loads(self.page.evaluate("""JSON.stringify({
          label: document.querySelector('#account-slot .a-t').textContent,
          sub: document.querySelector('#account-slot .a-s').textContent
        })"""))

    def _install_verify_mock(self, queue, token=True, retry_ms=250):
        self.page.evaluate("""(args) => {
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          window.__verifyCalls = 0;
          window.__verifyQueue = args.queue;
          window.__verifyRetryMs = args.retryMs;
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'verify-github') {
              window.__verifyCalls += 1;
              const r = window.__verifyQueue.length
                ? window.__verifyQueue.shift()
                : { success: false, token_present: true, error: 'network' };
              if (cb) cb(r);
              return Promise.resolve(r);
            }
            if (msg && msg.action === 'check-sync-status') {
              if (cb) cb('synced');
              return Promise.resolve('synced');
            }
            return orig(msg, cb);
          };
          if (args.token) chrome.storage.local.set({ 'github-token': 't' });
        }""", {"queue": queue, "retryMs": retry_ms, "token": token})

    def _open_modal(self):
        self.page.click("#account-slot")
        self.page.wait_for_timeout(100)

    def _modal(self):
        return json.loads(self.page.evaluate("""JSON.stringify({
          status: document.getElementById('github-modal-status').textContent,
          retry: document.getElementById('github-retry-btn').style.display
        })"""))

    def _install_delayed_verify_mock(self, delay_ms=400):
        """Как _install_verify_mock, но ответ verify-github с задержкой
        (delay_ms) — in-flight-состояние «проверяем» наблюдаемо."""
        self.page.evaluate("""(args) => {
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          window.__verifyCalls = 0;
          window.__verifyRetryMs = args.retryMs;
          window.__verifyDelayMs = args.delayMs;
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'verify-github') {
              window.__verifyCalls += 1;
              const r = { success: false, token_present: true, error: 'network' };
              setTimeout(function () { if (cb) cb(r); }, window.__verifyDelayMs);
              return Promise.resolve(r);
            }
            if (msg && msg.action === 'check-sync-status') {
              if (cb) cb('synced');
              return Promise.resolve('synced');
            }
            return orig(msg, cb);
          };
          if (args.token) chrome.storage.local.set({ 'github-token': 't' });
        }""", {"retryMs": 250, "delayMs": delay_ms, "token": True})

    def _wait_modal_status(self, text, tries=15, step=100):
        d = {}
        for _ in range(tries):
            d = self._modal()
            if d["status"] == text:
                break
            self.page.wait_for_timeout(step)
        return d

    # --- a. Рейка: устойчивый network-провал ---

    def test_rail_network_error_steady_error(self):
        """Устойчивый провал, кэша нет: стабильная account_verify_error
        (без спиннера), подпись «Аккаунт» (логина нет)."""
        self._load_view()
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "network"}])
        d = {}
        for _ in range(10):
            d = self._rail()
            if d["sub"] == self.ERR:
                break
            self.page.wait_for_timeout(200)
        assert d["sub"] == self.ERR, d
        assert d["label"] == "Аккаунт", d

    def test_rail_network_error_retry_scheduled(self):
        """В ошибочном стабейте авто-retry жив (хук 250 ms): счётчик
        verify продолжает расти после провала."""
        self._load_view()
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "network"}])
        d = {}
        for _ in range(10):
            d = self._rail()
            if d["sub"] == self.ERR:
                break
            self.page.wait_for_timeout(200)
        assert d["sub"] == self.ERR, d
        first = self.page.evaluate("window.__verifyCalls")
        self.page.wait_for_timeout(700)
        assert self.page.evaluate("window.__verifyCalls") > first

    # --- b. 401/403: регрессия ---

    def test_rail_401_stays_invalid_no_retry(self):
        """401 — не сеть: «Токен недействителен», авто-retry НЕ
        запланирован (мёртвый токен повтором не лечится)."""
        self._load_view()
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "api 401"}])
        d = {}
        for _ in range(10):
            d = self._rail()
            if d["sub"] == "Токен недействителен — войдите заново":
                break
            self.page.wait_for_timeout(200)
        assert d["sub"] == "Токен недействителен — войдите заново", d
        # retry-хук 250 ms: если retry был бы — счётчик стал бы ≥ 2
        self.page.wait_for_timeout(700)
        assert self.page.evaluate("window.__verifyCalls") == 1

    # --- c. Модалка: устойчивый network-провал ---

    def test_modal_network_error_shows_error_text(self):
        """После network-провала статус модалки = account_verify_error,
        кнопка «Проверить ещё раз» видна."""
        self._load_view()
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "network"},
            {"success": False, "token_present": True, "error": "network"}])
        self._open_modal()
        d = self._wait_modal_status(self.ERR)
        assert d["status"] == self.ERR, d
        assert d["retry"] != "none", d

    # --- d. Модалка: тихий retry ---

    def test_modal_quiet_retry_no_verifying_flash(self):
        """Отокрытая модалка + устойчивый провал: авто-retry делает verify
        БЕЗ вспышки «проверяем» — статус остаётся ошибкой и в in-flight
        окне verify, и после повторного провала."""
        self._load_view()
        self._install_delayed_verify_mock()
        self._open_modal()
        d = self._wait_modal_status(self.ERR)
        assert d["status"] == self.ERR, d
        # Тихий retry уже выстрелил: 3-й verify in-flight (400 ms окно)
        for _ in range(30):
            if self.page.evaluate("window.__verifyCalls") >= 3:
                break
            self.page.wait_for_timeout(50)
        assert self.page.evaluate("window.__verifyCalls") >= 3
        assert self._modal()["status"] == self.ERR
        self.page.wait_for_timeout(600)
        assert self._modal()["status"] == self.ERR

    # --- e. Восстановление после транзитного провала ---

    def test_recovery_after_transient_network_error(self):
        """1-й verify — network, 2-й (авто-retry) — success: рейка
        показывает логин, кэш blattam-github-login записан, pending-retry
        снят (verify больше не идёт)."""
        self._load_view()
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "network"},
            {"success": True, "user": {"login": "testuser"}},
        ])
        d = {}
        for _ in range(15):
            d = self._rail()
            if d["label"] == "GitHub: testuser":
                break
            self.page.wait_for_timeout(100)
        assert d["label"] == "GitHub: testuser", d
        assert read_local(self.page, "blattam-github-login") == "testuser"
        n = self.page.evaluate("window.__verifyCalls")
        self.page.wait_for_timeout(700)  # хук 250 ms: прилететь не должно
        assert self.page.evaluate("window.__verifyCalls") == n

    # --- f. Кнопка «Проверить ещё раз» ---

    def test_retry_btn_click_verifying_flash_then_verify(self):
        """Пользовательская проверка: «проверяем» мгновенно
        (showChecking=true по умолчанию), счётчик verify растёт, финальный
        статус при провале — ошибка."""
        self._load_view()
        self._install_delayed_verify_mock()
        self._open_modal()
        d = self._wait_modal_status(self.ERR)
        assert d["status"] == self.ERR, d
        before = self.page.evaluate("window.__verifyCalls")
        self.page.click("#github-retry-btn")
        for _ in range(20):
            d = self._modal()
            if d["status"] == self.VERIFYING:
                break
            self.page.wait_for_timeout(50)
        assert d["status"] == self.VERIFYING, d
        self.page.wait_for_timeout(700)
        after = self.page.evaluate("window.__verifyCalls")
        assert after > before, (before, after)
        assert self._modal()["status"] == self.ERR

    # --- g. en-локаль ---

    def test_en_locale_network_error(self):
        """Рейка при network-провале (en): «GitHub unreachable — check
        your network»."""
        self._load_view(lang="en")
        self._install_verify_mock([
            {"success": False, "token_present": True, "error": "network"}])
        d = {}
        for _ in range(10):
            d = self._rail()
            if d["sub"] == "GitHub unreachable — check your network":
                break
            self.page.wait_for_timeout(200)
        assert d["sub"] == "GitHub unreachable — check your network", d


class TestGithubModalSync:
    """GitHub-модалка (newtab): согласованность состояния + ошибки синка.
    При токене статус «проверяем» виден МГНОВЕННО (до ответа verify-github) —
    не «Не подключён» при видимой кнопке «Отключить». Ошибка синка видна в UI
    (с причиной) и НЕ затирается renderGitHubModal через 3 c."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self._errors = []
        page.on("pageerror", self._on_err)
        yield
        assert not self._errors, self._errors
        page.remove_listener("pageerror", self._on_err)

    def _on_err(self, err):
        self._errors.append(str(err))

    def _load(self):
        load_view(self.page)
        self.page.wait_for_timeout(120)

    def _modal_state(self):
        return json.loads(self.page.evaluate("""JSON.stringify({
          connect: getComputedStyle(document.getElementById('github-connect-btn')).display,
          sync: getComputedStyle(document.getElementById('github-sync-btn')).display,
          clear: getComputedStyle(document.getElementById('github-clear-btn')).display,
          disconnect: getComputedStyle(document.getElementById('github-disconnect-btn')).display,
          status: document.getElementById('github-modal-status').textContent
        })"""))

    def _mock_connected(self, status="synced"):
        """Токен + verify-github успех + check-sync-status → «подключено»"""
        self.page.evaluate("""(st) => {
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'verify-github') {
              const r = { success: true, user: { login: 'roach' } };
              if (cb) cb(r);
              return Promise.resolve(r);
            }
            if (msg && msg.action === 'check-sync-status') {
              if (cb) cb(st);
              return Promise.resolve(st);
            }
            return orig(msg, cb);
          };
          chrome.storage.local.set({ 'github-token': 't' });
        }""", status)

    def _open_modal(self):
        self.page.click("#account-slot")
        self.page.wait_for_timeout(150)

    def _status(self):
        return self.page.evaluate("document.getElementById('github-modal-status').textContent")

    def test_not_connected_static_consistent(self):
        """Без токена: статическая разметка согласована — видна только
        «Подключить» (sync/clear/disconnect скрыты inline в HTML),
        статус «Не подключён»."""
        self._load()
        self._open_modal()
        d = self._modal_state()
        assert d["connect"] != "none", d
        assert d["sync"] == "none", d
        assert d["clear"] == "none", d
        assert d["disconnect"] == "none", d
        assert d["status"] == "Не подключён", d

    def test_token_status_immediate(self):
        """Ядро фикса #1: при токене и pending verify-github статус
        уже «проверяем» (не «Не подключён»), а «Отключить» видна."""
        self._load()
        self.page.evaluate("""() => {
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'verify-github') {
              return Promise.resolve(undefined); // pending: cb не вызывается
            }
            return orig(msg, cb);
          };
          chrome.storage.local.set({ 'github-token': 't' });
        }""")
        self._open_modal()
        d = self._modal_state()
        assert d["status"] == "Подключено · проверяем аккаунт…", d
        assert d["disconnect"] != "none", d

    def test_sync_error_surfaced(self):
        """sync-now вернул ошибку — UI показывает «Ошибка синхронизации: api 404»
        и она НЕ затирается через 3 c."""
        self._load()
        self._mock_connected("synced")
        self._open_modal()
        self.page.wait_for_timeout(100)
        self.page.evaluate("""() => {
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'sync-now') {
              const r = { pulled: false, pushed: false, error: 'api 404' };
              if (cb) cb(r);
              return Promise.resolve(r);
            }
            return orig(msg, cb);
          };
        }""")
        self.page.click("#github-sync-btn")
        self.page.wait_for_timeout(200)
        assert self._status() == "Ошибка синхронизации: api 404", self._status()
        self.page.wait_for_timeout(3500)
        assert self._status() == "Ошибка синхронизации: api 404", self._status()

    def test_sync_error_fallback(self):
        """sync-now без ответа (undefined) — общий «Ошибка синхронизации»."""
        self._load()
        self._mock_connected("synced")
        self._open_modal()
        self.page.wait_for_timeout(100)
        self.page.evaluate("""() => {
          const orig = chrome.runtime.sendMessage.bind(chrome.runtime);
          chrome.runtime.sendMessage = function (msg, cb) {
            if (msg && msg.action === 'sync-now') {
              if (cb) cb(undefined);
              return Promise.resolve(undefined);
            }
            return orig(msg, cb);
          };
        }""")
        self.page.click("#github-sync-btn")
        self.page.wait_for_timeout(200)
        assert self._status() == "Ошибка синхронизации", self._status()

# ==========================================
#  BACKGROUND.JS: DEVICE FLOW — ПОЛЛИНГ + ALARM
# ==========================================

class TestDeviceFlowBackground:
    """background.js: состояние device flow персистится в storage
    (github-device-flow); device-flow-poll — один шаг поллинга; страховка —
    alarm blattam-device-poll (30 c). Выживает смерть MV3 service worker."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        page.goto("about:blank")
        page.evaluate(MOCK_CHROME)

    def _install_fetch_mock(self, token_res=None):
        self.page.evaluate("""(tr) => {
          window.__fetchCalls = [];
          window.__deviceCodeRes = { device_code: 'DC-1', user_code: 'ABCD-1234', verification_uri: 'https://github.com/login/device', verification_uri_complete: 'https://github.com/login/device#ABCD-1234', interval: 5, expires_in: 900 };
          window.__tokenRes = tr || { error: 'authorization_pending' };
          window.fetch = async function (url, opts) {
            window.__fetchCalls.push(String(url));
            let body;
            if (String(url).indexOf('/login/device/code') !== -1) body = window.__deviceCodeRes;
            else if (String(url).indexOf('/login/oauth/access_token') !== -1) body = window.__tokenRes;
            else body = { ok: false };
            return { json: async () => body, ok: true, status: 200 };
          };
        }""", token_res or {"error": "authorization_pending"})

    def _load_bg(self):
        self.page.evaluate(load_file("background.js") + "; 'loaded'")
        self.page.evaluate("""() => {
          const orig = chrome.runtime.getManifest.bind(chrome.runtime);
          chrome.runtime.getManifest = function () {
            return Object.assign({}, orig(), { oauth2: { client_id: 'mock-client' } });
          };
        }""")
    def test_start_stores_state_and_alarm(self):
        self._install_fetch_mock()
        self._load_bg()
        res = call_msg(self.page, "device-flow-start")
        assert res["user_code"] == "ABCD-1234", res
        assert res["interval"] == 5, res
        assert res["expires_at"] > self.page.evaluate("Date.now()"), res
        state = read_local(self.page, "github-device-flow")
        assert state is not None and state["device_code"] == "DC-1", state
        created = json.loads(self.page.evaluate("JSON.stringify(chrome.alarms.created)"))
        assert any(a["name"] == "blattam-device-poll"
                   and (a["info"] or {}).get("periodInMinutes") == 0.5
                   for a in created), created

    def test_poll_pending_keeps_state(self):
        self._install_fetch_mock({"error": "authorization_pending"})
        self._load_bg()
        call_msg(self.page, "device-flow-start")
        res = call_msg(self.page, "device-flow-poll")
        assert res == {"ok": True, "connected": False, "pending": True}, res
        state = read_local(self.page, "github-device-flow")
        assert state is not None and state["device_code"] == "DC-1", state
        assert read_local(self.page, "github-token") is None

    def test_poll_success_stores_token_and_cleans(self):
        self._install_fetch_mock({"access_token": "gh-mock-token"})
        self._load_bg()
        call_msg(self.page, "device-flow-start")
        res = call_msg(self.page, "device-flow-poll")
        assert res.get("connected") is True, res
        assert read_local(self.page, "github-token") == "gh-mock-token"
        assert read_local(self.page, "github-device-flow") is None
        cleared = json.loads(self.page.evaluate("JSON.stringify(chrome.alarms.cleared)"))
        assert "blattam-device-poll" in cleared, cleared

    def test_poll_final_error_sets_auth_error(self):
        self._install_fetch_mock({"error": "access_denied",
                                  "error_description": "The user denied the request"})
        self._load_bg()
        call_msg(self.page, "device-flow-start")
        res = call_msg(self.page, "device-flow-poll")
        assert res.get("connected") is False and res.get("inactive") is True, res
        assert res.get("error") == "The user denied the request", res
        assert read_local(self.page, "github-auth-error") == "The user denied the request"
        assert read_local(self.page, "github-device-flow") is None

    def test_poll_http_error_not_final(self):
        self.page.evaluate("""() => {
          window.__fetchCalls = [];
          window.__deviceCodeRes = { device_code: 'DC-1', user_code: 'ABCD-1234', verification_uri: 'https://github.com/login/device', verification_uri_complete: 'https://github.com/login/device#ABCD-1234', interval: 5, expires_in: 900 };
          window.fetch = async function (url, opts) {
            window.__fetchCalls.push(String(url));
            if (String(url).indexOf('/login/device/code') !== -1) {
              return { json: async () => window.__deviceCodeRes, ok: true, status: 200 };
            }
            return { json: async () => ({ message: 'rate limited' }), ok: false, status: 429 };
          };
        }""")
        self._load_bg()
        call_msg(self.page, "device-flow-start")
        res = call_msg(self.page, "device-flow-poll")
        assert res == {"ok": True, "connected": False, "pending": True, "network": True}, res
        state = read_local(self.page, "github-device-flow")
        assert state is not None and state["device_code"] == "DC-1", state
        assert read_local(self.page, "github-auth-error") is None

    def test_poll_without_state_is_inactive(self):
        self._install_fetch_mock()
        self._load_bg()
        res = call_msg(self.page, "device-flow-poll")
        assert res == {"ok": True, "connected": False, "inactive": True}, res
        calls = json.loads(self.page.evaluate("JSON.stringify(window.__fetchCalls)"))
        assert not any("/login/oauth/access_token" in u for u in calls), calls

    def test_alarm_triggers_poll(self):
        self._install_fetch_mock({"access_token": "gh-alarm-token"})
        self._load_bg()
        call_msg(self.page, "device-flow-start")
        self.page.evaluate("chrome.alarms.onAlarm._listeners[0]({name: 'blattam-device-poll'})")
        self.page.wait_for_timeout(200)
        assert read_local(self.page, "github-token") == "gh-alarm-token"
        assert read_local(self.page, "github-device-flow") is None

    def test_disconnect_clears_flow_state(self):
        self._install_fetch_mock()
        self._load_bg()
        call_msg(self.page, "device-flow-start")
        assert read_local(self.page, "github-device-flow") is not None
        res = call_msg(self.page, "disconnect-github")
        assert res is True, res
        assert read_local(self.page, "github-device-flow") is None
        cleared = json.loads(self.page.evaluate("JSON.stringify(chrome.alarms.cleared)"))
        assert "blattam-device-poll" in cleared, cleared

    def test_poll_slow_down_persists_wait(self):
        self._install_fetch_mock({"error": "slow_down", "interval": 525,
                                  "error_description": "Too many requests have been made in the same timeframe."})
        self._load_bg()
        call_msg(self.page, "device-flow-start")
        res = call_msg(self.page, "device-flow-poll")
        assert res.get("slow_down") is True, res
        assert res.get("wait_ms") == 525000, res
        state = read_local(self.page, "github-device-flow")
        now = self.page.evaluate("Date.now()")
        assert state is not None and state.get("slow_down_until") and state["slow_down_until"] > now, state

    def test_poll_during_slow_down_skips_fetch(self):
        self._install_fetch_mock({"error": "slow_down", "interval": 525,
                                  "error_description": "Too many requests have been made in the same timeframe."})
        self._load_bg()
        call_msg(self.page, "device-flow-start")
        call_msg(self.page, "device-flow-poll")
        before = self.page.evaluate("window.__fetchCalls.filter(u => u.indexOf('/login/oauth/access_token') !== -1).length")
        res = call_msg(self.page, "device-flow-poll")
        after = self.page.evaluate("window.__fetchCalls.filter(u => u.indexOf('/login/oauth/access_token') !== -1).length")
        assert res.get("slow_down") is True, res
        assert res.get("wait_ms") is not None and res["wait_ms"] < 525000, res
        assert after == before, (before, after)
    def test_poll_after_slow_down_window_polls(self):
        self._install_fetch_mock({"error": "authorization_pending"})
        self._load_bg()
        call_msg(self.page, "device-flow-start")
        self.page.evaluate("""() => {
          const s = chrome.storage.local._data['github-device-flow'];
          s.slow_down_until = Date.now() - 1000;
        }""")
        res = call_msg(self.page, "device-flow-poll")
        assert res.get("pending") is True, res
        assert not res.get("slow_down"), res
        calls = self.page.evaluate("window.__fetchCalls.filter(u => u.indexOf('/login/oauth/access_token') !== -1).length")
        assert calls == 1, calls
        state = read_local(self.page, "github-device-flow")
        assert state is not None and "slow_down_until" not in state, state

    def test_start_reuses_active_flow(self):
        self._install_fetch_mock()
        self._load_bg()
        r1 = call_msg(self.page, "device-flow-start")
        r2 = call_msg(self.page, "device-flow-start")
        assert r1["user_code"] == r2["user_code"] == "ABCD-1234", (r1, r2)
        codes = self.page.evaluate("window.__fetchCalls.filter(u => u.indexOf('/login/device/code') !== -1).length")
        assert codes == 1, codes


