class TestThemeInSettings:
    """Переключатель темы — панель «Внешний вид» (rail-кнопка «Тема» удалена)."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self.page_errors = []
        self._on_pageerror = lambda exc: self.page_errors.append(str(exc))
        self.page.on("pageerror", self._on_pageerror)
        yield
        self.page.remove_listener("pageerror", self._on_pageerror)

    def _open(self):
        self.page.locator("#settings-btn").click()
        self.page.wait_for_timeout(100)

    def _inject_real_styles(self):
        # Харнес ставит только body.innerHTML — подгружаем настоящие стили
        theme = load_file("theme.css")
        html = load_file("view.html")
        style = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate(
            "(styles) => { var st = document.createElement('style'); st.textContent = styles; document.head.appendChild(st); }",
            [theme + "\n" + style])

    def test_rail_theme_button_gone(self):
        load_view(self.page)
        assert self.page.evaluate("!!document.getElementById('theme-btn')") is False

    def test_dark_seed_buttons_sync_on_open(self):
        load_view(self.page, theme="dark")
        self._open()
        d = json.loads(self.page.evaluate("""(() => {
          const l = document.getElementById('theme-btn-light');
          const d = document.getElementById('theme-btn-dark');
          return JSON.stringify({
            lightActive: l.classList.contains('active'),
            darkActive: d.classList.contains('active')
          });
        })()"""))
        assert d == {"lightActive": False, "darkActive": True}, d

    def test_onchanged_external_set(self):
        load_view(self.page)
        self._open()
        self.page.evaluate("chrome.storage.local.set({'blattam-theme': 'dark'})")
        self.page.wait_for_timeout(50)
        d = json.loads(self.page.evaluate("""(() => {
          const l = document.getElementById('theme-btn-light');
          const d = document.getElementById('theme-btn-dark');
          return JSON.stringify({
            theme: document.documentElement.dataset.theme,
            lightActive: l.classList.contains('active'),
            darkActive: d.classList.contains('active')
          });
        })()"""))
        assert d == {"theme": "dark", "lightActive": False, "darkActive": True}, d

    def test_palette_changes_with_real_styles(self):
        for theme, body_bg in ((None, "rgb(255, 255, 255)"), ("dark", "rgb(31, 28, 27)")):
            load_view(self.page, theme=theme)
            self._inject_real_styles()
            bg = self.page.evaluate("getComputedStyle(document.body).backgroundColor")
            assert bg == body_bg, (theme, bg)

    def test_i18n_en_theme_section(self):
        load_view(self.page, lang="en")
        self._open()
        d = json.loads(self.page.evaluate("""(() => {
          const h4 = document.querySelector('#theme-section h4');
          return JSON.stringify({
            h4: h4 ? h4.textContent.trim() : null,
            light: document.getElementById('theme-btn-light').textContent.trim(),
            dark: document.getElementById('theme-btn-dark').textContent.trim()
          });
        })()"""))
        assert d == {"h4": "Theme", "light": "Light", "dark": "Dark"}, d

    def test_click_both_buttons_no_pageerrors(self):
        load_view(self.page)
        self._open()
        self.page.locator("#theme-btn-dark").click()
        self.page.locator("#theme-btn-light").click()
        self.page.keyboard.press("Escape")
        self.page.wait_for_timeout(100)
        assert self.page_errors == []
        assert self.page.evaluate("document.documentElement.dataset.theme") == "light"

class TestRailWidths:
    """Волна 4: ширина боковых реек — слайдеры в «Размер и форма»
    (токены --rail-left-w/--rail-right-w, blattam-custom-theme).
    computed gridTemplateColumns — resolved-длины треков (220px 870px 190px на 1280)."""

    TABS = [{"name": f"Вкладка {i}", "url": f"https://example.com/{i}"} for i in range(1, 3)]

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self.page_errors = []
        self._on_pageerror = lambda exc: self.page_errors.append(str(exc))
        self.page.on("pageerror", self._on_pageerror)
        self.page.set_viewport_size({"width": 1280, "height": 900})
        yield
        self.page.remove_listener("pageerror", self._on_pageerror)

    def _inject_css(self):
        # реальный CSS (theme.css + <style> view.html) — для computed-style проверок
        theme = load_file("theme.css")
        html = load_file("view.html")
        style = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate(
            "(() => { const st = document.createElement('style'); st.textContent = "
            + json.dumps(theme + style)
            + "; (document.head || document.documentElement).appendChild(st); })()")

    def _load(self, **kw):
        load_view(self.page, tabs=self.TABS, **kw)
        self._inject_css()
        self.page.wait_for_timeout(120)

    def _grid(self):
        return self.page.evaluate(
            "getComputedStyle(document.querySelector('.workspace')).gridTemplateColumns")

    def _stored(self):
        return self.page.evaluate("chrome.storage.local._data['blattam-custom-theme']")

    def _set_geo(self, cid, val):
        self.page.evaluate(
            "(() => { const i = document.getElementById('cust-geo-' + " + json.dumps(cid)
            + "); i.value = " + json.dumps(str(val))
            + "; i.dispatchEvent(new Event('input', {bubbles: true})); })()")

    def _open(self):
        # открытие настроек — ре-применение applyCustomTheme (актуальные
        # значения слайдеров из токенов темы, view.js @ openSettings)
        self.page.locator("#settings-btn").click()

    def test_defaults_grid_and_controls(self):
        self._load()
        assert self._grid() == "220px 870px 190px"
        self._open()
        assert self.page.evaluate("document.getElementById('cust-geo-railleft').value") == "220"
        assert self.page.evaluate("document.getElementById('cust-geo-railright').value") == "190"
        assert self.page.evaluate("document.getElementById('cust-geo-railleft-val').textContent") == "220px"
        assert self.page.evaluate("document.getElementById('cust-geo-railright-val').textContent") == "190px"
        assert self.page.evaluate(
            "document.querySelector('[data-cust-reset=\"railleft\"]').style.display") == "none"
        assert self.page.evaluate(
            "document.querySelector('[data-cust-reset=\"railright\"]').style.display") == "none"
        assert self._stored() is None
        assert self.page_errors == []

    def test_left_rail_set_live(self):
        self._load()
        self._open()
        self._set_geo("railleft", 260)
        grid = self._grid()
        assert grid == "260px 830px 190px", grid
        assert self._stored() == {"--rail-left-w": "260px"}
        assert self.page.evaluate(
            "document.querySelector('[data-cust-reset=\"railleft\"]').style.display") != "none"
        assert self.page.evaluate("document.getElementById('cust-geo-railleft-val').textContent") == "260px"

    def test_right_rail_set_live(self):
        self._load()
        self._open()
        self._set_geo("railright", 240)
        grid = self._grid()
        assert grid == "220px 820px 240px", grid
        assert self._stored() == {"--rail-right-w": "240px"}

    def test_per_row_reset_left(self):
        self._load(custom_theme={"--rail-left-w": "260px"})
        assert self._grid() == "260px 830px 190px"
        self._open()
        self.page.locator('[data-cust-reset="railleft"]').click()
        assert self._stored() is None
        assert self._grid() == "220px 870px 190px"
        assert self.page.evaluate(
            "document.querySelector('[data-cust-reset=\"railleft\"]').style.display") == "none"

    def test_reset_all_geometry(self):
        self._load(custom_theme={"--rail-left-w": "260px", "--rail-right-w": "240px"})
        self._open()
        self.page.locator("#cust-geo-reset-all").click()
        assert self._stored() is None
        assert self._grid() == "220px 870px 190px"
        assert self.page.evaluate("document.getElementById('cust-geo-railleft-val').textContent") == "220px"
        assert self.page.evaluate("document.getElementById('cust-geo-railright-val').textContent") == "190px"

    def test_persist_across_reload(self):
        self._load(custom_theme={"--rail-left-w": "280px", "--rail-right-w": "250px"})
        assert self._grid() == "280px 750px 250px"
        assert self.page.evaluate("document.getElementById('cust-geo-railleft').value") == "280"
        assert self.page.evaluate("document.getElementById('cust-geo-railright').value") == "250"

    def test_themes_and_i18n_en(self):
        self._load(theme="dark")
        assert self._grid() == "220px 870px 190px"
        self._load(lang="en")
        assert self._grid() == "220px 870px 190px"
        assert self.page.evaluate(
            "document.querySelector('[data-i18n=\"cust_railleft_w\"]').textContent") == "Left rail width"
        assert self.page.evaluate(
            "document.querySelector('[data-i18n=\"cust_railright_w\"]').textContent") == "Right rail width"

# ==========================================
#  VIEW.HTML: СКРОЛЛБАР КОНТЕНТА ОКНА НАСТРОЕК (как у .center, токены --scroll-thumb)
# ==========================================

class TestSettingsScrollbar:
    """Скроллбар #settings-modal .settings-main — тот же тонкий скруглённый,
    что у центральной колонки и правой рейки (токены --scroll-thumb)."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self.page_errors = []
        self._on_pageerror = lambda exc: self.page_errors.append(str(exc))
        self.page.on("pageerror", self._on_pageerror)
        self.page.set_viewport_size({"width": 1280, "height": 900})
        yield
        self.page.remove_listener("pageerror", self._on_pageerror)

    def _inject_real_styles(self):
        # харнес ставит только body.innerHTML — подгружаем настоящие стили
        # (theme.css + <style> view.html), чтобы computed-значения были реальными
        theme = open(f"{EXT_PATH}/theme.css", encoding="utf-8").read()
        html = open(f"{EXT_PATH}/view.html", encoding="utf-8").read()
        style = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate(
            "(() => { const st = document.createElement('style'); st.textContent = "
            + json.dumps(theme + style)
            + "; (document.head || document.documentElement).appendChild(st); })()")

    def _load(self, **kw):
        load_view(self.page, **kw)
        self._inject_real_styles()

    def _open(self):
        self.page.locator("#settings-btn").click()

    def _style_text(self):
        return load_file("view.html").split("<style>", 1)[1].rsplit("</style>", 1)[0]

    def _thumb(self, selector):
        return json.loads(self.page.evaluate("""(sel) => {
          const cs = getComputedStyle(document.querySelector(sel), '::-webkit-scrollbar-thumb');
          return JSON.stringify({bg: cs.backgroundColor, bw: cs.borderTopWidth,
            bs: cs.borderTopStyle, bc: cs.borderTopColor, radius: cs.borderTopLeftRadius});
        }""", [selector]))

    def _rule(self, text, sel):
        i = text.find(sel)
        assert i >= 0, sel
        return text[i:text.find("}", i) + 1]

    def _thumb_eq(self, theme=None):
        self._load(tabs=[{"name": "Вкладка 1", "url": "https://example.com/1"}],
                   **({"theme": theme} if theme else {}))
        self._open()
        sm, ct = self._thumb("#settings-modal .settings-main"), self._thumb(".center")
        if sm["bg"] and sm["bg"] != "rgba(0, 0, 0, 0)":
            assert sm == ct, (sm, ct)
        else:
            # Chromium не возвращает computed для псевдоэлементов скроллбара —
            # проверяем ТЕКСТ правил: общие блоки с теми же токеном и радиусом
            t = self._style_text()
            for sel in (".center::-webkit-scrollbar-thumb",
                        "#settings-modal .settings-main::-webkit-scrollbar-thumb"):
                # оба селектора лежат в ОДНОМ общем правиле — ищем блок по селектору
                m = re.search(r"([^{}]*" + re.escape(sel) + r"[^{}]*)\{([^{}]*)\}", t)
                assert m, sel
                body = m.group(2)
                assert "var(--scroll-thumb)" in body and "border-radius: 999px" in body, (sel, body)
        assert self.page_errors == []

    def test_settings_scrollbar_same_as_center_light(self):
        self._thumb_eq()

    def test_settings_scrollbar_same_as_center_dark(self):
        self._thumb_eq("dark")

    def _width_modern(self, theme=None):
        self._load(tabs=[{"name": "Вкладка 1", "url": "https://example.com/1"}],
                   **({"theme": theme} if theme else {}))
        self._open()
        w = json.loads(self.page.evaluate("""(sel) => {
          const cs = getComputedStyle(document.querySelector(sel), '::-webkit-scrollbar');
          const st = getComputedStyle(document.querySelector(sel));
          return JSON.stringify({width: cs.width, sw: st.scrollbarWidth, sc: st.scrollbarColor});
        }""", ["#settings-modal .settings-main"]))
        if w["width"] == "10px":
            assert w["sw"] == "thin", w
            assert w["sc"], w
        else:
            t = self._style_text()
            r = self._rule(t, "#settings-modal .settings-main::-webkit-scrollbar {")
            assert "width: 10px" in r, r
            r = self._rule(t, "#browser-tabs-list, #settings-modal .settings-main {")
            assert "scrollbar-width: thin" in r and "scrollbar-color: var(--scroll-thumb) transparent" in r, r
        assert self.page_errors == []

    def test_settings_scrollbar_width_and_modern_props_light(self):
        self._width_modern()

    def test_settings_scrollbar_width_and_modern_props_dark(self):
        self._width_modern("dark")

    def test_settings_scrollbar_only_tokens(self):
        t = self._style_text()
        hex6 = re.compile(r"#[0-9a-fA-F]{6}\b")
        found = 0
        for m in re.finditer(r"([^{}]+)\{([^{}]*)\}", t):
            sel, body = m.group(1).strip(), m.group(2)
            if "settings-main" in sel and ("::-webkit-scrollbar" in sel or "scrollbar-width" in body):
                assert not hex6.search(body), (sel, body)
                found += 1
                if sel.rstrip().endswith("::-webkit-scrollbar-thumb") or "scrollbar-width" in body:
                    assert "var(--scroll-thumb)" in body, (sel, body)
        assert found >= 5, found


# ==========================================
#  VIEW.JS: ПРЕСЕТЫ (профили внешнего вида)
# ==========================================

class TestPresetProfiles:
    """«Пресеты»: снапшот шести ключей внешнего вида (blattam-presets +
    blattam-active-preset, local); активный сбрасывается при ручном изменении
    (сверка значений в syncActivePreset)."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self._errors = []
        page.on("pageerror", self._on_err)
        self._orig_viewport = page.viewport_size
        page.set_viewport_size({"width": 1280, "height": 900})
        yield
        assert not self._errors, self._errors
        page.remove_listener("pageerror", self._on_err)
        page.set_viewport_size(self._orig_viewport)

    def _on_err(self, err):
        self._errors.append(str(err))

    def _inject_real_styles(self):
        # реальный CSS (theme.css + <style> view.html) — для computed-style проверок
        theme = open(f"{EXT_PATH}/theme.css", encoding="utf-8").read()
        html = open(f"{EXT_PATH}/view.html", encoding="utf-8").read()
        style = html.split("<style>", 1)[1].rsplit("</style>", 1)[0]
        self.page.evaluate(
            "(() => { const st = document.createElement('style'); st.textContent = "
            + json.dumps(theme + style)
            + "; (document.head || document.documentElement).appendChild(st); })()")

    def _open(self):
        self.page.locator("#settings-btn").click()

    def _data(self):
        return {"theme": "light", "customTheme": None, "bgImage": None,
                "bgImageLeft": None, "bgImageRight": None, "tabColor": None}

    def _list_names(self):
        return json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('#preset-list .preset-name')]"
            ".map(e => e.textContent))"))

    def test_preset_section_first_and_empty(self):
        load_view(self.page)
        self._open()
        assert self.page.evaluate("document.getElementById('preset-section') !== null")
        titles = json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('#settings-modal .settings-section-title')]"
            ".map(el => el.textContent.trim()))"))
        assert titles[0] == "Пресеты"
        assert self.page.evaluate("document.querySelectorAll('#preset-list .preset-empty').length") == 1
        assert self.page.evaluate("document.querySelectorAll('#preset-list .preset-row').length") == 0

    def test_save_new_preset(self):
        load_view(self.page, theme="dark", tab_color="#8a6d5c", custom_theme={"--bg": "#abcdef"})
        self._open()
        self.page.locator("#preset-name-input").fill("Тёмный")
        self.page.locator("#preset-save-btn").click()
        presets = self.page.evaluate("chrome.storage.local._data['blattam-presets']")
        assert len(presets) == 1
        assert presets[0]["name"] == "Тёмный"
        assert presets[0]["id"].startswith("p")
        assert presets[0]["data"] == {"theme": "dark", "customTheme": {"--bg": "#abcdef"},
                                      "bgImage": None, "bgImageLeft": None, "bgImageRight": None,
                                      "tabColor": "#8a6d5c"}
        assert self.page.evaluate("chrome.storage.local._data['blattam-active-preset']") == presets[0]["id"]
        assert self._list_names() == ["Тёмный"]
        assert self.page.evaluate("document.querySelectorAll('#preset-list .preset-badge').length") == 1
        assert self.page.evaluate(
            "document.querySelector('#preset-list .preset-badge').textContent") == "активен"
        assert self.page.locator("#preset-name-input").input_value() == ""

    def test_save_auto_name(self):
        load_view(self.page)
        self._open()
        self.page.locator("#preset-save-btn").click()  # имя не введено
        presets = self.page.evaluate("chrome.storage.local._data['blattam-presets']")
        assert len(presets) == 1
        assert presets[0]["name"] == "Пресет 1"

    def test_apply_preset(self):
        p = {"id": "pa", "name": "A", "createdAt": 1, "data": self._data()}
        load_view(self.page, theme="dark", tab_color="#123456",
                  custom_theme={"--bg": "#111111"}, presets=[p], active_preset="pa")
        self._inject_real_styles()
        self._open()
        self.page.locator("#preset-list .preset-apply").first.click()
        self.page.wait_for_timeout(50)
        # data.theme 'light' пишется как значение; остальные null — ключи сняты
        assert self.page.evaluate("chrome.storage.local._data['blattam-theme']") == "light"
        assert self.page.evaluate("'blattam-custom-theme' in chrome.storage.local._data") is False
        assert self.page.evaluate("'blattam-tab-color' in chrome.storage.local._data") is False
        assert self.page.evaluate("chrome.storage.local._data['blattam-active-preset']") == "pa"
        # body — светлый --bg (#ffffff)
        assert self.page.evaluate("getComputedStyle(document.body).backgroundColor") == "rgb(255, 255, 255)"

    def test_manual_change_clears_active(self):
        p = {"id": "pm", "name": "M", "createdAt": 1, "data": self._data()}
        load_view(self.page, presets=[p], active_preset="pm")
        self._open()
        assert self.page.evaluate("document.querySelectorAll('#preset-list .preset-badge').length") == 1
        # ручное изменение одного из шести ключей — «активен» снимается
        self.page.evaluate("chrome.storage.local.set({'blattam-tab-color': '#123456'})")
        self.page.wait_for_timeout(50)
        assert self.page.evaluate("'blattam-active-preset' in chrome.storage.local._data") is False
        # модалка открыта — список перерисован: без бейджа и подсветки
        assert self.page.evaluate("document.querySelectorAll('#preset-list .preset-badge').length") == 0
        assert self.page.evaluate("document.querySelectorAll('#preset-list .preset-row.active').length") == 0

    def test_delete_preset(self):
        p1 = {"id": "p1", "name": "One", "createdAt": 1, "data": self._data()}
        p2 = {"id": "p2", "name": "Two", "createdAt": 2, "data": self._data()}
        load_view(self.page, presets=[p1, p2], active_preset="p1")
        self._open()
        self.page.evaluate("document.querySelectorAll('#preset-list .preset-del')[0].click()")
        ids = json.loads(self.page.evaluate(
            "JSON.stringify(chrome.storage.local._data['blattam-presets'].map(x => x.id))"))
        assert ids == ["p2"]
        # активный удалён — ключ снят
        assert self.page.evaluate("'blattam-active-preset' in chrome.storage.local._data") is False

    def test_presets_persist_across_reload(self):
        p1 = {"id": "p1", "name": "First", "createdAt": 1, "data": self._data()}
        load_view(self.page, presets=[p1], active_preset="p1")
        self._open()
        self.page.locator("#preset-name-input").fill("Свой")
        self.page.locator("#preset-save-btn").click()
        stored = self.page.evaluate("chrome.storage.local._data['blattam-presets']")
        assert [x["name"] for x in stored] == ["First", "Свой"]
        # «релоад» с тем же хранилищем — пресеты не теряются
        load_view(self.page, presets=stored, active_preset=stored[1]["id"])
        self._open()
        assert self._list_names() == ["First", "Свой"]
        assert self.page.evaluate("document.querySelectorAll('#preset-list .preset-row.active').length") == 1

    def test_preset_with_backgrounds(self):
        b = "data:image/png;base64,iVBORw0KGgo="
        data = {"theme": "light", "customTheme": None, "bgImage": b,
                "bgImageLeft": b, "bgImageRight": b, "tabColor": "#112233"}
        load_view(self.page, bg=b, bg_left=b, bg_right=b, tab_color="#112233",
                  presets=[{"id": "pb", "name": "BG", "createdAt": 1, "data": data}],
                  active_preset="pb")
        self._inject_real_styles()
        # сброс вида — снять все четыре ключа
        self.page.evaluate(
            "chrome.storage.local.remove(['blattam-bg-image', 'blattam-bg-image-left', "
            "'blattam-bg-image-right', 'blattam-tab-color'])")
        self.page.wait_for_timeout(50)
        self._open()
        self.page.evaluate("document.querySelectorAll('#preset-list .preset-apply')[0].click()")
        self.page.wait_for_timeout(50)
        assert self.page.evaluate("chrome.storage.local._data['blattam-bg-image']") == b
        assert self.page.evaluate("chrome.storage.local._data['blattam-bg-image-left']") == b
        assert self.page.evaluate("chrome.storage.local._data['blattam-bg-image-right']") == b
        assert self.page.evaluate("chrome.storage.local._data['blattam-tab-color']") == "#112233"
        # фон снова на body и обеих рейках
        for el in ("document.body", "document.getElementById('rail-left')",
                   "document.getElementById('rail-right')"):
            assert self.page.evaluate(
                "getComputedStyle(" + el + ").backgroundImage").startswith('url("data:image/png')

    def test_i18n_en(self):
        p = {"id": "p1", "name": "First", "createdAt": 1, "data": self._data()}
        load_view(self.page, lang="en", presets=[p], active_preset="p1")
        self._open()
        assert self.page.evaluate(
            "document.querySelector('#preset-section .settings-section-title').textContent.trim()") == "Presets"
        assert self.page.evaluate(
            "document.getElementById('preset-name-input').placeholder") == "Preset name"
        btns = json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('#preset-list .preset-row button')]"
            ".map(b => b.textContent.trim()))"))
        assert btns == ["Apply", "Delete"]
        assert self.page.evaluate(
            "document.querySelector('#preset-list .preset-badge').textContent") == "active"
# ==========================================
#  VIEW.JS: ГОРЯЧИЕ КЛАВИШИ — настройка хоткеев в настройках
# ==========================================

class TestHotkeys:
    """Настройки → «Горячие клавиши»: 10 действий, blattam-hotkeys (local).
    Захват: клик по строке → нажать комбинацию (Esc — отмена); × — снять все;
    «Сбросить всё» — дефолты. Дефолты = прежнее поведение клавиатуры.
    Захват проверяется РЕАЛЬНЫМ вводом (page.keyboard) — capture-слушатель
    живёт на window."""

    ACTIONS = ["next", "prev", "open", "delete", "search", "selectAll",
               "newSpace", "newGroup", "theme", "settings"]
    RU_ROW_LABELS = ["Далее (вниз)", "Назад (вверх)", "Открыть вкладку",
                     "Удалить вкладку", "Фокус на поиске", "Выбрать все вкладки",
                     "Новое пространство", "Новая группа", "Переключить тему",
                     "Открыть настройки"]
    EN_ROW_LABELS = ["Next (down)", "Previous (up)", "Open tab", "Delete tab",
                     "Focus search", "Select all tabs", "New space",
                     "New group", "Toggle theme", "Open settings"]

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        self.page_errors = []
        self._on_pageerror = lambda exc: self.page_errors.append(str(exc))
        self.page.on("pageerror", self._on_pageerror)
        yield
        self.page.remove_listener("pageerror", self._on_pageerror)

    TABS = [
        {"name": "A", "url": "https://a.com"},
        {"name": "B", "url": "https://b.com"},
        {"name": "C", "url": "https://c.com"},
    ]

    def _open_hotkeys(self):
        self.page.click("#settings-btn")
        self.page.wait_for_timeout(150)
        self.page.locator("#settings-modal .settings-nav-item[data-section='hotkeys']").click()
        self.page.wait_for_timeout(150)

    def _rows(self):
        return json.loads(self.page.evaluate("""(() => {
          const rows = {};
          document.querySelectorAll('#hk-section .hk-box').forEach((box) => {
            const val = box.querySelector('.hk-val');
            const clear = box.querySelector('.hk-clear');
            rows[box.dataset.action] = {
              text: val ? val.textContent.trim() : null,
              clearVisible: clear ? clear.style.display !== 'none' : false
            };
          });
          return JSON.stringify(rows);
        })()"""))

    def _hk_storage(self):
        return json.loads(self.page.evaluate(
            "(chrome.storage.local._data['blattam-hotkeys'] === undefined) ? 'null' : "
            "JSON.stringify(chrome.storage.local._data['blattam-hotkeys'])"))

    def test_pane_in_nav(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        d = json.loads(self.page.evaluate("""(() => {
          const items = [...document.querySelectorAll('#settings-modal .settings-nav-item')];
          return JSON.stringify({
            count: items.length,
            sections: items.map(b => b.dataset.section),
            labels: items.map(b => b.textContent.trim())
          });
        })()"""))
        assert d["count"] == 6, d
        assert d["sections"] == ["appearance", "general", "hotkeys", "experimental", "faq", "about"], d
        assert d["labels"][2] == "Горячие клавиши", d
        assert self.page.evaluate(
            "document.getElementById('settings-pane-hotkeys').style.display") != "none"

    def test_default_bindings_display(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        rows = self._rows()
        assert rows["next"]["text"] == "↓ · →", rows
        assert rows["prev"]["text"] == "↑ · ←", rows
        assert rows["open"]["text"] == "Enter", rows
        assert rows["delete"]["text"] == "Del · Backspace", rows
        assert rows["search"]["text"] == "/", rows
        assert rows["selectAll"]["text"] == "Ctrl+A", rows
        for a in ("newSpace", "newGroup", "theme", "settings"):
            assert rows[a]["text"] == "не назначено", rows
            assert rows[a]["clearVisible"] is False, rows
        assert rows["open"]["clearVisible"] is True, rows
        # ключ ещё не записан — дефолты в памяти
        assert self._hk_storage() is None

    def test_row_labels_ru_order(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        labels = json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('#hk-section .hk-lbl')].map(e => e.textContent.trim()))"))
        assert labels == self.RU_ROW_LABELS, labels

    def test_capture_new_group_and_fires(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        self.page.locator(".hk-box[data-action='newGroup']").click()
        assert self.page.evaluate(
            "document.querySelector(\".hk-box[data-action='newGroup']\").classList.contains('hk-armed')")
        self.page.keyboard.press("F2")
        self.page.wait_for_timeout(150)
        stored = self._hk_storage()
        assert stored["newGroup"] == ["F2"], stored
        rows = self._rows()
        assert rows["newGroup"]["text"] == "F2", rows
        # Esc закрывает модалку настроек (захват уже снят)
        self.page.keyboard.press("Escape")
        self.page.wait_for_timeout(150)
        assert not self.page.evaluate(
            "document.getElementById('settings-modal').classList.contains('open')")
        # F2 открывает модалку создания группы
        self.page.keyboard.press("F2")
        self.page.wait_for_timeout(150)
        assert self.page.evaluate(
            "document.getElementById('space-modal').classList.contains('open')")
        assert self.page.evaluate(
            "document.getElementById('modal-title').textContent.trim()") == "Новая группа"

    def test_capture_escape_cancels(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        self.page.locator(".hk-box[data-action='newSpace']").click()
        self.page.keyboard.press("Escape")
        self.page.wait_for_timeout(150)
        # модалка настроек осталась открыта, захват снят, storage не тронут
        assert self.page.evaluate(
            "document.getElementById('settings-modal').classList.contains('open')")
        assert self.page.evaluate(
            "document.querySelector(\".hk-box[data-action='newSpace']\").classList.contains('hk-armed')") is False
        assert self._hk_storage() is None

    def test_capture_modifier_combo(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        self.page.locator(".hk-box[data-action='search']").click()
        self.page.keyboard.down("Control")
        self.page.keyboard.press("k")
        self.page.keyboard.up("Control")
        self.page.wait_for_timeout(150)
        stored = self._hk_storage()
        assert stored["search"] == ["/", "ctrl+k"], stored
        rows = self._rows()
        assert rows["search"]["text"] == "/ · Ctrl+K", rows

    def test_capture_dedup(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        self.page.locator(".hk-box[data-action='open']").click()
        self.page.keyboard.press("Enter")
        self.page.wait_for_timeout(150)
        stored = self._hk_storage()
        assert stored["open"] == ["Enter"], stored

    def test_clear_binding(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        self.page.locator(".hk-box[data-action='open'] .hk-clear").click()
        self.page.wait_for_timeout(150)
        stored = self._hk_storage()
        assert stored["open"] == [], stored
        rows = self._rows()
        assert rows["open"]["text"] == "не назначено", rows
        # Enter больше не открывает активную вкладку
        self.page.keyboard.press("Escape")  # закрыть настройки (и сброс)
        self.page.wait_for_timeout(150)
        self.page.keyboard.press("ArrowDown")
        self.page.wait_for_timeout(100)
        assert self.page.evaluate(
            "document.querySelectorAll('.tab-card.kbd-active').length") == 1
        self.page.keyboard.press("Enter")
        self.page.wait_for_timeout(150)
        assert self.page.evaluate("window.lastMessage") is None

    def test_rebind_new_space_fires(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        self.page.locator(".hk-box[data-action='newSpace']").click()
        self.page.keyboard.press("F5")
        self.page.wait_for_timeout(150)
        stored = self._hk_storage()
        assert stored["newSpace"] == ["F5"], stored
        self.page.keyboard.press("Escape")
        self.page.wait_for_timeout(150)
        self.page.keyboard.press("F5")
        self.page.wait_for_timeout(150)
        assert self.page.evaluate(
            "document.getElementById('space-modal').classList.contains('open')")
        assert self.page.evaluate(
            "document.getElementById('modal-title').textContent.trim()") == "Новое пространство"

    def test_select_all_hotkey(self):
        load_view(self.page, tabs=self.TABS)
        self.page.keyboard.down("Control")
        self.page.keyboard.press("a")
        self.page.keyboard.up("Control")
        self.page.wait_for_timeout(150)
        assert self.page.evaluate("document.querySelectorAll('.tab-select:checked').length") == 3
        self.page.keyboard.press("Escape")  # сброс
        self.page.wait_for_timeout(150)
        assert self.page.evaluate("document.querySelectorAll('.tab-select:checked').length") == 0

    def test_search_focus_hotkey(self):
        load_view(self.page, tabs=self.TABS)
        self.page.keyboard.press("/")
        self.page.wait_for_timeout(100)
        assert self.page.evaluate("document.activeElement.id") == "search"

    def test_theme_toggle_hotkey(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        self.page.locator(".hk-box[data-action='theme']").click()
        self.page.keyboard.press("F3")
        self.page.wait_for_timeout(150)
        assert self._hk_storage()["theme"] == ["F3"]
        self.page.keyboard.press("Escape")
        self.page.wait_for_timeout(150)
        self.page.keyboard.press("F3")
        self.page.wait_for_timeout(150)
        assert self.page.evaluate("chrome.storage.local._data['blattam-theme']") == "dark"
        assert self.page.evaluate("document.documentElement.dataset.theme") == "dark"

    def test_settings_hotkey_opens_modal(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        self.page.locator(".hk-box[data-action='settings']").click()
        self.page.keyboard.press("F4")
        self.page.wait_for_timeout(150)
        assert self._hk_storage()["settings"] == ["F4"]
        self.page.keyboard.press("Escape")
        self.page.wait_for_timeout(150)
        assert not self.page.evaluate(
            "document.getElementById('settings-modal').classList.contains('open')")
        self.page.keyboard.press("F4")
        self.page.wait_for_timeout(150)
        assert self.page.evaluate(
            "document.getElementById('settings-modal').classList.contains('open')")

    def test_reset_all(self):
        load_view(self.page, tabs=self.TABS)
        self._open_hotkeys()
        self.page.locator(".hk-box[data-action='newSpace']").click()
        self.page.keyboard.press("F5")
        self.page.wait_for_timeout(100)
        self.page.locator(".hk-box[data-action='open'] .hk-clear").click()
        self.page.wait_for_timeout(100)
        assert self._hk_storage()["open"] == []
        self.page.locator("#hk-reset-all").click()
        self.page.wait_for_timeout(150)
        assert self._hk_storage() is None
        rows = self._rows()
        assert rows["open"]["text"] == "Enter", rows
        assert rows["newSpace"]["text"] == "не назначено", rows

    def test_storage_persist(self):
        load_view(self.page, tabs=self.TABS, hotkeys={"newSpace": ["F5"], "open": ["Enter"]})
        self._open_hotkeys()
        rows = self._rows()
        assert rows["newSpace"]["text"] == "F5", rows
        assert rows["open"]["text"] == "Enter", rows

    def test_i18n_en(self):
        load_view(self.page, tabs=self.TABS, lang="en")
        self._open_hotkeys()
        nav = json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('#settings-modal .settings-nav-item')].map(b => b.textContent.trim()))"))
        assert "Hotkeys" in nav, nav
        labels = json.loads(self.page.evaluate(
            "JSON.stringify([...document.querySelectorAll('#hk-section .hk-lbl')].map(e => e.textContent.trim()))"))
        assert labels == self.EN_ROW_LABELS, labels
        rows = self._rows()
        assert rows["newSpace"]["text"] == "unassigned", rows
        assert rows["selectAll"]["text"] == "Ctrl+A", rows

    def test_no_pageerrors_both_themes(self):
        for theme in (None, "dark"):
            self.page_errors = []
            load_view(self.page, tabs=self.TABS, theme=theme)
            self._open_hotkeys()
        assert self.page_errors == [], self.page_errors


# ==========================================
#  C2.7: Безопасное открытие — только http/https
# ==========================================

class TestSafeOpenUrl:
    """background.js С2.7: javascript:/data:/chrome:// и непарсящиеся URL не
    открываются (open-one / open-many / openTab); https открывается (регрессия)."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        page.goto("about:blank")
        page.evaluate(MOCK_CHROME)
        page.evaluate(load_file("background.js") + "; 'loaded'")

    def _created(self):
        return json.loads(self.page.evaluate("JSON.stringify(chrome.tabs.createdTabs)"))

    def test_open_one_javascript_blocked(self):
        send_msg(self.page, "open-one", url="javascript:alert(1)")
        assert self._created() == []

    def test_open_one_data_blocked(self):
        send_msg(self.page, "open-one", url="data:text/html;base64,PHNjcmlwdD4=")
        assert self._created() == []

    def test_open_one_chrome_blocked(self):
        send_msg(self.page, "open-one", url="chrome://settings")
        assert self._created() == []

    def test_open_many_filters_unsafe(self):
        """open-many: небезопасный URL в массиве отбрасывается, валидный открывается (неактивно)."""
        send_msg(self.page, "open-many", urls=["https://ok.example", "javascript:alert(1)"])
        created = self._created()
        assert len(created) == 1, created
        assert created[0]["url"] == "https://ok.example"
        assert created[0]["active"] is False

    def test_open_tab_by_index_data_blocked(self):
        """openTab по индексу: вкладка с data:-URL не открывается; соседняя https — открывается."""
        self.page.evaluate("""
          chrome.storage.local._data['blattam-tabs'] = [
            {name: 'D', url: 'data:text/html,x', spaceId: 'sp'},
            {name: 'H', url: 'https://ok.example', spaceId: 'sp'}
          ];
        """)
        send_msg(self.page, "open", index=0)
        assert self._created() == []
        send_msg(self.page, "open", index=1)
        created = self._created()
        assert len(created) == 1 and created[0]["url"] == "https://ok.example", created

    def test_open_one_https_regression(self):
        send_msg(self.page, "open-one", url="https://example.com")
        created = self._created()
        assert len(created) == 1 and created[0]["url"] == "https://example.com", created


# ==========================================
#  C2.8: Валидация импорта (view.js)
# ==========================================

class TestImportValidation:
    """view.js С2.8: валидация импорта ДО применения: >5000 вкладок / url не
    http(s) или >2048 / name >200 / comment >1000 — alert и ничего не
    записывается; валидный файл импортируется (регрессия)."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page

    def _load(self, confirm=False):
        load_view(self.page, tabs=[], confirm=confirm)
        self.page.evaluate("""() => {
          window.__alerts = [];
          window.alert = (m) => { window.__alerts.push(m); };
        }""")
        self.page.wait_for_timeout(80)

    def _import(self, data):
        payload = json.dumps(data, ensure_ascii=False)
        self.page.evaluate("""(payload) => {
          var input = document.getElementById('import-input');
          var dt = new DataTransfer();
          dt.items.add(new File([payload], 'blatt-tabs-backup.json', {type: 'application/json'}));
          input.files = dt.files;
          input.dispatchEvent(new Event('change'));
        }""", payload)
        self.page.wait_for_timeout(250)

    def _alerts(self):
        return json.loads(self.page.evaluate("JSON.stringify(window.__alerts)"))

    def test_invalid_url_alerts_and_storage_untouched(self):
        self._load()
        self._import({"blatt-tabs": True, "tabs": [
            {"name": "Evil", "url": "javascript:alert(1)"}]})
        alerts = self._alerts()
        assert any("Невалидный URL" in a for a in alerts), alerts
        assert read_storage_raw(self.page, "blattam-tabs") == []

    def test_too_many_tabs_alerts(self):
        self._load()
        self._import({"blatt-tabs": True, "tabs": [
            {"name": f"T{i}", "url": f"https://t{i}.example"} for i in range(5001)]})
        alerts = self._alerts()
        assert any("Слишком много вкладок" in a for a in alerts), alerts
        assert read_storage_raw(self.page, "blattam-tabs") == []

    def test_url_too_long_alerts(self):
        self._load()
        bad = "https://long.example/" + "a" * 2040  # 2063 символов > 2048
        self._import({"blatt-tabs": True, "tabs": [
            {"name": "Long", "url": bad}]})
        alerts = self._alerts()
        assert any("Невалидный URL" in a for a in alerts), alerts
        assert read_storage_raw(self.page, "blattam-tabs") == []

    def test_name_too_long_alerts(self):
        self._load()
        self._import({"blatt-tabs": True, "tabs": [
            {"name": "N" * 201, "url": "https://ok.example"}]})
        alerts = self._alerts()
        assert any("Слишком длинное имя" in a for a in alerts), alerts
        assert read_storage_raw(self.page, "blattam-tabs") == []

    def test_comment_too_long_alerts(self):
        self._load()
        self._import({"blatt-tabs": True, "tabs": [
            {"name": "C", "url": "https://ok.example", "comment": "c" * 1001}]})
        alerts = self._alerts()
        assert any("Слишком длинный комментарий" in a for a in alerts), alerts
        assert read_storage_raw(self.page, "blattam-tabs") == []

    def test_valid_file_imports(self):
        self._load(confirm=True)
        self._import({"blatt-tabs": True, "tabs": [
            {"name": "A", "url": "https://a.example"},
            {"name": "B", "url": "https://b.example"}]})
        assert self._alerts() == []
        tabs = read_storage_raw(self.page, "blattam-tabs")
        assert sorted(t["url"] for t in tabs) == ["https://a.example", "https://b.example"], tabs


# ==========================================
#  C2.9: blattam-data-updated-at (метка свежести синка)
# ==========================================

class TestSyncUpdatedAt:
    """background.js С2.9: blattam-data-updated-at — метка свежести данных
    синка: пишется при изменении keysToSync, САМ НЕ в keysToSync (нет цикла —
    его запись не создаёт sync-alarm), getSyncPayload читает сохранённое
    значение (не Date.now() в момент чтения), applySyncPayload проставляет
    из payload.updatedAt."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        page.goto("about:blank")
        page.evaluate(MOCK_CHROME)
        page.evaluate(load_file("background.js") + "; 'loaded'")

    def _sync_push_alarms(self):
        created = json.loads(self.page.evaluate("JSON.stringify(chrome.alarms.created)"))
        return [a for a in created if a["name"] == "blattam-sync-push"]

    def test_write_data_key_creates_marker(self):
        """Запись в keysToSync (blattam-tabs) — в local появляется blattam-data-updated-at (число)."""
        self.page.evaluate("delete chrome.storage.local._data['blattam-data-updated-at']")
        self.page.evaluate("chrome.storage.local.set({'blattam-tabs': [{name: 'A', url: 'https://a.com'}]})")
        val = self.page.evaluate("chrome.storage.local._data['blattam-data-updated-at']")
        assert isinstance(val, (int, float)) and val > 0, val

    def test_marker_key_not_in_keys_to_sync(self):
        """Запись самой метки НЕ создаёт sync-alarm; запись blattam-tabs — создаёт."""
        n0 = len(self._sync_push_alarms())
        self.page.evaluate("chrome.storage.local.set({'blattam-data-updated-at': 1})")
        assert len(self._sync_push_alarms()) == n0, self._sync_push_alarms()
        self.page.evaluate("chrome.storage.local.set({'blattam-tabs': [{name: 'B', url: 'https://b.com'}]})")
        assert len(self._sync_push_alarms()) == n0 + 1, self._sync_push_alarms()

    def test_get_sync_payload_reads_saved_value(self):
        """Посаженная метка возвращается как есть (12345), а не Date.now() в момент чтения."""
        self.page.evaluate("chrome.storage.local._data['blattam-data-updated-at'] = 12345")
        payload = self.page.evaluate("getSyncPayload()")
        assert payload["updatedAt"] == 12345, payload

    def test_apply_sync_payload_stamps_from_payload(self):
        """applySyncPayload({updatedAt: 777}) — в local метка == 777 (собственная
        запись blattam-tabs её не перетирает); push-аларм от изменения данных всё же создаётся."""
        n0 = len(self._sync_push_alarms())
        self.page.evaluate("""applySyncPayload({
          tabs: [{name: 'R', url: 'https://r.com', spaceId: 'sp1'}],
          settings: {}, updatedAt: 777
        })""")
        assert self.page.evaluate("chrome.storage.local._data['blattam-data-updated-at']") == 777
        assert len(self._sync_push_alarms()) == n0 + 1, self._sync_push_alarms()


# ==========================================
#  C2.10: Пустой / битый gist (pullFromGitHub + check-sync-status)
# ==========================================

class TestEmptyGist:
    """background.js С2.10: пустой gist (clear-cloud записал '') — НЕ ошибка
    (JSON.parse('') не падаем); битый payload (tabs не массив) — не
    применяется, bad-payload; check-sync-status с пустым raw — 'unknown';
    нормальный gist — pulled: true (регрессия)."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        page.goto("about:blank")
        page.evaluate(MOCK_CHROME)

    def _load_bg(self):
        self.page.evaluate(load_file("background.js") + "; 'loaded'")

    def _seed(self):
        # ТОЛЬКО после старта SW: стартовая purgeStaleScopeToken удаляет
        # токен без маркера blattam-auth-scope
        self.page.evaluate("""() => {
          chrome.storage.local._data['github-token'] = 't';
          chrome.storage.local._data['blattam-auth-scope'] = 'gist-1';
          chrome.storage.local._data['blattam-gist-id'] = 'g1';
        }""")

    def _mock_get(self, body):
        self.page.evaluate("""(body) => {
          window.__fetchCalls = [];
          window.__fetchTimeoutMs = 50;
          window.fetch = async function (url, opts) {
            window.__fetchCalls.push({ url: String(url), method: (opts && opts.method) || 'GET' });
            return { ok: true, status: 200, json: async () => body };
          };
        }""", body)

    def test_pull_empty_content_not_error(self):
        """Пустой content в gist — {ok: true, pulled: false}, не ошибка."""
        self._mock_get({"files": {"sync.json": {"content": ""}}})
        self._load_bg()
        self._seed()
        res = self.page.evaluate("pullFromGitHub()")
        assert res == {"ok": True, "pulled": False}, res

    def test_pull_bad_payload(self):
        """Битый payload (tabs не массив) — {ok: false, error: 'bad-payload'}, вкладки не тронуты."""
        self._mock_get({"files": {"sync.json": {"content": '{"tabs": 42}'}}})
        self._load_bg()
        self._seed()
        res = self.page.evaluate("pullFromGitHub()")
        assert res == {"ok": False, "error": "bad-payload"}, res
        assert read_local(self.page, "blattam-tabs") is None

    def test_check_sync_status_empty_unknown(self):
        self._mock_get({"files": {"sync.json": {"content": ""}}})
        self._load_bg()
        self._seed()
        res = call_msg(self.page, "check-sync-status")
        assert res == "unknown", res

    def test_pull_normal_gist_regression(self):
        """Нормальный gist ({'tabs': [...], updatedAt}) — pulled: true, удалённые вкладки применены."""
        self._mock_get({"files": {"sync.json": {"content": json.dumps({
            "tabs": [{"name": "R", "url": "https://r.com", "spaceId": "sp1"}],
            "updatedAt": 111
        })}}})
        self._load_bg()
        self._seed()
        res = self.page.evaluate("pullFromGitHub()")
        assert res == {"ok": True, "pulled": True}, res
        tabs = read_local(self.page, "blattam-tabs") or []
        assert any(t["url"] == "https://r.com" for t in tabs), tabs


# ==========================================
#  C2.11: Debounced push на chrome.alarms
# ==========================================

class TestSyncDebounceAlarm:
    """background.js С2.11: дебаунс пуша на chrome.alarms (pending setTimeout
    умирал вместе с MV3 service worker): triggerDebouncedPush создаёт аларм
    blattam-sync-push; аларм будит SW — pushToGitHub + clear; в путях синка
    нет setTimeout/'syncTimer' (статика)."""

    @pytest.fixture(autouse=True)
    def _setup(self, page):
        self.page = page
        page.goto("about:blank")
        page.evaluate(MOCK_CHROME)
        self.page.evaluate("""() => {
          window.__fetchCalls = [];
          window.__fetchTimeoutMs = 50;
          window.fetch = async function (url, opts) {
            window.__fetchCalls.push({ url: String(url), method: (opts && opts.method) || 'GET' });
            return { ok: true, status: 200, json: async () => ({ id: 'g1' }) };
          };
        }""")
        self.page.evaluate(load_file("background.js") + "; 'loaded'")
        self.page.evaluate("""() => {
          chrome.storage.local._data['github-token'] = 't';
          chrome.storage.local._data['blattam-auth-scope'] = 'gist-1';
          chrome.storage.local._data['blattam-gist-id'] = 'g1';
        }""")

    def test_trigger_creates_sync_alarm(self):
        self.page.evaluate("triggerDebouncedPush()")
        created = json.loads(self.page.evaluate("JSON.stringify(chrome.alarms.created)"))
        assert any(a["name"] == "blattam-sync-push"
                   and (a["info"] or {}).get("delayInMinutes") == 5000 / 60000
                   for a in created), created

    def test_alarm_pushes_and_clears(self):
        """onAlarm('blattam-sync-push'): fetch к api.github.com/gists + clear аларма."""
        self.page.evaluate("chrome.alarms.onAlarm._listeners[0]({name: 'blattam-sync-push'})")
        self.page.wait_for_timeout(300)
        calls = json.loads(self.page.evaluate("JSON.stringify(window.__fetchCalls)"))
        assert any("api.github.com/gists" in c["url"] and c["method"] == "PUT" for c in calls), calls
        cleared = json.loads(self.page.evaluate("JSON.stringify(chrome.alarms.cleared)"))
        assert "blattam-sync-push" in cleared, cleared

    def test_no_settimeout_in_sync_debounce(self):
        """Статика: в triggerDebouncedPush нет setTimeout, 'syncTimer' в файле нет."""
        src = load_file("background.js")
        assert "syncTimer" not in src
        i = src.index("function triggerDebouncedPush")
        body = src[i:src.index("\n}", i)]
        assert "setTimeout" not in body, body
        assert "chrome.alarms.create(SYNC_ALARM" in body, body
